-- Growth Q and A: the real 34 questions, from Luke's artifact database.
--
-- Giant had 6 questions and no ask counts, so the list could not be ranked and every
-- row showed a caret instead of a number. Luke's own board has 24 questions counted
-- across 108 calls (588 asks), plus the 10 Clear answers shown as "AI answer" -- 34
-- rows, which is what his screen shows.
--
-- Read out of the artifact's own database (collection "qa"), not retyped.
--
-- SPLIT ON PURPOSE. The 588 call examples are 364KB. growth_settings is fetched whole
-- on every Growth page load, and the Q and A screen shows three examples by default,
-- so they live in their own key that the boot query now excludes and the Q and A
-- screen fetches when it opens. qa itself stays 25KB.

insert into growth_settings (key, value) values ('qa', $json${"items": [{"a": "No guarantee, and say so. What he promises is daily work and honesty. Work starts in 2 to 5 days after payment, ads usually go live in about 7 to 10 days, and the client will know in month one or two. If it is not working after about two weeks they say so and pivot.", "better": "I will not promise a number. Anyone who does is guessing. What I can promise is daily work and full honesty. You see the first ads live in about a week and real data in month one. If it is not working by week two, I will tell you and change the plan. We only keep clients who make money, so I have every reason to make it work. \n we have a great team", "calls": 37, "feel": "Will I waste my money?", "id": "results", "n": 65, "q": "Can you guarantee results? How fast will I see them?", "theme": "Results and timeline", "tricks": ["Do not promise ROAS", "Give the timeline in days", "Say we only keep clients by making them money", "Promise honesty and effort instead"], "why": "Honest beats hopeful. Say there is no guarantee, then show the plan, the timeline and the exit. Trust goes up when you do not promise."}, {"a": "Google Ads is $1,500 a month (up to $15,000 ad spend, about 10% of spend above that). Meta Ads is $1,800 to $2,000. SEO is $2,400 to $2,500. Google plus Meta together is $2,500 to $3,000. Everything (Rocket Fuel) is $5,000. Ad spend is on top and paid straight to Google or Meta. No setup fee.", "better": "Our Google Ads management is $1,500 a month. That covers daily management, building the campaigns, proper conversion tracking and small landing page fixes. There is no setup fee. Your ad spend goes straight to Google from your own card. Does that work for you?", "calls": 50, "feel": "Is this fair, and will I be surprised later?", "id": "price", "n": 62, "q": "What does it cost?", "theme": "Pricing and budget", "tricks": ["Say what is included before the price", "Close with a question, not silence", "Use the same numbers every call"], "why": "Most people want one number and a reason it is fair. Lead with the outcome, give the price, then say what is included and that there is no setup fee."}, {"a": "A Stripe payment link on autopay, a short contract confirming they own the accounts, and a 15 to 30 minute onboarding form that goes to the team. Matthew Overbay (general manager) then calls. The team audits and researches competitors, presents a plan in about a week, then launches and adjusts every week or two.", "better": "Five simple steps. One, I send you a payment link. Two, you fill out a 15 minute form. Three, Matthew, our general manager, calls you. Four, in about a week we show you the full plan before anything goes live. Five, we launch and adjust every week. You only do steps one and two.", "calls": 47, "feel": "How hard is it to get started, and what will I have to do?", "id": "onboard", "n": 53, "q": "What happens after I say yes? How does onboarding work?", "theme": "How it works", "tricks": ["Number the steps", "Name a real person (Matthew)", "Show the plan before going live", "Make step one tiny"], "why": "Make it feel like five easy steps. People say yes faster when the next step is small and clear."}, {"a": "Google Ads is buyer intent and the fastest predictable way to get leads and calls. Meta suits products and trust based offers, not usually B2B. SEO is slow, three to six months, and also now covers AI search and Maps. Start with the channel that fits the buyer, test small, then add.", "better": "It depends on how people find you today. If they search for what you sell, Google Ads is the fastest and most predictable. If people find you by browsing, Meta is strong. SEO is the long game, about three to six months. I would start with one, prove it works, then add the next.", "calls": 35, "feel": "What is the right first move for my situation?", "id": "channel", "n": 45, "q": "Should I do Google Ads, Meta or SEO?", "theme": "Services and fit", "tricks": ["Ask how customers find them", "Explain Google as buyer intent", "Say SEO is the long game", "Start with one channel"], "why": "Ask first. How do their customers find them today? Then recommend, and start small."}, {"a": "No annual contract. It is a three month minimum, paid one month at a time, with a 10 day exit. The contract says the client owns every account and asset, and ReachGiant never holds anything hostage.", "better": "No long contract. It is three months because the first month is setup and testing, and real data shows up in month two. You pay one month at a time. If it is not for you, email me in the first week and we part ways. You own every account, always.", "calls": 42, "feel": "What if I get stuck and cannot get out?", "id": "contract", "n": 44, "q": "Is there a contract? How long do I have to commit?", "theme": "Contracts and commitment", "tricks": ["Explain why three months", "Offer the 10 day exit up front", "Say the client owns the accounts"], "why": "Say the exit before they ask. It removes the fear and it sounds confident."}, {"a": "Bare minimum is $1,000 a month in ad spend, $1,500 is typical, and $2,500 to $3,000 is a better start. Start light, test for the first month or two, then scale only when ROAS or profit on ad spend is there. Ad spend stays in the client's own account on their own card.", "better": "It depends on what a new customer is worth to you. If a sale is $2,000, then $1,500 a month is enough to start testing. $2,500 gets you answers faster. We start light, watch the numbers for the first month, and only raise it when it pays back.", "calls": 32, "feel": "How much will this really cost me in total?", "id": "adspend", "n": 39, "q": "How much should I spend on ads? Is my budget enough?", "theme": "Tracking and ad spend", "tricks": ["Ask what a customer is worth first", "Say start light and prove it", "Remind them the spend stays in their account"], "why": "Do not give a number cold. Ask what a customer is worth, then work backwards. It makes your number feel earned."}, {"a": "They never niched. About 45 to 50 clients across ecommerce and service businesses, roughly 4 years as ReachGiant. Name the closest real example (painters, movers, flooring, Apple watch seller, scooters). If there is no exact match, say so and explain the plan is the same: seasonality, locations, keywords, competitors.", "better": "We have not done exactly your type of business, and I would rather be honest about that. We have worked with painters, movers and flooring companies. The plan is the same: your seasons, your areas, your keywords and your competitors. I can send you a short video from a client with a similar setup. Would that help?", "calls": 30, "feel": "Will you understand my business?", "id": "industry", "n": 33, "q": "Have you worked with a business like mine?", "theme": "Proof and experience", "tricks": ["Be honest about no exact match", "Name the closest real example", "Offer a video or a reference", "Say the plan is the same every time"], "why": "Do not pretend to match exactly. Say what is close, then prove the plan travels. Then offer a real reference."}, {"a": "A team of 10 to 12, US based and salaried, with Luke as owner and Matthew Overbay as general manager in New York. About four people touch an account: strategist, Google and Meta techs, designer, and a developer for tracking.", "better": "You get a team, not one freelancer. We are 12 people, all in the US. Matthew Overbay, our general manager in New York, leads your account. A Google specialist, a Meta specialist, a designer and a developer for tracking all work on it. You talk to them directly.", "calls": 26, "feel": "Am I buying a real team or one person?", "id": "team", "n": 32, "q": "Who will actually work on my account? Where is your team?", "theme": "Who does the work", "tricks": ["Give the team size", "Name the general manager", "List the roles"], "why": "Give numbers and names. A real team beats a promise."}, {"a": "Reviews are public: hundreds of Google reviews, Fiverr Pro agency, Upwork top 1%. The team is US based with salaried specialists. Accounts stay in the client's name. The first two months decide whether they keep the client, so results come first. Admit that not every campaign works.", "better": "That is a fair worry, and it happens a lot in this industry. Three things protect you. Your accounts stay in your name, so we can never take them. You can leave on 10 days notice. And you can read our reviews online first. We only keep clients by making them money, so I would rather earn your trust slowly.", "calls": 26, "feel": "I have been burned before. Why would you be different?", "id": "trust", "n": 32, "q": "Why should I trust you? Past agencies burned me.", "theme": "Trust and past agencies", "tricks": ["Agree before you answer", "Give three clear protections", "Point to public reviews", "Never sound defensive"], "why": "When someone says they were burned, agree first. Never defend. Then show proof and the exit."}, {"a": "Small landing page fixes (nav, CTAs, duplicate pages) are included in Google Ads management. Full websites and branding are separate quotes: nothing under $10,000, average about $25,000, websites alone from $10,000 and a $1,500 workshop is available.", "better": "Small landing page fixes are included in your management. A full new site is a separate project. Most start around $10,000, and the average is about $25,000. I would not start there unless the site is the real problem. Let us run ads first, see what the numbers say, then decide.", "calls": 29, "feel": "Will my website hold this back?", "id": "web", "n": 31, "q": "Do you build websites and landing pages? What does it cost?", "theme": "Services and fit", "tricks": ["Say small fixes are included", "Be clear on project prices", "Suggest ads first if the budget is tight"], "why": "Do not market a site that does not convert. Say it kindly, then offer a quote or a smaller step."}, {"a": "The $1,500 is built for real work by a US team, so it does not go far below. For small or new businesses Luke has dropped Google Ads to $1,000 to $1,300 and the vault to $1,500 to $2,000. The bare minimum ad spend is $1,000. Under about $1,000 total, point them to a trusted freelancer instead.", "better": "I hear you, and I want this to work at your size. Normally it is $1,500 a month. For a new business, I can do $1,000 if we start this week. I want to show you what a real team does with a smaller budget. I would just ask you to keep that between us. Fair?", "calls": 26, "feel": "I want this to work, but I am afraid I cannot afford it.", "id": "lower", "n": 27, "q": "Can you do it cheaper? My budget is small.", "theme": "Pricing and budget", "tricks": ["Give a reason for the discount", "Tie it to deciding today", "Ask them to keep it private", "Offer one discount only, then hold it"], "why": "The best deals so far came when the discount had a reason and a deadline. Never drop the price without something in return."}, {"a": "Google Tag Manager and Analytics on every account, conversion API through Stape for Meta, and a bot blocker (Clixie) for spam. They track calls, forms and drop offs, and report ROAS or profit on ad spend. For service businesses the client reports closes, or they use a lead to close ratio.", "better": "We set tracking up first, before anything else. We track calls, forms and sales in Google and Meta, and we block bot traffic. Then we show you in plain words: what you spent, what you made, and what we will do next. If it is not tracked, we do not scale it.", "calls": 21, "feel": "How will I know it is working and not made up?", "id": "tracking", "n": 24, "q": "How do you track results and make sure leads are real?", "theme": "Tracking and ad spend", "tricks": ["Say tracking is included", "Mention bot blocking", "Promise plain words", "Only scale what is proven"], "why": "Tracking is a selling point. Say it is included and that you will explain it simply."}, {"a": "Current answer: they only do Google and Meta, SEO, plus web and branding. They no longer offer cold email or LinkedIn, do not do CRM or automations, do not make UGC, and do not do one time audits or consulting. Training is rare and priced separately. Refer out cleanly.", "better": "That is not something we do, and I would rather tell you now than waste your money. We do Google Ads, Meta ads, SEO and websites. For the rest, I can point you to someone good. If you want the ads side, I am happy to help.", "calls": 17, "feel": "Can you solve my exact problem?", "id": "notdo", "n": 19, "q": "Can you also do [cold email, CRM, UGC, one time audit, training]?", "theme": "Services and fit", "tricks": ["Say no quickly and kindly", "Say what you do best", "Offer a referral"], "why": "A fast, kind no builds trust. Say what you do best, then point them somewhere good."}, {"a": "Custom to the client. Email replies usually within a couple of hours, a booking link for calls, a strategy call after payment and a second one a week later. Reports are short Loom videos explaining spend, what is working and the plan, not big PDFs.", "better": "You pick how involved you want to be. Most clients get a short Loom video from us, about ten minutes, showing what we did, what worked and what is next. No giant PDFs. Email us anytime and we reply within a couple of hours. We can also hop on a call whenever you want.", "calls": 17, "feel": "Will I be left in the dark?", "id": "comms", "n": 18, "q": "How will we communicate and how will you report?", "theme": "How it works", "tricks": ["Offer Loom videos", "Give a reply time", "Let them choose how involved to be"], "why": "Sell the easy part: you will always know what is happening, in plain words."}, {"a": "Google Ads, Meta Ads, SEO, plus web and branding, with about 12 people and 45 to 50 clients across ecommerce and service businesses. They say honestly when someone is not a fit.", "better": "We run Google and Meta ads and SEO for businesses that already make sales and want more. Tell me a bit about your business and what a good result looks like in a year. Then I will tell you straight if we are the right team or if someone else is a better fit.", "calls": 10, "feel": "Will you actually understand my business?", "id": "fit", "n": 11, "q": "What do you do, and am I a good fit?", "theme": "Services and fit", "tricks": ["Ask before you pitch", "Promise a straight answer", "Make it about their goal"], "why": "Curiosity beats a pitch. Ask first, then answer with honesty."}, {"a": "Manual outreach and guest posts for backlinks, with a plan, workbooks and monthly reporting. Cold email only makes sense when the offer, market and reputation line up, and it starts at around $4,500.", "better": "Fair question, there is a lot of junk out there. Everything is done by hand. We pick real sites in your field, write real content, and send one to one messages. Nothing is automated. You see every link we earn each month. If your offer is not ready for it, I will tell you early. Want me to show you an example?", "calls": 7, "feel": "Show me it is real and not spammy.", "id": "outbound", "n": 11, "q": "How do link building and cold email actually work?", "theme": "How it works", "tricks": ["Agree there is junk out there", "Show the work visibly", "Promise an early honest answer"], "why": "Acknowledge the distrust, make the work visible, and promise honesty."}, {"a": "An in house designer and video editor turn the client's photos and footage into ads. They do not film new content or make UGC, and they avoid throwaway AI images.", "better": "You do not need to be a creator. Send us what you already have, like product photos, a phone video or screenshots. Our designer and editor turn that into ads. I will also tell you which extra content would help most. Does that feel doable?", "calls": 10, "feel": "Will I have to create everything myself?", "id": "creative", "n": 10, "q": "Who makes the ads, videos and images?", "theme": "Who does the work", "tricks": ["Make their part feel small", "Name the exact thing you do not do", "Offer a clear next step"], "why": "People fear extra work. Show them the first step is tiny, then be clear about the one thing you do not do."}, {"a": "No free audits, since a proper review takes five to ten hours. Work starts once they sign. Luke offers a quick look or a short overview, and the plan comes in the first week.", "better": "I get it, you want to see something first. A real audit takes our team five to ten hours, so we do not give it away free. What I can do is take a quick look now and tell you the two biggest things I see. And in week one you see the full plan before anything goes live. If you are not happy, you can leave with 10 days notice.", "calls": 7, "feel": "I want to see proof before I commit.", "id": "audit", "n": 7, "q": "Can I get an audit, a plan or a quote first?", "theme": "Services and fit", "tricks": ["Give a small taste now", "Explain why not, kindly", "Lower risk with the exit"], "why": "Respect the request, say why not, then give something real on the spot and lower the risk."}, {"a": "They can run ads in other languages with AI translation and target by radius, zip code or country. Luke advised focusing on the words people use to search rather than only locations.", "better": "Yes. We have run campaigns in other countries. We translate carefully and target by country, city or radius. Often the smartest move is to start with the one market that has your best customers, prove it works, then add the next. Which country is your best customer in today?", "calls": 5, "feel": "Will you understand my market?", "id": "intl", "n": 5, "q": "Do you work in other countries and languages?", "theme": "How it works", "tricks": ["Say yes plainly", "Start with the best market", "Ask where customers are now"], "why": "Say yes, then give a calm strategy: start with the best market."}, {"a": "No revenue share, only management fees. No free work and no splitting payment. Occasional performance deals have been done where sales are provable, but the price stays the same. Monthly billing means they are never paying three months up front.", "better": "We do not do revenue share. It gets messy to track. What keeps you safe is the 10 day exit and billing one month at a time. If it is not working, you stop. That is the same protection, without the complicated math.", "calls": 5, "feel": "Can we share the risk?", "id": "perf", "n": 5, "q": "Can you work on performance, revenue share or a free trial?", "theme": "Pricing and budget", "tricks": ["Do not work for free", "Offer the exit as the safety net", "Keep billing monthly"], "why": "Redirect from risk to the exit. They want safety, not free work."}, {"a": "Flat retainers, no revenue share. In one case he offered about $1,000 for each Google Ads client referred. He is fine working beside other agencies on different channels.", "better": "I like how you think. We keep a flat monthly fee so things stay simple and fair. But I like working with partners. If you bring us a client, I will thank you properly, and we can work alongside your team. Tell me how you picture it, and we can find a version that works for both of us.", "calls": 3, "feel": "Is there something in this for both of us?", "id": "partner", "n": 4, "q": "Can we partner, split work or do a referral deal?", "theme": "Pricing and budget", "tricks": ["Say yes to the relationship", "Hold the price structure", "Invite them to shape it"], "why": "Be warm, hold the structure, and invite them to design the details with you."}, {"a": "They are used to restricted brands. As a Google partner they use long tail keywords as a workaround, check copy with AI, and keep an approval sheet so the client can accept or reject ads.", "better": "That is a stressful spot, and you are not the first. We work with restricted brands often. We check what the platforms allow before writing a single ad, use safer, longer keyword phrases, and keep a shared sheet where you approve every ad first. You stay in control of your own account. What happened the last time an ad got flagged?", "calls": 4, "feel": "I have been banned or flagged before and I am afraid of it happening again.", "id": "restricted", "n": 4, "q": "Can you advertise my restricted or regulated product?", "theme": "Services and fit", "tricks": ["Normalize the problem", "Show the safety process", "Let them tell the story"], "why": "Empathy first, then a clear process that shows control, and a question that lets them tell the story."}, {"a": "Leads can flow almost anywhere with Zapier or Make. They do not work inside CRMs or answer phones, and fast follow up is the client's job.", "better": "Yes. We send every lead straight into your CRM through Zapier, so nothing gets lost. Then your team does the follow up. The faster you call back, the better the ads look, so aim for within five minutes. What CRM do you use today?", "calls": 3, "feel": "I do not want good leads to slip through the cracks.", "id": "crm", "n": 4, "q": "Can leads go into my CRM, and who follows up?", "theme": "How it works", "tricks": ["Name the fear before the tool", "Give one simple rule (call in five minutes)", "Ask what they use today"], "why": "Answer the real fear (lost leads), then hand over one simple rule they can act on."}, {"a": "Luke agreed that training an internal team can be a good option, but said it takes time and doing it well is hard.", "better": "Doing it yourself can work. The honest trade is this: you save the fee, but you spend the learning time, usually a few months and some wasted ad spend. If time is tight, I would hire us for three months and we teach your team as we go. What matters more right now, saving cash or saving time?", "calls": 3, "feel": "Am I wasting money by hiring someone?", "id": "diy", "n": 3, "q": "Should I try it myself first or train my own team?", "theme": "Services and fit", "tricks": ["Validate their idea", "Name the real trade off", "Ask what matters most"], "why": "Respect their option, show the real trade off, and let them choose."}, {"a": "", "ai": true, "better": "ReachGiant helps customers find you and choose you. We run Google Ads, Facebook and Instagram ads, and SEO. We also do AI search, so you show up when people ask ChatGPT or Perplexity. And we build your brand and your website, so people land on you, trust you, and buy.", "calls": 0, "feel": "", "id": "ai-what", "n": 0, "q": "What does ReachGiant do?", "theme": "Services and fit", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "Google Ads, Meta ads, SEO, AI search, branding, and web development. Most people start with one thing that fits, then add more once it is working.", "calls": 0, "feel": "", "id": "ai-services", "n": 0, "q": "What services do you offer?", "theme": "Services and fit", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "We are an incredible team, and we do excellent work. Our reputation speaks for itself.", "calls": 0, "feel": "", "id": "ai-choose", "n": 0, "q": "Why should I choose you?", "theme": "Proof and experience", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "We cater to you. We communicate over email, Zoom, and Loom videos, and whatever you need, we do. Communication is our biggest strength.", "calls": 0, "feel": "", "id": "ai-talk", "n": 0, "q": "How do you communicate?", "theme": "How it works", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "Everything is on our pricing page at reachgiant.com/pricing. Take a look, and I can walk you through what fits your goals.", "calls": 0, "feel": "", "id": "ai-cost", "n": 0, "q": "How much does it cost?", "theme": "Pricing and budget", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "Setup takes about 7 days. Once you say yes, we get everything ready in that time, and you see the full plan before anything goes live.", "calls": 0, "feel": "", "id": "ai-long", "n": 0, "q": "How long does it take?", "theme": "Results and timeline", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "It is three simple steps. First, I send you a payment link. Second, you fill in a short onboarding form, about 15 minutes. Third, Matthew calls you and we get started. You can start with one channel and add more later.", "calls": 0, "feel": "", "id": "ai-forward", "n": 0, "q": "How do I move forward?", "theme": "How it works", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "No. It is a three month minimum, billed one month at a time. If it is not right for you, you can leave with 10 days notice. The ad accounts stay in your name the whole time.", "calls": 0, "feel": "", "id": "ai-contract", "n": 0, "q": "Is there a long contract?", "theme": "Contracts and commitment", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "No, and I will not promise a number, because anyone who does is guessing. What I can promise is daily work and full honesty. If something is not working after about two weeks, I will tell you straight and change the plan.", "calls": 0, "feel": "", "id": "ai-guarantee", "n": 0, "q": "Can you guarantee results?", "theme": "Results and timeline", "tricks": [], "why": ""}, {"a": "", "ai": true, "better": "You get a team. Matthew Overbay leads it. Behind him are Google and Meta specialists, a designer for the ads, and a developer who sets up the tracking, so the work is never on one person.", "calls": 0, "feel": "", "id": "ai-team", "n": 0, "q": "Who will actually work on my account?", "theme": "Who does the work", "tricks": [], "why": ""}]}$json$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();

insert into growth_settings (key, value) values ('qa_examples', $json${"byId": {"adspend": [{"a": "Luke said budgets must be raised strategically, around 7 percent a day on Google and similar on Facebook, because the algorithms take whatever you give them and you scale off data.", "better": "That is a really common story, and it is not your fault, you were trying to help it grow. Going from 75 to 250 in one jump makes the algorithm start over, so the sales quality drops. We raise about 7 percent at a time and only when the numbers are healthy. Would it help if I showed you how we would step it up?", "call": "Jermaine Fowler", "good": true, "q": "Why did my ads tank when I raised the budget from 75 to 250 a day?", "s": 119, "trick": "Take the blame off them", "url": "https://fathom.video/calls/226527595"}, {"a": "Luke said a really good start would be a $2,000 ad spend, bringing the total to about $5,000, and the ad account stays on her own card.", "better": "For a strong start, I would plan about $2,000 a month in ad spend on top of our $3,000 package, so about $5,000 total. It stays in your own ad account and you can stop it any time. We do not need to spend it all at once, we can start smaller and grow once we see what pays back. Does that range feel workable?", "call": "Tiffani", "good": true, "q": "What budget would we need for ads if we go with the Klaviyo and Meta option?", "s": 1519, "trick": "Give a number and a safety", "url": "https://fathom.video/calls/318560045"}, {"a": "Luke said clients spend from 1,000 to 100,000 a month, 1,500 of ad spend is a good starting point, and they scale only when the return is there.", "better": "Starting from zero is actually a great place to be, because we can do it the right way. I would start with about 1,500 a month in ad spend and plan on three months. That is enough for real data without risking much. Then you can show your board exactly what it earned and ask for more. Does that feel doable?", "call": "Chloe Puig", "good": true, "q": "What budget do you recommend for us to start with, since we are starting from zero?", "s": 1473, "trick": "Tie the budget to their goal", "url": "https://fathom.video/calls/264491733"}, {"a": "Matthew explained it is up to 15 percent total per week, per campaign, only when metrics look good, because doubling budget on conversion bidding can double the cost per sale.", "better": "Good question, because this is where most accounts get hurt. We raise spend about 15 percent a week and only when your return stays above your 3x line. If we jumped faster, Google would struggle to find enough buyers and your cost per sale could double. Does a steady climb like that feel right to you?", "call": "Ali Kamel", "good": true, "q": "You said 15 percent of what ad spend, scaled each week?", "s": 1462, "trick": "Explain the why behind the rule", "url": "https://fathom.video/calls/827514516"}, {"a": "Luke said the team would need four or five days to give an exact answer, but he would start with about $2,000 on each platform and offered a $2,500 fee with a micro Google budget.", "better": "I will not guess a fake number. Here is what I can say: if each player is worth about $1,000, then 100 players is $100,000 of value, so a few thousand in ads is reasonable to test. We start small and scale only on proof. Would you like us to build the real math after a short research week?", "call": "Mike Worden", "good": true, "q": "What would I need to spend to add 100 players over six months?", "s": 1485, "trick": "Use their lifetime value", "url": "https://fathom.video/calls/831260309"}, {"a": "Luke recommended starting with about 2k on Google and 2k on Facebook, scaling slowly as booked jobs come in, and said they would fix the missing call to action.", "better": "I would start with 2000 on Google and 2000 on Facebook. That is enough to learn what works without risking too much. We will also add a clear call button to your site in the first days. When jobs book, we raise the budget slowly. Does that feel safe for a new business?", "call": "Garret Ashton", "good": true, "q": "Is there a recommended ad spend to start with when the website has no call to action?", "s": 2944, "trick": "Give one clear starting number", "url": "https://fathom.video/calls/228223662"}, {"a": "Brian said they would scale only with the client's approval and would show the data first, and mentioned weekly video reports.", "better": "We only raise your budget when the numbers say it is safe, and never without asking you. I will send you the data and one clear reason, like the return we are seeing, before any change. It is your money, so you decide. Does that feel like the right level of control?", "call": "Purepiel", "good": true, "q": "If one ad does really well, will you scale the budget or keep it the same?", "s": 2493, "trick": "Give them the final say", "url": "https://fathom.video/calls/272300366"}, {"a": "Luke said start with a reasonable amount, that her 3,000 to 3,500 pounds is fine, and under 1,500 is too low to compete, and they scale only when profitable.", "better": "Your current spend of about 3,000 is a good start, so we do not need to raise it. The goal is to make it profitable first, then grow it step by step. Below 1,500 is usually too small to learn from. Would you like me to look at your account and tell you what I see?", "call": "Joyce", "good": true, "q": "How much Google Ads budget is appropriate to spend?", "s": 1809, "trick": "Fix profit before raising spend", "url": "https://fathom.video/calls/322118977"}, {"a": "Brian said the prices are fixed and ad spend is up to them, and that the rate stays the same as they scale.", "better": "Yes, the fee stays at $2,500 no matter how much you spend on ads. I would rather you scale only when the numbers prove it, so I will always show you the data before we raise spend. That keeps us on the same side. Does a flat fee help with how you plan your budget?", "call": "Dylan Taylor", "good": true, "q": "Is there a limit on spend for the $2,500 price, so if we spend $100,000 a month is it the same rate?", "s": 1804, "trick": "Show we are on their side", "url": "https://fathom.video/calls/273322525"}, {"a": "Luke said yes, it is a good starting point, noted it is US dollars not pounds, and said she can raise it later depending on how many leads she wants.", "better": "For your business, yes, $1,000 is a good start. You sell projects worth thousands, so one or two new clients covers the cost. We can raise the budget when you want more leads. Just so you know, it is in US dollars, about 800 pounds. Does that feel comfortable?", "call": "Alexandra Bailey", "good": true, "q": "Is $1,000 on Google enough to get things going?", "s": 1193, "trick": "Tie spend to one client's value", "url": "https://fathom.video/calls/527818977"}, {"a": "Luke asked Sam's budget, Sam said about $2,000 a month, and Luke said they could start with a minimum of $2K a month in ad spend.", "better": "Yes, the fee and the ad spend are two separate things. Our fee pays for the team, and the ad money goes straight to Google. With a high price product I like to start near $2,000 a month so the test has a fair chance. Is that a number that feels safe for you?", "call": "Sam Daoud", "good": true, "q": "Do I pick a package and then add two to three thousand for ads?", "s": 1024, "trick": "Split fee from ad spend", "url": "https://fathom.video/calls/551904290"}, {"a": "Luke said a minimum of about $1,500, better $2,500 to $3,000, and that they have clients from $1,200 up to a quarter of a million a month.", "better": "I would not go under $1,500, and $2,500 to $3,000 gives us enough to learn fast. The goal is to prove leads come in and you can close them, then grow. You have already spent about $4,000 a month, so that is not a big jump. Does that range feel okay?", "call": "Amy N Neighbors", "good": true, "q": "What ad spend do you want me to put in each month?", "s": 1915, "trick": "Use their own past spend", "url": "https://fathom.video/calls/485151651"}, {"a": "Luke said it depends, a thousand is the bare minimum, maybe 1,500, and spend should follow how much in sales it brings.", "better": "Fair question. I do not like going below $1,000 a month, because there is not enough data to learn from. For you, $1,500 to $2,000 is a good test, and we raise it only when the sales support it. Does that range work next to what you spend now?", "call": "Mathieu Bolle", "good": true, "q": "What is the minimum ad budget per month?", "s": 939, "trick": "Give a floor and a reason", "url": "https://fathom.video/calls/545661967"}, {"a": "Luke said he would want at least 2,000 dollars to test properly, 1,500 to 3,000 is the range to dip toes in, and you scale with ROI so you do not need 10k.", "better": "Good thinking. We start where your budget is, around 2,000 to 3,000, and only raise it when the numbers show it will pay back. You will never be pushed to spend more just because. Does it feel good to grow the budget only when we have proof?", "call": "David Marcyniuk", "good": true, "q": "If we need more ad budget to test more things, how would that work?", "s": 1206, "trick": "Promise growth only with proof", "url": "https://fathom.video/calls/231509507"}, {"a": "Luke said to start with their current 2,000 to 2,500, because under 1,000 would not allow testing, and to scale only with data.", "better": "I would start where you are, around 2,000 to 2,500 a month. Under 1,000 we cannot test enough to learn anything. We will not scale anything without data, and in a few weeks we will know whether to go up or down. Does that range feel doable?", "call": "Shiv Patel", "good": true, "q": "What ad spend would you recommend for a company our size?", "s": 836, "trick": "Give a number and a reason", "url": "https://fathom.video/calls/242052539"}, {"a": "Brian said a solid starting ad spend on Facebook is about 1,000 a month and you can scale up later if needed.", "better": "I can help you with a number to ask for. A good start is 1,000 a month in ad spend plus our fee. I would ask your partners for two to three months, and promise them clear numbers like sign ups. Shall I help you put that into one sentence?", "call": "Erin Rosenstock", "good": true, "q": "What monthly amount should I ask my partners to give, since I am not sure what is needed?", "s": 474, "trick": "Help them make the ask", "url": "https://fathom.video/calls/262474173"}, {"a": "Matthew said the account was at about 775 dollars a day and they could bump it 15 percent right away, then adjust week to week by campaign.", "better": "You're at about 775 a day right now, so I would start there and nudge it up 15 percent. If a campaign dips, we hold for a few days before pushing again. I'll send you the numbers each week so you always know where we are. Sound fair?", "call": "Ali Kamel", "good": true, "q": "Where do you want to start the baseline of spend?", "s": 1523, "trick": "Start from their real number", "url": "https://fathom.video/calls/827514516"}, {"a": "Luke said start with $100 a day on Meta, as low as $50 if needed, and not under $1,500 to $2,000 a month, with three thousand being fantastic.", "better": "A good start is $100 a day on Meta, which is about $3,000 a month. We can go to $50 a day, but learning is slower. In the first weeks we check your return, and we only scale what works. Does that give you a number for your CEO?", "call": "Ivona", "good": true, "q": "What should our ad budget be per day?", "s": 1067, "trick": "Give a number they can repeat", "url": "https://fathom.video/calls/481051622"}, {"a": "Luke said no worries, Matthew will be in touch all the time, and they can adjust week by week and month by month.", "better": "That is normal for a garden center. Just tell Matthew when you want to ramp up and we change the budget within days. I would plan lower in February and higher in March and April. Want to sketch a rough monthly plan together?", "call": "Hailey Baird", "good": true, "q": "Our budget changes by season. How will we tell you when to spend more?", "s": 612, "trick": "Normalize it, offer a plan", "url": "https://fathom.video/calls/512674658"}, {"a": "Luke said they usually ask for a minimum of 1000 and never go under that, with 1000 to 1500 the best range. He said a good return is about 2 to 2.5 times, and it can range from 0.8 to 15.", "better": "I like to start at around 1000 to 1500 a month, so we have enough data to learn from. You said you want to break even first, so we will start there and only raise it when the numbers prove it. Does that feel comfortable?", "call": "Mcbride", "good": true, "q": "How much ad spend do you want to see to get results?", "s": 960, "trick": "Tie spend to their goal", "url": "https://fathom.video/calls/241078094"}, {"a": "Luke said they cap the plan at 10,000 because some clients spend 100,000 and larger campaigns need a different tier.", "better": "Bigger budgets take more hours to run well, so we move them to a higher tier so your account never gets less attention. For you, 10,000 is plenty of room to grow. Does that sound about right for where you want to be?", "call": "Jeroen Reuven Bours", "good": true, "q": "Why do you cap it at 10 thousand in ad spend?", "s": 345, "trick": "Explain the why behind a rule", "url": "https://fathom.video/calls/259216207"}, {"a": "Luke said a $1,000 minimum ad budget, not including the management fee, with the fee at 1,500 a month.", "better": "We like to see at least $1,000 a month of ad spend so Google has enough data to learn. Our fee is on top of that. For you, I can do $1,000 for the fee. Does $1,000 of ad spend plus our fee fit what you have in mind?", "call": "Cesar Diaz", "good": true, "q": "What is the minimum budget you do for Google?", "s": 594, "trick": "Separate fee from ad spend", "url": "https://fathom.video/calls/860109475"}, {"a": "Megan suggested $1,000 to $1,500 on Google and about $1,000 on Meta for ad spend, plus the management fee, and not starting below $1,000.", "better": "Great that you are open to investing. I would start with about $1,000 on Google and $1,000 on Meta, plus our fee, and see which one works best. Then we put more into the winner. Does a test like that feel right?", "call": "Kristina Shumi", "good": true, "q": "How much budget should I set aside if I try both Google and Meta?", "s": 1030, "trick": "Start small, scale the winner", "url": "https://fathom.video/calls/284134646"}, {"a": "Luke said there is nothing extra to pay Google for SEO, though manual backlink outreach can sometimes cost something.", "better": "Right, you never pay Google for SEO traffic, that is the beauty of it. The $2,400 covers our work. Sometimes a good article placement costs a small fee, and I would always tell you first. Does that make sense?", "call": "Stefan Gutowski", "good": true, "q": "Do I have to pay anything extra for SEO, or is it all optimization?", "s": 1010, "trick": "Clear answer, flag small extras", "url": "https://fathom.video/calls/293071198"}, {"a": "Luke said they cap by monthly spend, such as 2000, and daily spend can vary, and told him not to buy accounts.", "better": "We set a monthly cap you choose, and we pace it day by day. If you say 2000, we will not go over. One tip, please do not buy accounts, you can lose them with no support. Does a monthly cap work for you?", "call": "Anyro", "good": true, "q": "Would we have an issue with a daily spend limit on a new account?", "s": 1498, "trick": "Give a tip that protects them", "url": "https://fathom.video/calls/227623273"}, {"a": "Luke said $2,000 is for Google Ads only, about $1,000 management plus $1,000 ad spend, while adding SEO moves it to the $3,000 to $3,500 range.", "better": "Yes, for Google Ads that is about $2,000 a month: $1,000 for us and $1,000 that goes straight to Google. SEO adds more. Does that sit within what you can invest while you are getting started?", "call": "Eric Tsu", "good": true, "q": "So is $2,000 the total I would spend?", "s": 2222, "trick": "Add it up out loud", "url": "https://fathom.video/calls/287693226"}, {"a": "Megan said they usually suggest around $1,000 for Google Ads, though clients range from $1,000 to $100,000, and some start at $500.", "better": "For a new business, we usually suggest about $1,000 a month on Google Ads to get enough data to learn from. You can start lower, but it is slower. Does about $1,000 feel doable for you?", "call": "Daniel", "good": true, "q": "What ad budget do you have in mind?", "s": 408, "trick": "Give a number and the reason", "url": "https://fathom.video/calls/286220389"}, {"a": "Luke said yes, ad spend goes on top of the 4,000 a month fee.", "better": "Yes, you pay Google directly for clicks, and our fee is separate. That way you always see every dollar of ad spend in your own account. Do you have a monthly ad budget in mind yet?", "call": "Jeroen Reuven Bours", "good": true, "q": "Is your fee on top of Google's ad costs?", "s": 339, "trick": "Show money stays visible", "url": "https://fathom.video/calls/259216207"}, {"a": "Brian said it is about not spreading budget too thin, that about 6 ads at a time on Facebook is a good average for smaller budgets, and that they would present a plan for which campaigns to launch first.", "better": "There is no magic number, but here is how I think about it. Each ad needs enough daily budget to get a steady stream of clicks and a few sales a week. With $5,000 a platform, I would run a handful of campaigns first and turn on more as we learn. I will write out the plan with real numbers so you can see it. Want me to include that in the email?", "call": "Dylan Taylor", "good": false, "q": "What is the minimum campaign budget before you stop getting good data?", "s": 1438, "trick": "Give a rule of thumb", "url": "https://fathom.video/calls/273322525"}, {"a": "Luke said his prices are fixed, then asked what he could spend, and later suggested SEO alone at $2,000 or Facebook plus SEO at $2,500 with a $500 ad spend to test.", "better": "Good question, and thank you for being open about the number. Honestly it is less about the amount and more about what we can prove at that size. At about $2,000 a month I would pick one channel and do it well, rather than spread thin across three. Tell me your number and I will tell you straight whether it can work.", "call": "John Cho", "good": false, "q": "What is a good monthly budget to see results? I have a number in mind but I do not want it to be too small.", "s": 1534, "trick": "Ask for their number first", "url": "https://fathom.video/calls/320715151"}, {"a": "Luke said no, ad spend is on top, mentioned a $5,000 plan and individual plans, and talked about starting with about $1,500 to $2,000 a month per platform.", "better": "Great question, and I want it to be clear. No, the $3,000 is our work only, and the ad money goes to Google and Meta on top. I would start you around $2,000 a month per platform, so about $7,000 all in if you do both. We can also start with only Meta and keep it smaller. Which feels more comfortable?", "call": "Mike Worden", "good": false, "q": "Does the $3,000 a month include the ad budget?", "s": 696, "trick": "All in number up front", "url": "https://fathom.video/calls/831260309"}, {"a": "Luke said it depends, started with $1,500 for Google, talked about ROAS and scaling, and did not give one clear number at that point.", "better": "It depends on which channel, but let me give you a real number. To reach $15,000 a month in sales, I would start around $1,500 to $2,000 in ad spend on one channel and watch the return for 60 days. Then we grow only what is working. Would you like me to map that out for your products?", "call": "Tiffani", "good": false, "q": "What is the budget we would need for ads?", "s": 838, "trick": "Give one clear starting number", "url": "https://fathom.video/calls/318560045"}, {"a": "Luke said it is 1,500 up to 10k ad spend, that he sometimes negotiates the 10 percent fee, between 7 and 10 percent on larger budgets, and said he is probably not the best salesman.", "better": "Good thing to ask before you start. It is $1,500 a month while your ad spend is up to $10,000, with design included for you. Above that we move to a percent of spend, because the work grows a lot. So you will always know the price before you scale. Does that feel fair?", "call": "Jermaine Fowler", "good": false, "q": "If I scale up, does it stay $1,500 until I reach 25K a month?", "s": 1435, "trick": "Say the rule, then ask", "url": "https://fathom.video/calls/226527595"}, {"a": "Luke said it depends on the brand and the data, that they start smart with less than 15K, and that his team might counter him on the plan.", "better": "Honestly it varies a lot, so I will not guess. A common way is to start with a smaller test, watch your return, and scale only what works. Your Meta data tells us a lot, so we would build from that. Could you share your best sellers so we can suggest a starting number?", "call": "Rehan Amir", "good": false, "q": "How much would Google spend be compared to my 300K on Meta?", "s": 2087, "trick": "Honest answer plus next step", "url": "https://fathom.video/calls/490898315"}, {"a": "Daniel said he believed it would be enough but had to run it by his team.", "better": "You are right to check, because ads need enough money to learn. Two thousand split across two platforms is thin for a 200 dollar product. I would start with Meta only, put the whole budget there, and add Google later. Would you rather keep it simple and focus first?", "call": "Kristina Shumilova", "good": false, "q": "With a 5,000 dollar max and paying you 3,000, will 1,000 each on ad spend be enough?", "s": 1901, "trick": "Protect them from a bad spend", "url": "https://fathom.video/calls/234074760"}, {"a": "Luke said it depends, but with a 10k budget they would start with about 2000 on Google and 2000 on Facebook, and with 5k they would also start near 2000 each, then move money based on data.", "better": "With a 10000 budget I would start at 2000 on Google and 2000 on Facebook. Then in week two or three we move money to whichever sells more. We never spend your full budget until we see it works. Does starting small like that feel okay?", "call": "Stephanie Webb", "good": false, "q": "If we chose the 5500 package, how much ad budget would you recommend?", "s": 3319, "trick": "Give a number, then explain why", "url": "https://fathom.video/calls/227326702"}, {"a": "Luke asked for his window, then said an ideal range is about $1,500 a month, they can get by with $1,200 and even $1,000, and Justin said he could do about $7,500 over three months.", "better": "Good question. Ideal is around $1,500 a month, and we can start near $1,000 to $1,200 to test. Under that, we would not learn much. Tell me the most you are comfortable with and I will tell you honestly if it is enough to learn from.", "call": "Justin Mitchell", "good": false, "q": "What ad spend would you start at?", "s": 2680, "trick": "Ask for their number first", "url": "https://fathom.video/calls/464049834"}, {"a": "Luke said they have clients from $1,000 to a quarter million a month, Google is safer and Meta is more temperamental, and starting low is still fine.", "better": "Exactly right, you need both ad spend and someone good running it. At your size, I would split your $1,000 to $2,000 so there is enough to learn from. We would track every sale so we know if it pays. Does that match your thinking?", "call": "Isak Peterson", "good": false, "q": "I need a manager too, so I cannot put all my budget into ads, right?", "s": 910, "trick": "Agree, then show the math", "url": "https://fathom.video/calls/329401485"}, {"a": "Luke gave a long answer, then said the minimum is about 1500, 1000 at a stretch, and recommended 2000 and up to 3000 a month to get enough data.", "better": "I would suggest 2000 a month, and 1500 is the lowest I like. Under that we do not get enough data to learn anything. You can raise it later once we see results. Does 2000 fit what you had in mind?", "call": "Anyro", "good": false, "q": "What is the minimum ad spend you look for?", "s": 1104, "trick": "Lead with the number", "url": "https://fathom.video/calls/227623273"}], "audit": [{"a": "Luke offered a $1,000 plan and workbook as a Google Sheet with keywords, clusters and meta tags, ready in a few days, with no work done.", "better": "Yes, and that is a smart way to start with a smaller budget. For $1,000 you get a full plan in a few days: your competitors, the keywords to go after and what to fix on your site. Then you can choose if you want us to do the work or your own helper. Want me to show you a sample so you can see what you would get?", "call": "Kevin Huang", "good": true, "q": "Can you give me a plan first, and when can I get it?", "s": 1493, "trick": "Offer a small safe first step", "url": "https://fathom.video/calls/300079094"}, {"a": "Luke said there is not really an audit, but the team can take a quick look, and he asked about their revenue and business size.", "better": "We do not sell a separate audit. Instead, my team does a free deep look at your offer, your list and your market before we spend you a cent. If we think it will not work, we will say so. I will send our short form so they can start that review.", "call": "Andrew Silagy", "good": true, "q": "Do you charge for an audit, or how does that work?", "s": 1141, "trick": "Free look removes risk", "url": "https://fathom.video/calls/341420869"}, {"a": "Luke said they would simplify the call notes and Megan would send a pricing sheet with options 1, 2 and 3, and invited him to email to talk again.", "better": "Of course, shopping around is smart. I will send a one page summary today with your options and prices in plain words. When you have looked at it, can we set a short time to talk so I can answer anything?", "call": "Eric Tsu", "good": true, "q": "Can you give me a summary so I can compare when I talk to someone else?", "s": 2589, "trick": "Support the comparison", "url": "https://fathom.video/calls/287693226"}, {"a": "Luke said it was not a good fit, that he was too busy to do a three hour audit without seeing their stats, and offered a 1000 dollar two day workshop.", "better": "I understand wanting to compare before you spend. A real audit takes me hours, so I do not do those free, but I can give you honest tips if you send your numbers. If you share what you spend and what you get back, I will tell you where I see gaps, no charge. Does that work?", "call": "Alex Szilagyi", "good": false, "q": "Can you give me an audit or quote first, so I can compare with my current approach?", "s": 1018, "trick": "Offer a free first step", "url": "https://fathom.video/calls/240152980"}, {"a": "Luke said the regular service is $1,500 a month for one location, an audit is very different for them, and he would have to check with Luke and reach back out.", "better": "Thank you for being so open about where you are. An audit is not our usual service, so I will not promise it on the spot, but I do want to help. I can ask Luke about a fixed price tracking review and email you an answer by Friday. Is that okay?", "call": "Jessica Wagner", "good": false, "q": "Can you do an audit of our Google Tag Manager and analytics setup, as a first step?", "s": 357, "trick": "Honest limit with a date", "url": "https://fathom.video/calls/459408894"}, {"a": "Luke said he could email a breakdown of what is involved and agreed to email Jeroen and his colleague.", "better": "Happy to. I will send a short plan today with what we do, the monthly price and what you should see in the first 30 days. Is there anything the president will care about most, so I can put it at the top?", "call": "Jeroen Reuven Bours", "good": false, "q": "Where do I find this information in a package I can show the president of our company?", "s": 376, "trick": "Help them sell it internally", "url": "https://fathom.video/calls/259216207"}, {"a": "Luke did not answer the idea and just asked what his budget was.", "better": "I like that idea. A one time strategy call can be a smart way to start small. I would show you what to test first with your budget so you can run it yourself. Want me to send a link to book one?", "call": "Konstantin Genkin", "good": false, "q": "Maybe we could do a strategic consulting call instead?", "s": 135, "trick": "Offer a smaller first step", "url": "https://fathom.video/calls/329568754"}], "channel": [{"a": "Luke said Google Ads is the more stable bet because about 90 percent of clients who spend there profit, while cold email can land a huge contract or nothing.", "better": "Good thought, Frank. For you I would start with Google Ads, because people are already searching for a hotel photographer, so we catch buyers who are ready. Cold email is a bigger swing but costs more. I earn more on the cold email, so I am telling you this because it is the safer fit. Want me to show you the keywords people are using today?", "call": "Frank Modarelli", "good": true, "q": "If I do not have the budget for cold email, is my money better spent on SEO and Google Ads?", "s": 1711, "trick": "Say what is best for them", "url": "https://fathom.video/calls/264528192"}, {"a": "Luke said they often run multiple campaigns and ads against each other, that testing is the trick, and that with premium Facebook support they can prevent and fix rejected ads.", "better": "Good question, and you are right to think about it before launching. Yes, we would likely run two tracks: one built to pass the social issue rules and one that is more broad. We check the rules first so ads are not rejected, and we can call Facebook support directly if one is. Does that feel like the right balance for your content?", "call": "Jermaine Fowler", "good": true, "q": "Facebook flags my history ads as social issues, should I run two campaigns?", "s": 493, "trick": "Validate, then show the plan", "url": "https://fathom.video/calls/226527595"}, {"a": "Matthew said Meta is stricter than Google for research products and tracking purchases can be restricted, so it might be possible but Google is safer to start. Ali agreed to do Google first.", "better": "I get why you're curious, you have the posts and the page ready. Meta is stricter on products like yours, and it can even block us from calling a sale a purchase. So my honest view is win on Google first, then test Meta small once Google is steady. Want me to check what your competitors are running there so we have real proof?", "call": "Ali Kamel", "good": true, "q": "I have never run Meta ads. Do you think they would work for me?", "s": 1920, "trick": "Honest limit then a small test", "url": "https://fathom.video/calls/827514516"}, {"a": "Luke said SEO has many parts like keyword clusters, internal and external links, backlinks and real content, with the goal of bringing relevant traffic that leads to sales.", "better": "Great question, and you do not have to know SEO to start. Think of it as helping Google understand who you are and who you help, in the same words your clients use when they search. You can keep your simple writing, and we shape it so it still matches what people type. Want me to show you how that looks for a firm like yours?", "call": "Mohamed Mohaimen Hany", "good": true, "q": "How does SEO work, and can we keep our text simple but still show up in search?", "s": 91, "trick": "Use a simple picture for SEO", "url": "https://fathom.video/calls/358358872"}, {"a": "Luke said ChatGPT and Perplexity pull from the internet in real time, so ranking on Google with relevant content helps, and that you cannot pay your way in yet.", "better": "Great question, and you are ahead of most people asking it. These tools read the web live, so the same things that help on Google help there too, like clear pages, real backlinks and mentions on trusted sites. Nobody can promise a spot there yet, but we are watching it closely. Do you want me to check where you show up today?", "call": "Jennifer Metcalf", "good": true, "q": "What can you do to make sure I rank well in AI search like Perplexity?", "s": 488, "trick": "Honest limits, simple why", "url": "https://fathom.video/calls/247960459"}, {"a": "Luke explained Google has organic (SEO) and paid, both bring people searching to your site, and the site must have a clear call to action.", "better": "That is a fair thing to wonder, since you are planning a launch campaign too. SEO works slowly, so starting early means your site is already getting found when the launch buzz sends people searching your name. It does not compete with your other agencies, it supports them. Would it help if I showed how the two fit together?", "call": "Mohamed Mohaimen Hany", "good": true, "q": "What is the benefit of SEO for us at the moment, before our launch campaign?", "s": 1039, "trick": "Calm the fear of overlap", "url": "https://fathom.video/calls/358358872"}, {"a": "Luke said that for his budget he would focus on AI search and social media because paid ads are too expensive, and pointed him to another app of his that could automate content for about 499 dollars.", "better": "With a small budget I would not start with paid ads, because you'd burn through it before the ads learn anything. I would build your social and search first so people find you for free. I want to be honest that this isn't what we do best at your size. Would a simple plan to get foreign event clients to notice you be useful?", "call": "Kushal Barnwal", "good": true, "q": "When I start marketing, should I focus on ads or growing my social media account?", "s": 230, "trick": "Honest fit before any pitch", "url": "https://fathom.video/calls/813161330"}, {"a": "Luke said Google is competitive but local keywords can help, and that Facebook is good for real estate because they can target sellers in the area.", "better": "You are right to be careful, Zillow and Realtor.com spend a lot. The good news is you do not need to beat them, you just need to be the local choice people find next. Facebook can reach likely sellers in your area quickly, and SEO builds the longer game. Which matters more to you this year, fast leads or a strong base?", "call": "John Cho", "good": true, "q": "I do not want to compete with the big brands, so should we do Facebook ads instead?", "s": 1194, "trick": "Reframe the big competitors", "url": "https://fathom.video/calls/320715151"}, {"a": "Brian said they use Meta tools but carefully, turning off some Advantage Plus features because they can broaden audiences and make testing harder, and they keep a change log.", "better": "We use both. Advantage Plus can be useful, but it can also spend on people who will never buy, and it hides what is working. So we turn on the parts that help, turn off the ones that do not, and write down every change so we can learn from it. Is there a past campaign where Meta's automatic settings let you down?", "call": "Purepiel", "good": true, "q": "Do you use Advantage Plus campaigns, or the old manual way?", "s": 2640, "trick": "Explain the why simply", "url": "https://fathom.video/calls/272300366"}, {"a": "Luke said they do Google, Meta and cold outreach, and LinkedIn is an add on to cold email that costs more and can be hit or miss.", "better": "Yes, it is part of what we do, mostly alongside cold email. I would be honest that it can be a hit or miss for some offers, but with your million followers you start in a strong spot. We would find the people who hire speakers and write to each one personally. Would you like to see how that would look for you?", "call": "Jennifer Metcalf", "good": true, "q": "Do you have experience with LinkedIn, since much of our work comes from there?", "s": 775, "trick": "Link to their strength", "url": "https://fathom.video/calls/247960459"}, {"a": "Luke suggested Facebook ads first because of the 40 to 65 age group, said he could drop his fee from $1,800 to $1,500, and wanted the budget raised to at least $3,000.", "better": "Yes, one clear idea. I would start with Meta, because it can reach older people with more money to invest, and we can target trading groups. Before that, though, I would fix the trust on your landing page, because people will not put in $3,000 without it. Can I show you what I mean on the page?", "call": "Millan John", "good": true, "q": "Do you have suggestions on how we could run this campaign?", "s": 851, "trick": "Give one smart specific insight", "url": "https://fathom.video/calls/309209561"}, {"a": "Brian said they do both: backlinks, keyword research and clusters, blogs, landing page updates, with monthly SEO reports instead of weekly videos.", "better": "We do both. We find the right keywords, build links, write blogs and fix your pages so they can rank. Since your founders have strong SEO people, we can also work alongside them instead of replacing them. Would it help if I sent a short example of how we split the work with in house teams?", "call": "Dylan Taylor", "good": true, "q": "What does your SEO team actually do, backlinks or on page work?", "s": 1987, "trick": "Offer to fit their team", "url": "https://fathom.video/calls/273322525"}, {"a": "Brian said AI is a tool they use to their benefit, not a threat, and that they are picky about which Google AI tools they turn on.", "better": "Good thing to ask, Kyle. AI changes how Google works, but someone still has to choose the goal, the keywords and the message. We use the new tools where they help and turn off the ones that waste money. Your results still come from careful setup and daily checks. Does that ease the worry?", "call": "Kyle", "good": true, "q": "Is AI disrupting Google Ads right now, or is it untouched?", "s": 2058, "trick": "Calm the fear with clarity", "url": "https://fathom.video/calls/263406837"}, {"a": "Luke shared his screen and explained paid search versus organic, long tail buyer keywords, Maps, reviews and ChatGPT, and said Google Ads is fastest while SEO takes longer.", "better": "Think of Google Ads as renting a spot at the top, and SEO as owning one. Ads bring calls fast. SEO takes months but keeps working. For a crew of eight who want more jobs now, I would start with ads and ask every happy customer for a review. Want me to show you how it looks for Madison?", "call": "Leo", "good": true, "q": "Tell me more about SEO, what is the difference?", "s": 207, "trick": "Simple comparison they can picture", "url": "https://fathom.video/calls/533275704"}, {"a": "Luke said Google and Facebook own about 84 percent of online market share, and Google captures buyer intent while Facebook interrupts people.", "better": "I hear you, social is where people spend time. Here is the simple difference. Google catches people already searching for boots near them, and Facebook finds people who were not looking. We need both, with a different job each. Want me to show how that would look for your stores?", "call": "Jarrad Beard", "good": true, "q": "Is Google even relevant anymore, since everybody is on social media?", "s": 1377, "trick": "One clear insight, simple contrast", "url": "https://fathom.video/calls/241168945"}, {"a": "Luke said Meta interruption marketing with videos and images is best, because Google ads only catch people searching, and set goals like sign ups and emails.", "better": "Parents are the ones to reach, Erin, and that is exactly what Facebook and Instagram do well. We show short clips of the kids flying drones to moms and dads in the right area. Then we follow up with people who watched. Can you share your best video clips so I can show you?", "call": "Erin Rosenstock", "good": true, "q": "How do I target high schoolers or their parents on social media?", "s": 722, "trick": "Speak to the real buyer", "url": "https://fathom.video/calls/262474173"}, {"a": "Luke said yes they do cold and warm email, it is a different and more expensive package starting at 4,500, best for bigger B2B deals.", "better": "Yes, we do both, and I would not push cold email for you right now. Your 95,000 contacts are warm, so that is an easy win after ads are running. Cold email makes more sense for big B2B deals, like reaching nonprofits. Want to start with ads and look at email in a month?", "call": "Larry Pomerantz", "good": true, "q": "Do you have your own software for cold email, and is it a different package?", "s": 2502, "trick": "Recommend the smaller step", "url": "https://fathom.video/calls/276740502"}, {"a": "Luke said keep Instagram as a side strategy but Google Ads is predictable and brings people looking for her now, so start there.", "better": "Keep Instagram, it is clearly working for you. But clicks there are not steady. With Google Ads, people are already searching for an architect, so the flow of leads is more reliable. I would start there and let Instagram keep feeding the brand. Does that make sense?", "call": "Alexandra Bailey", "good": true, "q": "Should I focus on Google Ads or my Instagram, where my leads come from now?", "s": 704, "trick": "Keep what works, add what is missing", "url": "https://fathom.video/calls/527818977"}, {"a": "Luke said they are niched: Google SEO and Google Ads, Meta, Klaviyo warm email, and cold email as another main service.", "better": "We keep it focused on purpose. We do Google, Meta, warm email and cold email, because that is what we are great at. Since you are new to cold email, that mix helps, as we can test where your next customer really comes from. Which channel are you most curious about?", "call": "Andrew Silagy", "good": true, "q": "Is your company mainly cold email, or do you do all sorts of marketing?", "s": 997, "trick": "Narrow focus builds trust", "url": "https://fathom.video/calls/341420869"}, {"a": "Luke said they run influencers for several clients, paying cash for some, up to about 5,000 for bigger ones, and gifting product to smaller ones, and that those videos can be reused in Facebook ads.", "better": "Yes, and for a brand like yours it can be very smart. We often send product to smaller creators first and check their real engagement before paying anyone. Then we reuse their best videos in your Facebook ads. Would you want me to include a small test in the plan?", "call": "Mark", "good": true, "q": "Do you also work with influencers?", "s": 1358, "trick": "Small test before big spend", "url": "https://fathom.video/calls/226492580"}, {"a": "Luke said that is not part of the Google ads side, it belongs to SEO, and explained that paid ads and organic search are two ways to win the same keywords.", "better": "Yes, that is exactly what SEO is for. We tell you which topics and keywords to cover, you make the videos, and we tune them to rank. The Google ads package covers ads only, so SEO would be added when you are ready. Want me to show you how the two fit together?", "call": "Shabnam Akrami", "good": true, "q": "Will your team tell me what to do with my content and videos so they help SEO?", "s": 1400, "trick": "Draw a simple line between services", "url": "https://fathom.video/calls/282988891"}, {"a": "Luke said Google is the biggest, owns about 91 percent of the market, and everyone should lock it down, especially service businesses, though he would not start Facebook right away.", "better": "That is a smart instinct. Google ads catch people who are ready to buy, and they work in days while SEO builds. For a window company in Chicago, I would start with Google and keep Facebook for later. Do you want to look at it with your owner on the next call?", "call": "Stefan Gutowski", "good": true, "q": "Should we start with Google Ads since it is sort of the same thing as SEO?", "s": 1317, "trick": "Validate their idea, then guide", "url": "https://fathom.video/calls/293071198"}, {"a": "Luke explained Google is intent marketing where people search ready to buy, so they are leaving money on the table without it, and said both Google and Facebook together could be best.", "better": "That is a real concern, and it often comes down to landing pages and timing, not Google itself. People searching for window installers are ready to buy, so it is worth a careful test. We could start small and fix the landing page first. Would you like that?", "call": "Eric D Shepard", "good": true, "q": "Google ads stopped working for us after COVID, why would it work now?", "s": 892, "trick": "Reframe the cause, small test", "url": "https://fathom.video/calls/458078657"}, {"a": "Luke said running Meta and Google together is $3K a month in management, but for a fresh brand he would lock down Google first because it is buyer intent.", "better": "We can run both, but with no sales yet I would not split your budget in two. Google catches people who are ready to buy, so that is where we win a first sale fastest. Once it works, we add Meta to bring those people back. Does that order make sense to you?", "call": "Sam Daoud", "good": true, "q": "Which one is Meta and which is Google, can you do both?", "s": 701, "trick": "Sequence channels, do not stack", "url": "https://fathom.video/calls/551904290"}, {"a": "Luke said not much, Google is buyer intent and Meta is interruption, so it is not the go to but worth a small careful test, and he claimed 95% positive ROAS on Google.", "better": "Honestly, Meta is trickier for B2B, so I would not start there. Google catches people already searching, so I would lock that down first. Since two competitors are running Meta, a small test later could make sense. Want me to look at what they are running?", "call": "Mark H", "good": true, "q": "Do you use Meta much for business to business?", "s": 537, "trick": "Honest answer plus small test", "url": "https://fathom.video/calls/524683610"}, {"a": "Luke said they only do Meta and Google, with a team of 10 across the US, Canada and London, covering paid search, SEO and Meta.", "better": "We do two things, Google and Meta, and we do them well. A team of 10 handles it, so you are never talking to one person. For festivals, Meta is great for tickets and Google catches people already searching. Which one do you feel does more for you now?", "call": "Dean Strober", "good": true, "q": "How do you guys work, is it mostly Meta or also Google?", "s": 536, "trick": "Link answer to their business", "url": "https://fathom.video/calls/335111266"}, {"a": "Luke said SEO is Google's organic side, going after people searching for terms like best payment processor, and that it is part of the Google strategy.", "better": "No worries at all, plenty of people ask that. SEO is how you show up when someone types something like best card processor into Google, without paying per click. Paid ads work the same way, only faster. Want me to show you what your buyers search for?", "call": "Gregory Corbin", "good": true, "q": "What is SEO? I do not even know what that is.", "s": 305, "trick": "Plain words, no jargon", "url": "https://fathom.video/calls/325605508"}, {"a": "Luke said it changes constantly, they work on it every day with over 50 clients, and he showed a deck with an example ad that got a 3.5 ROAS.", "better": "It changes all the time, and that is why working with a team helps. We run ads for over 50 clients, so we see what works and what stops working before most people. I can show you an ad that got a 3.5 return. Want me to send you the examples?", "call": "David Marcyniuk", "good": true, "q": "Does the Facebook landscape keep changing, and do you stay on top of it?", "s": 1561, "trick": "Turn the worry into your edge", "url": "https://fathom.video/calls/231509507"}, {"a": "Luke said geotargeting handles that, down to radius, zip code and street, and that without online you miss parents searching and AI answers that start the word of mouth.", "better": "That is a smart question. Yes, we can aim ads at a 5 or 10 mile circle, even by zip code, so you never pay for people outside it. Word of mouth is best, but a parent has to find you first. Would it help to see how we set up a local campaign?", "call": "Mike Worden", "good": true, "q": "Is digital marketing worth it when I only care about people within 10 miles?", "s": 408, "trick": "Agree word of mouth matters", "url": "https://fathom.video/calls/831260309"}, {"a": "Luke said every campaign has a main goal plus smaller campaigns beneath, so that could be one of them, along with retargeting and location campaigns.", "better": "Yes, that is a smart idea, and it is easy on Meta. We could build a small campaign aimed only at your top five partners' employees, beside the main local one. Then we can see which gets better results. Can you send me that company list?", "call": "Jarrad Beard", "good": true, "q": "Should we target employees of our top partner companies in the ads?", "s": 1936, "trick": "Praise the idea, then make it concrete", "url": "https://fathom.video/calls/241168945"}, {"a": "Luke said yes, ads can get you to the top right away but you have to pay for it, with about $2,000 ad spend.", "better": "Yes, ads are the fast lane. You can show up at the top within days, but you pay for every click. SEO is slower but the traffic is free over time. Since your budget is tight, would you rather start small with ads or begin with the plan?", "call": "Kevin Huang", "good": true, "q": "Will Google paid ads give a quick result?", "s": 1904, "trick": "Compare two paths side by side", "url": "https://fathom.video/calls/300079094"}, {"a": "Luke said Google Ads is the fastest and suggested management at a reduced $1,000 plus about $1,000 ad spend because the business is small.", "better": "Good question. For you I would start with Google Ads, because people searching for tint near them are ready to buy and you can start getting calls fast. SEO is great too but takes a few months. How soon do you need new customers?", "call": "Eric Tsu", "good": true, "q": "If I just want people to go to my website and get a price, is Google Ads or SEO my best route?", "s": 792, "trick": "One clear recommendation", "url": "https://fathom.video/calls/287693226"}, {"a": "Luke said to Google them and look for sponsored ads, and if the big ones advertise it is probably working for them.", "better": "Easy way. Search your top competitors in a private browser and see who pays for the top spot. If many do, it works for them, and if none do, buyers probably do not search that way. I can show you what to look for in two minutes.", "call": "Yesset Karayev", "good": true, "q": "How can I find out if the big auction companies run Google ads?", "s": 2676, "trick": "Give a free quick check", "url": "https://fathom.video/calls/455546501"}, {"a": "Luke said they have done SEO for years including link building and it all ties to ChatGPT, but it is slower than paid ads.", "better": "Yes, we do SEO, links and AI search work. It is slower than ads, so I would keep your ads running while it builds. Your FAQ pages and reviews are already smart steps. Want us to look at that after Google Ads is running well?", "call": "Mark H", "good": true, "q": "Are you also getting into SEO? Do you do link building too?", "s": 1770, "trick": "Set honest speed expectations", "url": "https://fathom.video/calls/524683610"}, {"a": "Luke said he would start with Meta ads at $1,500 a month, watch conversions and ROAS for two months, then scale or add Google, and add SEO later.", "better": "If it were my money, I would start with Meta at $1,500, because your Instagram is already working. I would watch it for two months and add Google only once Meta pays back. Then SEO comes later. How does that sit with you?", "call": "Isak Peterson", "good": true, "q": "If you were in my shoes, what would you try for a three month period?", "s": 1661, "trick": "Speak as if it were my money", "url": "https://fathom.video/calls/329401485"}, {"a": "Luke said yes in general, explained ads can show on the map as sponsored, and that reviews and keywords help organic map rankings.", "better": "Mostly yes. You can pay to show up on the map, or earn a spot with reviews and a good profile. Since you find services on the map yourself, that is where we would put real effort. Want me to check your business profile?", "call": "Eric Tsu", "good": true, "q": "Do SEO and ads work the same way on Google Maps as in normal search?", "s": 1874, "trick": "Use their own habit", "url": "https://fathom.video/calls/287693226"}, {"a": "Luke said it is multifaceted, reviews are part of it, and they would work in stages, getting to the top of search fast with ads while slowly building reviews.", "better": "Reviews matter, but they are one piece with your profile and keywords. You do not need 400 reviews to start. We can run ads for fast leads while we build your reviews over time. Does that order make sense to you?", "call": "Eric Tsu", "good": true, "q": "So reviews help, but it is really the SEO that gets businesses to the top?", "s": 2111, "trick": "Break big goal into stages", "url": "https://fathom.video/calls/287693226"}, {"a": "Luke said they used to offer it as an add on with bots and Sales Navigator, never had much success, stopped selling it, and recommended focusing on cold email.", "better": "Honestly, not really for us. We tried it and only got a few meetings, so we stopped selling it, because we only sell what gets results. I would put your energy into email first and see what the numbers say.", "call": "Andrew Silagy", "good": true, "q": "Is LinkedIn a good channel for selling, or not really?", "s": 1976, "trick": "Admit what did not work", "url": "https://fathom.video/calls/341420869"}, {"a": "Brian said it is Meta only at $1,800, with a Google and Meta package for $2,500, and a Meta plus email package for $3,000.", "better": "Yes, this price is Meta only, and I think that is the right place to start for the retreat. If it works, we can add Google or email later. There is no pressure to buy more now. Does Meta first sound right?", "call": "Chris Bilyk", "good": true, "q": "Is this just for Meta ads, no Google?", "s": 2179, "trick": "Start small, grow later", "url": "https://fathom.video/calls/271182973"}, {"a": "Luke said it comes in levels and moved to SEO and reviews as the thing he would add.", "better": "PMax is a fine start, but it gives you less control. Since people book tours from their phones, I would add a maps style ad to your search campaign so you show up where they look. We can test that in the first month. Want me to show you where you show up now?", "call": "Christian Hoeffel", "good": false, "q": "Is PMax enough for search, or should we do more, like Google Maps ads?", "s": 3279, "trick": "Answer first, then add one idea", "url": "https://fathom.video/calls/317379106"}, {"a": "Luke said it cannot be answered in a minute, needs a deep review, and that a plan would be presented within a couple of days after they get paid and into the account.", "better": "Fair thing to want to know. With a feed based shop, Pmax and Shopping often work together, but it depends on your products and margins. I would not guess without seeing the data. In week one we would test both and share what we learn. Does that make sense?", "call": "Joyce", "good": false, "q": "Should we use Pmax or Shopping ads for next year with more products?", "s": 787, "trick": "Give a hint, then a test plan", "url": "https://fathom.video/calls/470472685"}, {"a": "Luke said they use scripts and many tools but do not rely on Google's own algorithms and do most things manually.", "better": "Yes, we use Google's smart tools, but we guide them. Left alone, the AI spends your money where Google wants. We set the targets, the tracking and the limits so it learns from real leads. Did something specific fall apart when you tried it?", "call": "Jeroen Reuven Bours", "good": false, "q": "Google is steering ads with AI now, is that something you do?", "s": 475, "trick": "Ask what broke first", "url": "https://fathom.video/calls/259216207"}, {"a": "Luke said they can do it, but they do not usually cross track cold email into Facebook and Google; they do it for warm lists they own.", "better": "I like that thinking, because timing matters in your market. We can do it, but I would not start there. First let us see if the emails get replies, and then add retargeting once we know who is warm. Does that order make sense to you?", "call": "Andrew Silagy", "good": false, "q": "Would you suggest an echo campaign, loading the email list into LinkedIn or Google Ads to retarget them?", "s": 1863, "trick": "Sequence the idea, do not reject it", "url": "https://fathom.video/calls/341420869"}, {"a": "Luke said yes, but he left the details to Matthew and Harry and offered to bring them on the call.", "better": "Yes, that group is a real asset, and we can build ads around it and people like them. I want the exact setup to come from the team who do this daily, so let me bring Matthew in for ten minutes. Would that help?", "call": "Isak Peterson", "good": false, "q": "Can we target the 6,000 people in our private Facebook group?", "s": 2186, "trick": "Say yes, bring in the expert", "url": "https://fathom.video/calls/329401485"}, {"a": "Luke had Megan pull up Google and show that sponsored results are paid ads while the results below are organic, then explained the map section too.", "better": "The ones marked Sponsored are only paid ads. Everything below them, and the map pack, is organic. Let me show you in your area so you can see where you would land.", "call": "Eric Tsu", "good": false, "q": "When businesses show up at the top as sponsored, is that Google Ads, SEO, or both?", "s": 1490, "trick": "Show it live on screen", "url": "https://fathom.video/calls/287693226"}], "comms": [{"a": "Luke said they set communication to match what the client wants, with a first month weekly call, Loom videos walking through the account, same day email replies, and a booking link, mostly through the GM Matthew.", "better": "I hear you, you have been burned by an agency that went quiet. So here is how we do it. You get a short Loom video that walks through your account in plain words, a weekly call in the first month, and email answers usually the same day. Would you like fewer calls or more, so we set it up your way from day one?", "call": "Eric D Shepard", "good": true, "q": "Do you have a dashboard or a way for us to stay in touch, and can we reach you when we need to?", "s": 402, "trick": "Echo their pain, then be specific", "url": "https://fathom.video/calls/470388378"}, {"a": "Brian said the team takes full control, checks daily, and sends a weekly Loom video under 5 minutes that shows the real numbers, plus email, phone and booking links any time.", "better": "Great question, most people want to stay out of dashboards, and that is fine. Every week you get a short video from us, under five minutes, showing what you spent, what sold, and what we will do next. You never have to log in unless you want to. Does a weekly video feel like the right amount for you?", "call": "Dylan Taylor", "good": true, "q": "How does reporting work and how often will we get it?", "s": 1164, "trick": "Match their wish for less work", "url": "https://fathom.video/calls/273322525"}, {"a": "Luke said yes, they take over creatives and strategy, send a weekly video of about 10 minutes, and meet whenever the client wants more.", "better": "Yes, that is exactly how it works. We do the heavy thinking up front, then you get a short video from us each week showing what we changed and why. If you want to jump on a call more, we are happy to. Would you want me to ask you for a few of your own videos too, since people buy from you?", "call": "Jermaine Fowler", "good": true, "q": "After the plan, will I be hands off while you make the changes?", "s": 651, "trick": "Paint the weekly picture", "url": "https://fathom.video/calls/226527595"}, {"a": "Luke said they are month to month so they must show ROI, use Data Studio dashboards, and send a custom video from a team member at least once a week.", "better": "Great question. You will get a short video from your team each week where we walk through the numbers on screen, plus a dashboard you can check anytime. We show visits, calls and leads, not just clicks. There is no contract, so we have to earn it every month. Want to see a sample video?", "call": "Joseph Gaspero", "good": true, "q": "How do we monitor performance and how do your clients measure ROI?", "s": 1368, "trick": "Show the rhythm of reporting", "url": "https://fathom.video/calls/247180673"}, {"a": "Luke showed a custom monthly report with traffic, impressions and rankings, said the team records a Loom video of about 10 minutes, and can tailor it high level or deep.", "better": "You will never get a PDF with no explanation. Each month someone from our team records a short video and walks you through what we did, what moved, and what is next. We can make it very simple for you and deeper for your team. Want me to send a sample so you can see it?", "call": "Annie", "good": true, "q": "How do you track and report results, beyond traffic and authority score?", "s": 1815, "trick": "Show reporting in human terms", "url": "https://fathom.video/calls/301373694"}, {"a": "Luke said yes, each client gets a login where they can see replies and reply themselves, or his team can reply for them. He later showed an Instantly style inbox with campaign stats and reply rates.", "better": "Yes, you will have your own login with our logo on it. You see every reply in one inbox and every campaign number, like reply rate. You can answer leads yourself or let us do it, whichever you like. Want me to show you what the inbox looks like right now?", "call": "Andrew Milstead", "good": true, "q": "Do you have a portal where we can see the responses coming in?", "s": 859, "trick": "Say yes, then show it live", "url": "https://fathom.video/calls/229583830"}, {"a": "Luke said no fixed monthly meetings, a live video walkthrough at least once a week, and quick calls every couple of weeks or any time she asks.", "better": "Very little, Lindsey, and that is the point. You get a short video every week showing your accounts. If you want to talk, we jump on a call, and we check in every couple of weeks. No boring meetings, just clear updates. Does that fit your busy schedule?", "call": "Lindsey Carter", "good": true, "q": "What would you need from me, and what does a normal month look like with talking to each other?", "s": 1044, "trick": "Give them time back", "url": "https://fathom.video/calls/262584763"}, {"a": "Brian said they send informal weekly videos showing the account and metrics, and will build the key metrics in Klaviyo.", "better": "Yes. We build a simple view of the numbers that matter, like email one against email five. Each week we send a short video that walks you through it. If something looks off we tell you early. Would that be enough for you and Mike?", "call": "Carolina", "good": true, "q": "Will your team set up reporting so we can see how emails and ads perform?", "s": 3646, "trick": "Show what they will see", "url": "https://fathom.video/calls/274394195"}, {"a": "Luke said they send a video report every week or two, and Kay can add a call every two weeks or monthly to review the plan.", "better": "It is up to you. We send a short video every week or two showing what moved, and we can add a call every two weeks or once a month. Most of the work happens without you needing to do anything. What rhythm would suit your schedule?", "call": "Kay Pollard", "good": true, "q": "How often would we talk, and is it just the first week?", "s": 1059, "trick": "Let them choose the rhythm", "url": "https://fathom.video/calls/241212547"}, {"a": "He said they send weekly Loom videos walking through leads, results and changes, plus email and booking links for live calls.", "better": "You will never have to chase us. Every week you get a short video where we walk through what worked, what we changed and what is next, and you can book a call any time. Is video or a live call better for you and your team?", "call": "Leonard Emini", "good": true, "q": "How would we communicate and how would you share data with us?", "s": 915, "trick": "Show the weekly rhythm", "url": "https://fathom.video/calls/271080025"}, {"a": "Luke said communication is custom, email any time, frequent Loom videos walking through accounts, and replies usually within a couple of hours, with Matthew using a shared Google Drive.", "better": "Simple. Email us any time and we reply in a couple of hours, and we send Loom videos so you see the account. One shared Google Drive keeps your photos in one place. Does that sound easy?", "call": "Hailey Baird", "good": true, "q": "How will we communicate day to day, and how do we share files?", "s": 947, "trick": "Keep it simple and human", "url": "https://fathom.video/calls/512674658"}, {"a": "Megan said each client gets an account manager and a Loom video update every Friday, with email at any time.", "better": "Yes, you get one account manager who is your person. Every Friday you get a short video on how things are going, and you can email anytime. Would that feel like enough contact for you?", "call": "Kristina Shumi", "good": true, "q": "Will I have one person to talk to and get reports every week?", "s": 1240, "trick": "Name the person and rhythm", "url": "https://fathom.video/calls/284134646"}, {"a": "Luke said it is custom to each client, with a strategy call at the start and another a week later, then Loom videos and email, and calls whenever needed.", "better": "We tailor it. You get a kickoff call, one more a week later, and then a short Loom video showing real numbers. If you prefer a weekly call, we do that too. Which would you like?", "call": "Matt Holdridge", "good": true, "q": "How often do you do check ins, weekly or every two weeks?", "s": 1794, "trick": "Offer a choice", "url": "https://fathom.video/calls/469763535"}, {"a": "Daniel said the customer success managers monitor the metrics, keep you updated, and usually reply within 24 hours if you reach out.", "better": "Good question, because nobody wants to be set up and then forgotten. Your campaign gets looked at every week by a real person, and you get a short update with what is working and what we are changing. If you ever have a question, you will hear back within one business day. Would a quick weekly video be a good way to keep you in the loop?", "call": "Kristina Shumilova", "good": false, "q": "How often do the team check in, and do they just leave the campaign once it is set up?", "s": 1360, "trick": "Answer the fear behind the question", "url": "https://fathom.video/calls/234074760"}, {"a": "Megan said they always give creative ideas and stay by his side, while Luke said they specialize in a couple of things and do not do everything.", "better": "Yes, and that is a normal place to start. You will have a real person who explains each step in plain words and checks in with you, so you never feel lost. We cannot do every part, like video, but we will tell you what comes next and who can help. Can I walk you through what the first month would look like?", "call": "Barry Smoak", "good": false, "q": "Can I lean on you for help since I am new to all of this?", "s": 887, "trick": "Reassure, then paint month one", "url": "https://fathom.video/calls/283039215"}, {"a": "Daniel said he believed it is weekly but would need to check with his team, and said she can email anytime to book a meeting within 24 hours.", "better": "Honest answer, you will see numbers every week, and I will confirm the exact format before you pay so there are no surprises. You will see spend, how many people clicked, how many bought, and what we do next. Would you like to see a sample report?", "call": "Kristina Shumilova", "good": false, "q": "How often will I get reports from the team?", "s": 1470, "trick": "Be honest, then show proof", "url": "https://fathom.video/calls/234074760"}, {"a": "Luke said communication is custom, after payment and the onboarding form the team reviews call notes and meets the client, and some clients talk often while others do not.", "better": "You choose. Every week you get a short update, and we can meet as often as you like, weekly or monthly. Before our first call the team already studies your notes, so you do not repeat yourself. How much contact would you like?", "call": "Stephanie Webb", "good": false, "q": "Do you do weekly reporting, or how often do you meet with clients?", "s": 3729, "trick": "Let them set the rhythm", "url": "https://fathom.video/calls/227326702"}, {"a": "Luke said they send Loom videos, may move reports to biweekly or monthly, hold an hour onboarding call, and reply to emails within 24 hours, usually in an hour or two.", "better": "You will always know what we did, what we are doing and what is next. We send a short video walking through your account, plus a report, and you can have a call whenever you want. Which would you like most, weekly or monthly?", "call": "Brian Rose", "good": false, "q": "Once you start, is it weekly calls or a monthly report?", "s": 1550, "trick": "Offer a simple choice", "url": "https://fathom.video/calls/288749754"}], "contract": [{"a": "Luke said there is no contract and you can leave any time, but he wants at least three months, and he offered to drop the price to 3,500 for the first three to four months.", "better": "No contract at all, Frank, you can stop whenever you want. I just want to be straight that two months is usually too short, because month one is research, month two ramps up, and month three is where we see the real numbers. If three months is too much right now, I would rather tell you to wait than have you waste money. How does that sound?", "call": "Frank Modarelli", "good": true, "q": "Is there a contract, and would you recommend a two month go at this?", "s": 1156, "trick": "Give the honest timeline", "url": "https://fathom.video/calls/264528192"}, {"a": "Luke said Google work has a three month minimum, they do not do one time setups though it could be negotiated, and handing over in month one is not a good idea.", "better": "I get why you want that, you are busy and want to keep costs low. The trouble is the first three months are where most of the learning happens, so a quick handover usually leaves money on the table. We keep it simple with three months, then month to month, and you own the account the whole time. Would that feel comfortable to you?", "call": "Rehan Amir", "good": true, "q": "Can you do a one time Google Ads setup and then hand it over to me?", "s": 651, "trick": "Explain the reason behind the rule", "url": "https://fathom.video/calls/490898315"}, {"a": "Luke agreed that guest posts are not fixed because one month might bring two and the next four or five, and said they never buy bad links.", "better": "Yes, you have it exactly right. Articles are the promise, guest posts are the stretch. I do it this way on purpose, because a promised number tempts agencies to buy cheap links, and I will never do that to you. Also, there is no long contract, so you can see the work before you commit. Want to see how we report the links we win?", "call": "Chris Savor", "good": true, "q": "So the contract minimums are the articles, and guest posts are something you strive for but are not in the contract?", "s": 858, "trick": "Confirm, then give the reason", "url": "https://fathom.video/calls/251114242"}, {"a": "Luke said it is not something they do, and that SEO is not one and done, though six months of work can give results for years.", "better": "I hear you, and with the changes in your world, being careful is smart. A one time push can help for a while, but it usually needs about three to four months of work to set up. A smaller plan with a few months of work, then a pause, can be done. Would a short project like that be worth looking at?", "call": "Joseph Gaspero", "good": true, "q": "Can we do SEO as a one time setup with no ongoing service because of budget limits?", "s": 1676, "trick": "Acknowledge budget, offer small test", "url": "https://fathom.video/calls/247180673"}, {"a": "Luke said there is no 12 month contract, only a three month minimum with a one page clause and a 10 day exit, so anyone can leave by email.", "better": "No, and I know why you ask, that contract you described sounds awful. We have a one page agreement with a three month minimum, and in the first 10 days you can walk away for any reason. We keep clients by doing good work, not by locking them in. Would you like to read the page before you decide?", "call": "Michael Cash", "good": true, "q": "Do I have to sign a long contract?", "s": 1727, "trick": "Name the bad contract, contrast it", "url": "https://fathom.video/calls/867124558"}, {"a": "Luke said yes, it is three months and then month to month, because the team needs time to build on the account and they want commitment from both sides.", "better": "Yes, it is three months, then month to month after that. I would rather be honest about why. The first months are where we learn your account, and I do not want you judging us on three weeks. After that we keep you only if the results are there. Does that feel fair after your last experience?", "call": "Mohammed Sharifi", "good": true, "q": "Is the three month commitment a minimum three month contract?", "s": 1213, "trick": "Give the honest reason", "url": "https://fathom.video/calls/323376725"}, {"a": "Brian and Luke said it is month to month with no contract lock in, with weekly and monthly updates and short videos so you can see results.", "better": "Month to month, Chloe, and you can leave any time. We used to do yearly deals and stopped, because we would rather earn your trust each month. You will get a short video every week showing what we did. We ask for about three months so the work has time to show results. Does that feel fair?", "call": "Chloe Puig", "good": true, "q": "What are your contracts like, month to month or yearly?", "s": 1320, "trick": "Remove the risk, say why", "url": "https://fathom.video/calls/264491733"}, {"a": "Luke said they link her card to her business manager and then to theirs, they send a Stripe link on autopay, and it is a three month minimum.", "better": "Simple. You keep your own ad account and card, we just get access, and you can turn it off any time. Our fee is a Stripe link on autopay each month, with a three month minimum so we have time to do real work. I will put it all in a contract you can read first. Want me to send it today?", "call": "Tiffani", "good": true, "q": "How do you get paid? Do you invoice monthly, and who holds the ad spend card?", "s": 1556, "trick": "Make payment feel safe and simple", "url": "https://fathom.video/calls/318560045"}, {"a": "Luke said SEO is never a one time thing, to plan at least three to four months and ideally six, and after that it depends on revenue whether to keep going.", "better": "Good question, and I will be honest with you. SEO is not a one time job, it builds over months, so I would plan at least six. After about a year we look at the sales it brought, and you decide whether to keep going. Would it help if I showed you what the first six months look like?", "call": "Joyce", "good": true, "q": "Is SEO a one time thing, or do we have to keep paying to build it?", "s": 444, "trick": "Be honest about the timeline", "url": "https://fathom.video/calls/322118977"}, {"a": "Luke said it is billed monthly and one month is not enough, you need at least four months.", "better": "Good question. It is $2,400 a month, and SEO needs a little patience, so I would plan on at least four months to see real traffic. There is no big lock in, but one month alone would not show you anything. Would it help if I explained what happens in each of those first four months?", "call": "Kevin Huang", "good": true, "q": "Is that $2,400 for one month, and how long do I need to stay?", "s": 538, "trick": "Honest answer, then offer detail", "url": "https://fathom.video/calls/300079094"}, {"a": "Luke said it is month to month with no contract, with only a verbal ask to try three months, and that Doug can stop any time.", "better": "No contract at all. It is month to month and you can leave any time. I only ask for a handshake that you give it about three months, because cold email needs a little time to warm up. If it is not working sooner, I will be the first to tell you. Does that take the pressure off?", "call": "Doug Fiore", "good": true, "q": "Is there a three month commitment to this process?", "s": 2308, "trick": "Remove the risk, keep the ask small", "url": "https://fathom.video/calls/242167771"}, {"a": "Luke said no contracts, month to month, with a verbal ask to stay at least three months, then walked through pricing of 1,500 for Meta, 3,000 for Meta and Google, plus 1,000 to 2,000 ad spend each.", "better": "No contract, month to month, and you can leave any time. I only ask for a three month handshake because ads need a little time to learn. For you, Meta and Google together is 3,000, plus ad spend of about 1,000 to 1,500 each. Does that sit okay with where you want to land?", "call": "Jarrad Beard", "good": true, "q": "How do your contracts work?", "s": 2378, "trick": "Remove risk, then plain numbers", "url": "https://fathom.video/calls/241168945"}, {"a": "Luke said it is month to month and can be cancelled any time, but he asks for a minimum of three months because the work needs time.", "better": "There is no contract, so you are free to stop any time. I do suggest three months though, because the first month is setup and learning, and the real results come after. Since camp is in July, we have enough time to do it well. Does three months work for you?", "call": "Erin Rosenstock", "good": true, "q": "How long should I commit, would two months be okay?", "s": 1454, "trick": "Tie timing to their event", "url": "https://fathom.video/calls/262474173"}, {"a": "Luke agreed to cross out the three month commitment in the contract and let him tell them at the end of the month.", "better": "Thank you for being so honest, that helps me a lot. I would rather you stay because it works than because of a contract, so I am happy to take the three months out for you. What I ask is that we tell each other early if anything changes. Does that feel fair?", "call": "Marius Negru", "good": true, "q": "If I cannot pay after the first month, can I leave? I am not here for three months.", "s": 829, "trick": "Honesty for honesty, flexible terms", "url": "https://fathom.video/calls/525995385"}, {"a": "Luke said they usually do a three month contract but might skip it for now, then send an onboarding form and payment link, with a team call the same or next day.", "better": "Here is how it goes. I send a payment link and a short form today, and Matthew calls you right after. We usually use a three month agreement, but since this is new, I am happy to start month to month for the first weeks. Would that make you comfortable?", "call": "Mathieu Bolle", "good": true, "q": "What is coming next, and is there a contract?", "s": 1483, "trick": "Flexible terms to lower risk", "url": "https://fathom.video/calls/545661967"}, {"a": "Luke said they only do long term work, month to month with no commitment, and charge 3k a month for Google and Facebook up to 20k ad spend plus 500 for graphics.", "better": "Long term is exactly what we do. We work month to month with no contract, and clients stay because it works. For Google and Facebook it is 3000 a month, and graphics are 500 extra if you want them. Does a long term partner sound like what you pictured?", "call": "Stephanie Webb", "good": true, "q": "We want long term management, what possibilities do you have for that?", "s": 579, "trick": "Echo their words first", "url": "https://fathom.video/calls/227326702"}, {"a": "Luke said at least three months, later saying the contract is month to month with an exit anytime and he would check in after weeks one and two himself.", "better": "Fair question. We say three months because it takes time to learn, but for you I will make it month to month, so you can leave if it is not working. We will talk after month one and be honest about what we see. Would that make it easier to say yes?", "call": "Justin Mitchell", "good": true, "q": "How many months would I need to commit before we get something real to analyze?", "s": 2697, "trick": "Lower the risk of starting", "url": "https://fathom.video/calls/464049834"}, {"a": "Luke said there are zero contracts, they can leave anytime, and the clients own the campaigns, but he asks for a verbal hope to stay at least three months.", "better": "No contract at all. You can leave any time and you own your ad accounts. I only ask that you give it three months, because it takes that long to learn what works. I would rather earn your trust each month than lock you in. Does that feel fair?", "call": "Tony Small", "good": true, "q": "What does the commitment look like, and is there a number of months?", "s": 1246, "trick": "Explain why no contract", "url": "https://fathom.video/calls/246099180"}, {"a": "Luke said it is $2,400 flat for one location and billed monthly, and that cheap $2,000 setups are worthless.", "better": "It is $2,400 a month for one location. SEO works best when it keeps going, so most clients stay on, but we review it together and I will tell you honestly if it is time to change plans. Does monthly work better for you than a long contract?", "call": "Stefan Gutowski", "good": true, "q": "Is that monthly, and what does the duration look like?", "s": 587, "trick": "Price plus flexibility together", "url": "https://fathom.video/calls/293071198"}, {"a": "Luke said there is no contract, billing is by payment link on auto pay, month to month, with a verbal ask for three months.", "better": "No contract. We send a payment link, it goes on auto pay, and you can stop any time. I ask for three months by handshake only, because SEO needs a little time. We earn your stay with results. Does that feel better than what others told you?", "call": "Kay Pollard", "good": true, "q": "Is there a contract, and how does billing work?", "s": 1138, "trick": "Contrast with the usual lock in", "url": "https://fathom.video/calls/241212547"}, {"a": "Luke said there is no long contract, only a three month commitment so both sides are serious, and after that the client stays only if they want to.", "better": "You are right, it is a short commitment, and I will not hide that. The reason is that ads need a few weeks to learn, and leaving early would waste your money. After three months, you stay only if it works. Does that feel fair to you?", "call": "Leah Vogt", "good": true, "q": "Is the three month commitment really a contract?", "s": 690, "trick": "Say the true word, then explain why", "url": "https://fathom.video/calls/347069031"}, {"a": "Luke said it is in the contract that the accounts and work are the client's, and that they work inside the client's existing accounts.", "better": "Yes, and I would insist on it. Everything stays in your accounts, and the contract says they are yours. If we ever part ways, you keep every campaign and all your data. Would you like me to include that line in the email I send you?", "call": "Eric D Shepard", "good": true, "q": "Can you manage our existing ad accounts so we always own them?", "s": 1485, "trick": "Put ownership in writing", "url": "https://fathom.video/calls/458078657"}, {"a": "Luke said no contracts, monthly billing at 4500, work starts on day one, and she can cancel any time, though he prefers clients who stay about three months.", "better": "No contract at all. You pay 4500 for the month, we start that day, and you can stop whenever you want. I ask for about three months only because cold email needs time to learn what works. Is that something you are comfortable with?", "call": "Andrew Milstead", "good": true, "q": "What is the signup rate and is there a contract?", "s": 1356, "trick": "Explain why you ask for time", "url": "https://fathom.video/calls/229583830"}, {"a": "Brian said it is month to month with a contract sent over, so you can stay as long as you get results and leave if you need to.", "better": "Yes, it is a simple monthly fee, and you can stop any time. We do that on purpose so we have to keep earning it. Setup is included, and the Google Ads account stays yours. Would you like me to send the contract so you can read it?", "call": "Kyle", "good": true, "q": "Do you work on a retainer for management and setup, and how does that work?", "s": 1140, "trick": "Make flexibility a promise", "url": "https://fathom.video/calls/263406837"}, {"a": "Luke said no contract at all, month to month, they used to have contracts and dropped them because they do not want to tie anyone in.", "better": "No contracts. You stay because it works, and you can leave any time. What I do ask is that we both give it about three months, because that is how long it takes to see real results. Does three months of working together feel fair?", "call": "Joseph Gissy", "good": true, "q": "Is it month to month or a six month contract?", "s": 1226, "trick": "No contract, honest commitment", "url": "https://fathom.video/calls/230308235"}, {"a": "Luke said it is monthly with a three month minimum then month to month, and he said it is not set in stone for a seasonal business.", "better": "It is monthly, with a three month start and then month to month. I know your season is seasonal, so we can talk through the quiet months. We just want to do the setup properly and show you results first. Does that feel fair?", "call": "Dean Strober", "good": true, "q": "Is the $2,500 monthly, and is there a contract term?", "s": 769, "trick": "Give the reason for the term", "url": "https://fathom.video/calls/335111266"}, {"a": "Luke said there is a 3 month minimum because less is pointless, then it runs month to month, and clients usually stay a year.", "better": "Yes, billed monthly. We ask for 3 months because SEO needs that long to show real movement, and after that you can go month by month. If you are not seeing value, you should not stay. Does a 3 month start feel okay to you?", "call": "Annie", "good": true, "q": "So it is billed by the month, and is there a minimum?", "s": 916, "trick": "Give the reason for the minimum", "url": "https://fathom.video/calls/301373694"}, {"a": "Luke said it is automatic, with an invoice sent first and a receipt after, because chasing invoices is too hard.", "better": "It is automatic, and you always get an invoice before and a receipt after. We do it this way so nothing gets missed on either side. If you ever have a question about a charge, just message Matthew or me. Does that work?", "call": "Chad", "good": true, "q": "Will the later months auto deduct from my card, or will you send an invoice?", "s": 60, "trick": "Explain the reason simply", "url": "https://fathom.video/calls/322275597"}, {"a": "Luke said they charge monthly, not up front, with a three month minimum but a 10 day exit and no contract after that, and they do not hold anyone ransom.", "better": "No, it is not paid up front. You pay month by month, and if month one is not working, just tell us and we do not hold you. We have a three month minimum so we can do real work, plus a 10 day exit. Does that feel safer?", "call": "Mike Worden", "good": true, "q": "Do I commit $10K up front for three months?", "s": 1824, "trick": "Clear no, then reassurance", "url": "https://fathom.video/calls/831260309"}, {"a": "Luke said month to month, they used to do 12 month contracts, and they keep clients through results rather than locking them in.", "better": "Right, month to month. We stopped contracts because we want you to stay because it works, not because you are stuck. If leads are not coming, you should be free to leave. What matters to you most in the first 60 days?", "call": "Garret Ashton", "good": true, "q": "So there is no contract, it is month to month, right?", "s": 1793, "trick": "Turn no contract into trust", "url": "https://fathom.video/calls/228223662"}, {"a": "Brian said no real contract, month to month, no commitment, and later called the paperwork a scope of work for both sides.", "better": "It is month to month, so you can pause or stop any time. The one page agreement just lists what we do and what you get, so we are both clear. We want to keep you with results, not paperwork. Does that sound fair?", "call": "Brian (mock call 1)", "good": true, "q": "Do you have contracts, and what if I want to pause my ads?", "s": 1770, "trick": "Frame contract as clarity", "url": "https://fathom.video/calls/267787294"}, {"a": "Luke said there is a three month minimum, then month to month, and if they are losing money after two months he would not charge for the third month.", "better": "We ask for three months, because good campaigns take time to build. After that it is month to month. If after two months you feel we are not making you money, tell me and we will talk. Does that feel safe to you?", "call": "Isak Peterson", "good": true, "q": "Do you have contracts, or is it month to month?", "s": 1575, "trick": "Make the risk feel small", "url": "https://fathom.video/calls/329401485"}, {"a": "Luke said zero commitment, month to month, but they recommend three months and would not take a client for just one.", "better": "There is no contract, it is month to month. We suggest three months because cold email needs the first month to set up, the second to ramp, and the third to see full results. Does three months feel okay?", "call": "Gio", "good": true, "q": "What is the minimum commitment for the contract?", "s": 1115, "trick": "Why we suggest three months", "url": "https://fathom.video/calls/267686901"}, {"a": "Luke said three months minimum but not set in stone, you can leave after month one, though it isn't worth starting campaigns for one month.", "better": "Yes, three months is our standard. It takes that long to learn what works with your data, and I'd rather be honest about that. If it isn't a fit, you can leave with 10 days notice. Does that feel okay?", "call": "Dorian Fleuri", "good": true, "q": "It's three months minimum, right?", "s": 1606, "trick": "Give the reason for the rule", "url": "https://fathom.video/calls/564365833"}, {"a": "She said there are no contracts and no commitments, only month to month, with three months recommended to see results.", "better": "There is no contract at all, you can leave any month. We suggest three months because cold email needs time to warm up and test, but that is advice, not a lock in. Does that feel fair to you?", "call": "Ricardo Amaya", "good": true, "q": "How long is the contract?", "s": 1196, "trick": "Free to leave, honest advice", "url": "https://fathom.video/calls/269795639"}, {"a": "Luke said they work month to month with no contracts, so clients can leave if results are not there.", "better": "No contract. We work month to month, so we have to earn the next month. After what you have been through, I think that is the right way to start. Does that take some pressure off?", "call": "Safa", "good": true, "q": "Is it a contract, and do you work month to month?", "s": 186, "trick": "Acknowledge past burns", "url": "https://fathom.video/calls/259170120"}, {"a": "Luke said yes, one month at a time, and that the contract is just a commitment.", "better": "Yes, you pay one month at a time, and the three months is only a promise to give it a fair try. You will see each invoice before it is charged. Does that feel comfortable?", "call": "Chad", "good": true, "q": "Will the three months be paid monthly, one month at a time?", "s": 31, "trick": "Make the plan feel safe", "url": "https://fathom.video/calls/322275597"}, {"a": "Brian said yes, he would own all assets and the accounts, and they would make any transition smooth.", "better": "100 percent, it is your account and your data. We run it for you, and if you ever leave we hand everything over smoothly. Does that take a worry off your plate?", "call": "Brian (mock call 1)", "good": true, "q": "Will I own everything if I stop working with you, like my Facebook and Google accounts?", "s": 2082, "trick": "Say yes, remove the worry", "url": "https://fathom.video/calls/267787294"}, {"a": "Luke explained they want serious clients, three months is paid one month at a time, and long answers said people who cannot commit usually cannot invest.", "better": "Fair to check that. The three months is paid monthly, and Google Ads needs that time to learn, so a pilot cut at 20 days would not teach you much. If your CEO wants a real answer, three months gives you real data. Want a short note you can share with him?", "call": "Razi Hecker", "good": false, "q": "I need to check if I can commit to three months. Why is it required?", "s": 1336, "trick": "Give the reason, then help them", "url": "https://fathom.video/calls/507313039"}, {"a": "Luke said it is a three month agreement but you can stop anytime with 10 days notice, payment is one month upfront, and if he could not pay upfront they were not the right fit.", "better": "That makes sense, you've been burned before and money is tight. Here is what I can do. Month one is paid upfront, and I'll cut it 50 percent so your risk is small. If you aren't happy in the first 10 days, you tell me and we stop. Does that feel fair?", "call": "After hours alcohol delivery prospect", "good": false, "q": "I can't do three months or pay in advance. I need to see the work first.", "s": 640, "trick": "Shrink the risk, keep the value", "url": "https://fathom.video/calls/858246139"}, {"a": "Luke said they charge monthly with a basic retainer plus 50% of ad spend above 5K, monitor daily, and keep clients by showing results, then later quoted 3K.", "better": "Great question. We work month to month with a flat fee, and we are in your account daily. The fee depends on your ad spend, and I will give you one clear number so nothing is confusing. Can I ask what you spent last month so I can quote you exactly?", "call": "Mark H", "good": false, "q": "How does your business model work? Do you only work by the month?", "s": 937, "trick": "One clear number, no confusion", "url": "https://fathom.video/calls/524683610"}, {"a": "Brian said he would talk to Luke, did not want to charge when nothing is happening, and would send an updated proposal.", "better": "You should not pay for months when nothing is happening. I suggest a small pay as you go option for tweaks, with a price list you see in advance. I will bring you an exact number in the updated proposal. Does that feel fair?", "call": "Carolina", "good": false, "q": "How should I think about pricing when I need small changes later?", "s": 3360, "trick": "Remove the fear of surprise bills", "url": "https://fathom.video/calls/274394195"}, {"a": "Luke said they charge monthly and people stay only if they are making money, without stating contract length.", "better": "Good question. It is month to month with us, so you are never stuck. We only want you to stay if the jobs are coming in. We will send you the leads every month and ask how many you booked. Does that feel safe?", "call": "Leo", "good": false, "q": "Is this a month program, or what is the commitment?", "s": 833, "trick": "Answer the exact question first", "url": "https://fathom.video/calls/533275704"}, {"a": "Megan said it is month to month, with a recommended three months, and you can leave any time.", "better": "It is a simple agreement with no year long lock in. We ask for a three month start, because Google and Meta need time to learn, and I want you to see real results. Does that feel fair to you?", "call": "Kristina Shumi", "good": false, "q": "What is the contract with you guys?", "s": 1357, "trick": "Give the reason for the term", "url": "https://fathom.video/calls/284134646"}], "creative": [{"a": "Brian said they do not use AI, they would use the creatives Chris already has, and the designer would make more later, all included in the price.", "better": "We do not use AI for your ads, because real photos and videos of your retreat feel more honest. We start with the footage you already have, cut it into short 15 second clips with captions and a call to action, then add new pieces as we learn. All of that is in the fee. Can you share the folder of retreat videos?", "call": "Chris Bilyk", "good": true, "q": "Are we creating images from scratch, doing photo shoots, or using AI?", "s": 2326, "trick": "Use what they already have", "url": "https://fathom.video/calls/271182973"}, {"a": "Luke said they welcome ideas, will test them, and will push back honestly if an idea looks wrong, while Kristina explained that things like 25 years in business can build trust.", "better": "Yes, please. You know your customers better than we do, and 25 years is a real trust builder. We will test it in the ads and show you the numbers, and if something does not work we will say so kindly. What other things do customers say they love about you?", "call": "Eric D Shepard", "good": true, "q": "If we have ideas, like our 25th year in business, can we say we want to use them in the ads?", "s": 1044, "trick": "Invite their input, stay honest", "url": "https://fathom.video/calls/470388378"}, {"a": "Luke said it varies, and gave examples: a jewelry client gives a 1000 dollar gift card to about 20 influencers a month, and another pays up to about 5000 for big accounts.", "better": "It depends on the size. Small creators will often say yes to a free subscription, and bigger ones want money, sometimes 1500 to 5000. For your site, I would start with small creators and a free year, and see who responds. We can test it cheaply first.", "call": "Lasse Jensen", "good": true, "q": "Is it enough to give influencers free product, or do they want to be paid?", "s": 1037, "trick": "Real example then small test", "url": "https://fathom.video/calls/240196889"}, {"a": "Megan said they have an in house designer and editor who edit the client's images and videos, but the client needs to provide the raw photos or video.", "better": "Yes. We have a designer and editor who polish your content. We need your raw footage, like short clips from your course, and we will tell you exactly what to film. Would you be comfortable filming a few simple videos?", "call": "Kristina Shumi", "good": true, "q": "Do you help with the images and videos for ads?", "s": 1110, "trick": "Say what they must supply", "url": "https://fathom.video/calls/284134646"}, {"a": "Brian said they test new Facebook creatives every week, keep the best ad running while trying to beat it, and avoid big changes on Google for a few days to a week so the algorithm can learn. He did not answer the minimum volume part directly.", "better": "I like that you asked, because testing is where most of the gain comes from. On Meta we add new creative every week and always try to beat your best ad. On Google we change less, about once a week, so the system can learn. For volume, with your budget we can test a few ads at a time and I will tell you honestly when we have enough data to trust a result. Want me to sketch what the first month of tests would look like?", "call": "Dylan Taylor", "good": false, "q": "How do you do testing and optimization, and how much volume is needed for a test?", "s": 1244, "trick": "Answer the part they asked", "url": "https://fathom.video/calls/273322525"}, {"a": "Brian said the in house designer edits and builds creatives as part of the Meta price, but they need product videos from the client, and influencer made UGC would cost extra. He said he would check with Luke.", "better": "I can see why this matters, because it changed how you saw the price. Let me be clear: our designer edits, adds text and builds the ads, and that is included. The raw footage of your product, like a simple phone video, usually needs to come from you, or we can arrange a creator as an add on. Let me confirm exactly what was said on your first call and email you today. Is that okay?", "call": "Purepiel", "good": false, "q": "Will you make the ad videos for us, or do we have to film them? Luke told us it was included.", "s": 1109, "trick": "Own the confusion calmly", "url": "https://fathom.video/calls/272300366"}, {"a": "Daniel said you can provide your own, but usually the in house team creates the visuals, and he showed an example ad, though he could not name the client or product.", "better": "Great thing to ask, because the picture or video is what makes people stop scrolling. Our designers make them for you, and you are welcome to send your own photos or clips too. Since your course is about calm and love, soft real photos often work well. Want to see an ad we built for a similar kind of product?", "call": "Kristina Shumilova", "good": false, "q": "Do I need to provide the images and video for the ads, or do you make them in house?", "s": 1520, "trick": "Tie the answer to their product", "url": "https://fathom.video/calls/234074760"}, {"a": "Luke said Meta is now creative based so ads change often, with as many as 160 ads running at once, and winning ads stay on with small tweaks.", "better": "Often, because on Meta the creative does most of the work. We test many versions at once, keep the winners running and tweak them. We also watch what competitors run for ideas. You would get fresh ideas from our designers every month. Does that sound like the hands on help you want?", "call": "Jarrad Beard", "good": false, "q": "How often should we change our ads?", "s": 2044, "trick": "Short answer, then show the process", "url": "https://fathom.video/calls/241168945"}, {"a": "Luke said it was a deep question, suggested a studio video for $700 to $800 showing who she is, her background and energy, and that they would plan a script.", "better": "Pretty much, yes, and that is the power of it. Keep it short and real. Say who you help, what you have done, and invite them to talk. A studio costs about $700 to $800, and I can help with the script. Does that sound doable?", "call": "Amy N Neighbors", "good": false, "q": "Is the video really just me saying who I am and what we do?", "s": 2801, "trick": "Make the hard thing feel simple", "url": "https://fathom.video/calls/485151651"}, {"a": "Luke said they would break down a plan if the client moves forward and that they run dozens of ads and campaigns.", "better": "For a small budget I would start with three or four ads and let the winners show in a few weeks. More ads can split your money too thin. I can map exactly how we would test it in your plan. Sound fair?", "call": "Jeroen Reuven Bours", "good": false, "q": "Do you recommend rotating four or five ads for a small company like us?", "s": 495, "trick": "Give one real insight", "url": "https://fathom.video/calls/259216207"}], "crm": [{"a": "Luke listed Apollo, Sales Navigator, Ocean, Outscraper and Apify, and said for her kind of business Apollo and Sales Navigator would likely be enough.", "better": "We mix a few trusted sources, and for a business like yours we would mostly use Apollo and Sales Navigator. Then we check every email and website before anything goes out, so you are not paying for bad data. That check is what keeps your emails out of spam. Would you like me to show you how a list looks after cleaning?", "call": "Andrew Milstead", "good": true, "q": "Where do you get the leads from?", "s": 1063, "trick": "Tie the source to their goal", "url": "https://fathom.video/calls/229583830"}, {"a": "Luke said they use Zapier and Make too, and can pull leads into whatever CRM the client uses.", "better": "Good question. Yes, we connect with Zapier and Make, so every positive reply can drop straight into your CRM. Your sales rep will not have to copy anything by hand. Which CRM does your team use, so I can tell you exactly how it will work?", "call": "Andrew Milstead", "good": true, "q": "Are you compatible with our CRM, like through Zapier, so leads go straight in?", "s": 900, "trick": "Answer, then ask which tool", "url": "https://fathom.video/calls/229583830"}, {"a": "Luke said they do not manage CRMs, but can set one up like HubSpot, send leads there and add follow up texts, while someone on the client side needs to make the calls.", "better": "Good thing to ask now. We can set up a simple CRM and automatic follow up texts, so no lead gets lost. Making the sales calls is your side, and we will coach you on that. How many people will answer the phone for you?", "call": "Garret Ashton", "good": true, "q": "As leads come in, how do we manage them, is there a CRM or follow up?", "s": 3501, "trick": "Be clear on what you do not do", "url": "https://fathom.video/calls/228223662"}, {"a": "Luke said he was not familiar with JobNimbus but leads can be sent almost anywhere with Zapier, Make or an API, though ReachGiant does not work inside CRMs themselves.", "better": "Good thing to ask now. We have not used JobNimbus, but most CRMs connect with Zapier or Make, so I am fairly confident we can send every new lead straight in. We will test it before any ads go live. Can Eric send us a login or a docs link so we check it this week?", "call": "Eric D Shepard", "good": false, "q": "How do we get our leads into JobNimbus, our CRM?", "s": 1386, "trick": "Honest gap, then a next step", "url": "https://fathom.video/calls/470388378"}], "diy": [{"a": "Luke said he would be straight, that he would waste his time because cold email is one of the hardest channels, and it is hard to get past spam filters.", "better": "You absolutely can, Frank, and I respect that you want to learn it first. The one risk is your domain. If it lands in spam, it can take weeks to repair and you lose the chance with the big names you want. If you try it, keep the volume tiny and use a separate domain. Want a short list of the mistakes to avoid?", "call": "Frank Modarelli", "good": true, "q": "Could I try cold email myself first and come back to you after I learn more?", "s": 1445, "trick": "Support their choice, warn gently", "url": "https://fathom.video/calls/264528192"}, {"a": "Luke said no ClickFunnels or GoHighLevel are needed, suggested Klaviyo for email, and said her site could use a rebrand but it is not essential.", "better": "Good thing to ask. You do not need ClickFunnels. We would send traffic to your site and use Klaviyo to warm people up by email, and we can build that list for about $2 each. You will not need a new hire for the ads. Would a simple email plan help you?", "call": "Ivona", "good": true, "q": "Will this need another hire or tools like ClickFunnels or GoHighLevel to warm up cold leads?", "s": 789, "trick": "Say what is not needed", "url": "https://fathom.video/calls/481051622"}, {"a": "Luke said he would have recommended it because training an internal team can take years, then pushed back that SEO and Google Ads are easy to do but hard to do really well.", "better": "That is a fair plan and I can see why it sounded smart to you. With 30,000 pages, a trained team is real work, and it usually takes a year or more to get good. We could do either, train your people or run it for you, and the right choice depends on speed and cost. Can I look at the site first and tell you honestly which way I would go?", "call": "Billy Chung", "good": false, "q": "What is your opinion on another company telling me to hire four or five people and train them to do the SEO myself?", "s": 205, "trick": "Respect their idea, then compare", "url": "https://fathom.video/calls/499402776"}], "fit": [{"a": "Brian said there are no tiers and no campaign limit, but they will be careful not to spread the budget too thin.", "better": "Good news, there is no cap on campaigns and no tiers, so you can grow your box lineup without a price change. The real limit is budget, because 20 campaigns on a small budget each get very little data. So I would start with your best few boxes and add more as the winners show up. Does that sound like a smart way to launch?", "call": "Dylan Taylor", "good": true, "q": "Is there a campaign limit or a package tier that would limit us, since we want a campaign for each of our 20 boxes?", "s": 1383, "trick": "Say yes, then add honest limit", "url": "https://fathom.video/calls/273322525"}, {"a": "Megan said ReachGiant offers four main services: Google Ads, organic SEO, Meta ads and warm email, plus influencer marketing, with a team of nine across the US and Canada.", "better": "Good question. We focus on four things we do really well: Google Ads, SEO, Meta ads and warm email. Most people start with Google Ads because it is the fastest, then add SEO later. Since Google Ads is your main channel right now, want me to show you how we would handle that first?", "call": "Brian Rose", "good": true, "q": "What departments do you have, and how far out do you go with marketing?", "s": 773, "trick": "Narrow the menu to fit them", "url": "https://fathom.video/calls/288749754"}, {"a": "Luke said each business has its own profile, suggested emailing past clients to leave reviews on the new profile, and said reaching 20 to 40 reviews is a great start.", "better": "Reviews stay with each profile, so we cannot move them over. Your idea is the best one, asking happy past clients to leave a short review on the new profile. Aim for 15 emails a day and we will give you a simple note to send. Would you like that template this week?", "call": "Shabnam Akrami", "good": true, "q": "Can my Google reviews from the other business be connected to this one?", "s": 1719, "trick": "Praise their idea, then hand a tool", "url": "https://fathom.video/calls/282988891"}, {"a": "Brian said he agreed that starting with a survey is best for an educational campaign and that setup matters most here.", "better": "Yes, I like the survey, because it gives you the person's age and other facts for later emails. We would keep it short so people finish it. If it does not convert, an ebook is a good second test. Want us to review your questions before we build it?", "call": "Carolina", "good": true, "q": "Do you agree a survey magnet is the best way to build this list?", "s": 1232, "trick": "Give one smart reason, then a next step", "url": "https://fathom.video/calls/274394195"}, {"a": "Luke recommended reading Essentialism, picking one clear goal, and going all in on it, and told stories about his own 50K a month goal.", "better": "I hear how tired you are of chasing the HOT clients, and that matters. Here is what I would do: ask which one you would still enjoy doing in two years, and put your energy there. You can still use HOT money as a bridge, but only one gets your full focus. Which one makes you more excited when you picture next year?", "call": "Greg Laskody", "good": false, "q": "Should I scrap HOT and develop Master CRE, or finish HOT since I already started it?", "s": 2075, "trick": "Ask a question that points to the answer", "url": "https://fathom.video/calls/804786478"}, {"a": "Luke said it can be, but it might not be, and Meta or Google ads may not be the right channel until Greg is 100 percent clear on his goal.", "better": "It could be us, and I would love that, but I want to be sure first. Right now the offer is still fuzzy, and good ads on a fuzzy offer just waste your money. Let's get the one sentence offer clear, and then I can tell you honestly if we are the right team. Would you like to send me that sentence when you have it?", "call": "Greg Laskody", "good": false, "q": "Can you be the brander and marketer for Master CRE? Is that you?", "s": 2803, "trick": "Protect trust by being honest", "url": "https://fathom.video/calls/804786478"}, {"a": "Luke said he needed to run it by his team to build a clear plan, would study the site and analytics, and that they only do SEO, Google Ads and Meta with a team of 12.", "better": "Great question. We only do three things, SEO, Google Ads and Meta, and we do them all day with a team of 12. For a site this big I do not want to guess, so my tech will look at your pages and analytics first. Then I will come back with a plain plan and a clear price. Does end of week work to talk again?", "call": "Billy Chung", "good": false, "q": "What do you guys actually do, and how would you help us?", "s": 1149, "trick": "Say what you do, then promise a plan", "url": "https://fathom.video/calls/499402776"}, {"a": "Luke said it varies, from e commerce and startups to service businesses, about 50 to 60 clients and 10 employees, specializing in Meta, Google Ads, email, SEO and web development.", "better": "We do best with businesses that already sell something and want more leads or sales from Google and Meta. That is where our team is sharpest, so we say no to a lot of other things. Who are the startups you send people to, and what do they usually struggle with first?", "call": "Alan Kadish", "good": false, "q": "Who is your ideal client and what do you offer?", "s": 127, "trick": "Narrow focus builds trust", "url": "https://fathom.video/calls/261509501"}, {"a": "Luke said they have 10 employees and about 60 clients, specialize in cold email, web design, Google, Meta and SEO, and can do warm email too.", "better": "Fair question, and I am glad you asked. We are a team of 10 with around 60 clients, and we do web design, ads, SEO and email. Your warm email we can do, but what I hear is bigger: you want a brand people recognize. Can I show you how we would start with that?", "call": "Jade Pyne", "good": false, "q": "What do you specialize in, and are we asking for something outside your scope?", "s": 707, "trick": "Answer, then name the bigger need", "url": "https://fathom.video/calls/242102912"}, {"a": "Luke walked through account setup in the client's name, strategy, keywords, tracking, landing page tweaks and said they do not reply to leads or answer the phone.", "better": "Good thing to ask. We handle everything inside Google, plus tracking and small landing page fixes. We do not answer calls or reply to leads, that stays with your team. Does that split work for you?", "call": "Darren Lebel", "good": false, "q": "When you say you take care of all that, what does it mean? Are you answering phones?", "s": 728, "trick": "Draw a clear line", "url": "https://fathom.video/calls/504983103"}, {"a": "Luke insisted he needed a general budget and Daniel then said around $2,000.", "better": "Fair to ask. I am not trying to sell ads. I ask so I do not suggest something you cannot afford. Even a rough range helps me point you to the right thing. Would a range work?", "call": "Daniel", "good": false, "q": "Why are you asking about my budget?", "s": 167, "trick": "Explain why you ask", "url": "https://fathom.video/calls/286220389"}], "industry": [{"a": "Luke said they have a strong chance because it is a product people need, but cold email does not work for everyone, and he mentioned about 55 clients and 10 employees.", "better": "That is a fair thing to ask. I think you have a real shot, because your price and next day delivery are things printers care about. I will be honest, cold email works great for some people and flops for others, and the big risk here is trust since you have no website yet. Want me to show you how we would fix that first so replies turn into orders?", "call": "Shayaan Abbas Houssen Aly", "good": true, "q": "Is this kind of cold outreach going to work in our industry?", "s": 873, "trick": "Honest odds plus named risk", "url": "https://fathom.video/calls/253053797"}, {"a": "Luke said that is the agency's job, they have apps to find lookalike and similar brands, and that it is different when you work with a team than a one person band.", "better": "You are right, a niche like yours is hard to target, and I am glad you told me. We would look at who your audience follows, who else sells to them, and use your 27,000 email list to build lookalikes. I will not promise it is easy, but we have tools for exactly this. Would you like to share a few people your audience already follows?", "call": "Jermaine Fowler", "good": true, "q": "Competitors are hard to find in my niche, can you still find the right audience?", "s": 999, "trick": "Use their own list as proof", "url": "https://fathom.video/calls/226527595"}, {"a": "Luke said they have over 60 clients and 10 employees across many types, never niche down, and admitted a firm like theirs would be new territory.", "better": "I will be honest, we have not done executive search before. We have done consultants, government groups and service firms, and the base work is the same. The difference is I would spend the first week learning your buyers before writing a word. Would it help if I showed you a plan for a similar service client?", "call": "Chris Savor", "good": true, "q": "Have you handled SEO for a service business like executive search?", "s": 1218, "trick": "Honest gap plus a bridge", "url": "https://fathom.video/calls/251114242"}, {"a": "Luke said they research the market, show prototypes before building, and that every design passes his eye before the client sees it.", "better": "I hear you, you have been burned by designers who never really got it. We start by studying your customer, the contractor buying heavy equipment, and we show ideas early so you can say what feels off before we build. Every design also goes past me first. Would it help if I showed you how we do that step?", "call": "Jade Pyne", "good": true, "q": "Will your designers understand our niche trailer business and our contractor customer?", "s": 1261, "trick": "Echo their words first", "url": "https://fathom.video/calls/242102912"}, {"a": "Luke said no garage door client, but many similar ones such as painters, contractors and flooring, plus a locksmith and policy heavy clients, and that they are a Google Premier partner.", "better": "Honest answer, no garage door company yet. But we have run locksmiths, contractors and flooring, so Google's tough verification is familiar. We would keep your account stable and avoid risky changes. Does that give you enough comfort, or would it help to hear how we handled the locksmith?", "call": "Michael Cash", "good": true, "q": "Have you worked with garage door companies and Google's verification rules?", "s": 1411, "trick": "Honest gap, closest proof", "url": "https://fathom.video/calls/867124558"}, {"a": "Luke said the whole team is US based, his manager Matthew is in New York, they have done real estate many times, and they would do a deep dive on the target market.", "better": "Yes. Our team lives in the US so we think like your buyers, and we have done real estate before. For Costa Rica we would learn the seasons, who is searching now and who is ready in 60 to 90 days. I would love to hear who your best buyer is today. Who do you want more of?", "call": "Cesar Diaz", "good": true, "q": "Do you understand American buyers and my Costa Rica market?", "s": 1080, "trick": "Ask who their best buyer is", "url": "https://fathom.video/calls/860109475"}, {"a": "Luke said they have around 45 to 50 clients with a lot of B2B, and explained Google and SEO are the best fit while Meta is weak for B2B.", "better": "Yes, a good share of our clients are B2B, so this is familiar ground. For something as niche as yours, I would start with Google, because it catches people who are already searching. I can send you a couple of B2B examples after we talk. Does that sound helpful?", "call": "Justin Mitchell", "good": true, "q": "Do you have references or experience with strictly B2B advertising?", "s": 925, "trick": "Simple proof, then next step", "url": "https://fathom.video/calls/464049834"}, {"a": "Luke said they work with a mobility scooter company in New Zealand at a higher price point, plus jewelry and about 10 Shopify clients, and Matthew can share more.", "better": "Yes, and that is a fair worry at a $1,500 pound price. We run ads for a mobility scooter store at an even higher price, and the lesson is the same: fix tracking, then spend on what sells. Matthew can walk you through their numbers if you want. Would that help?", "call": "Marius Negru", "good": true, "q": "Have you worked with anyone else who sells products at such a high price?", "s": 1138, "trick": "Match proof to their situation", "url": "https://fathom.video/calls/525995385"}, {"a": "Luke said they work with fitness apps, alcohol and addiction companies, and know the rules so they shape content to Google's guidelines.", "better": "That is frustrating, and it is a real risk for trainers. We have worked with fitness apps and other touchy industries, so we know where the lines are. We write content to fit the rules and never push past them. Want me to look at what got flagged for you?", "call": "Kay Pollard", "good": true, "q": "Google flagged my before and after photos. How would you handle that in my industry?", "s": 1294, "trick": "Show you have seen this before", "url": "https://fathom.video/calls/241212547"}, {"a": "Luke said they do not show live accounts, but showed one ad for a client who sells moss walls, with a 3000 average order value, 170,000 people reached and leads generated.", "better": "Yes. We keep client accounts private, but I can show you real ads and numbers with permission. A moss wall artist at about 1.5 million in sales is a close match to you. I can also set up a call with a client who has similar sales. Would that help?", "call": "Stephanie Webb", "good": true, "q": "Do you have examples of what you have done?", "s": 1905, "trick": "Match proof to their size", "url": "https://fathom.video/calls/227326702"}, {"a": "Luke said no pool company, no current cleaning company, but they have flooring, moving, construction and painting clients with the same plan.", "better": "No pool company yet, and I will be honest about that. We run seasonal, local service accounts like moving and painting, so the plan is the same. You would be our first pool client, so you would get extra attention. Does that feel okay?", "call": "Darren Lebel", "good": true, "q": "Have you guys done a pool company before?", "s": 1148, "trick": "Admit gap, show similar wins", "url": "https://fathom.video/calls/504983103"}, {"a": "Luke said both, and that they never picked one niche, wanting a small strong team and a match where the business already works.", "better": "Both. We work with roofers, stores and software, because the basics are the same: know your buyer and track what works. What matters is that your offer is real, and yours is. Which customer matters most to you right now?", "call": "Razi Hecker", "good": true, "q": "Do you work with B2B or also B2C?", "s": 1802, "trick": "Answer, then ask about their buyer", "url": "https://fathom.video/calls/507313039"}, {"a": "Luke said they have 12 employees, specialize in Google and Meta, and serve both e commerce and service clients without a niche.", "better": "We run Google for a lot of service companies like flooring, moving and painting. Your business is the type we do well with: steady demand and clear sales. I can send a short video from a similar client. Want that?", "call": "Darren Lebel", "good": true, "q": "How well versed are you in service businesses like mine?", "s": 430, "trick": "Name similar clients, offer proof", "url": "https://fathom.video/calls/504983103"}, {"a": "Luke said they are one of the best Google Ads teams in the US, a Google partner with over 60 Google Ads clients and 10 employees.", "better": "I think so, but I want to be sure first. We have done similar lead gen work and I would like to look at your keywords before saying yes. Would it help if I tell you about a client that looked like yours?", "call": "Maria Costa", "good": true, "q": "Do you think you are a good fit to help us with this?", "s": 411, "trick": "Honest fit before a promise", "url": "https://fathom.video/calls/253101615"}, {"a": "Luke said they never niched, are best at ecommerce and service businesses, and avoid things like real estate where they cannot help.", "better": "Yes, ecommerce and local shops are a big part of what we do. A store like yours is a good fit because you already have loyal customers and a list. I can show you a similar brand we run. Want to see one?", "call": "Matt Holdridge", "good": true, "q": "Do you work with a lot of retail businesses?", "s": 584, "trick": "Link their shop to a fit", "url": "https://fathom.video/calls/469763535"}, {"a": "Luke said they have experience with both and prefer high ticket products or services, as long as the business is working.", "better": "We have done both. Services with high ticket jobs actually suit us best, because one sale pays for a lot of ads. Your assessments sound like that. Would you like an example of a similar service client?", "call": "Razi Hecker", "good": true, "q": "Do you have more experience on the product side or the services side?", "s": 1761, "trick": "Link their offer to our strength", "url": "https://fathom.video/calls/507313039"}, {"a": "Luke said about 40 accounts.", "better": "We run about 40 accounts right now, and most spend around 10K a month on ads. I'm happy to tell you how many are local delivery or service businesses like yours. Want me to show you one example?", "call": "After hours alcohol delivery prospect", "good": true, "q": "How many ad accounts are you guys running?", "s": 919, "trick": "Number plus a relevant example", "url": "https://fathom.video/calls/858246139"}, {"a": "Luke said he can give references, video case studies and reviews, but only sends references when a client is ready to move forward.", "better": "Yes, I have video case studies and reviews, and I will send a few today. I can also introduce you to a client once you are close to deciding. Which kind of business would you like to hear from?", "call": "Darren Lebel", "good": true, "q": "Do you have any case studies you can share?", "s": 598, "trick": "Offer proof right away", "url": "https://fathom.video/calls/504983103"}, {"a": "Luke said they have doctors, plastic surgery and cosmetic dental clients, but not exactly hers, and they do not share client data. He said they have about 60 to 70 clients and zero negative reviews.", "better": "Yes, we work with doctors, plastic surgeons and larger dental practices, so we know the care needed around health topics. I keep client data private, the same way I would for you, but I can share reviews and walk through our process. I would also love to meet your compliance people early. Would that help your team?", "call": "Annie", "good": false, "q": "Do you have experience in healthcare or a similar use case you can share?", "s": 2143, "trick": "Explain why privacy builds trust", "url": "https://fathom.video/calls/301373694"}, {"a": "Luke said yes, they have a lot of communications clients including a couple of AI companies like Hey Libby doing similar things, though he would need to check on communication specifically.", "better": "Yes, we have worked with a few communication and AI companies, and Hey Libby is a close match to what you do. I do not want to oversell it, though. The real question is whether your buyers are easy to find, so I will have my team check that on your lists. Would it help if I sent you two examples after this call?", "call": "Andrew Silagy", "good": false, "q": "Have you guys worked with communication companies?", "s": 296, "trick": "Honest proof plus easy next step", "url": "https://fathom.video/calls/341420869"}, {"a": "Brian said their clients are a mix, including clothing e commerce, software and bigger businesses, and he was not sure they had worked with dropshipping specifically.", "better": "Fair question. We work with online stores of different kinds, and the ad work is very similar, but I will be honest that I do not have a dropshipping example I can name today. What matters most is your margin and your creative, and we can check both in an audit. Can I ask what your profit per order looks like?", "call": "Purepiel", "good": false, "q": "Are you familiar with dropshipping stores, or more with in store businesses?", "s": 489, "trick": "Honest answer, then curiosity", "url": "https://fathom.video/calls/272300366"}, {"a": "Luke said yes, not exactly a trading platform, but they work with financial companies like Money Next and many clients who need account signups.", "better": "Not a trading platform exactly, and I will be honest about that. We do work with financial companies, including a finance events company, and we run many signup campaigns. The trust piece you need is something we handle often. Would it help if I explained how we would build that trust on your page?", "call": "Millan John", "good": false, "q": "Have you worked with financial clients or campaigns like ours before?", "s": 741, "trick": "Be honest about the gap", "url": "https://fathom.video/calls/309209561"}, {"a": "He could not recall a musical artist but said they work with a TED speaker who has over a million LinkedIn followers.", "better": "Honestly, not a musician yet, but we do run ads for a well known speaker with a big following, and a fashion store on Shopify. What matters here is that your fans already say yes, 3,000 votes in 15 hours is real proof. We would build the ads around Kida himself. Does that match how you see it?", "call": "Leonard Emini", "good": false, "q": "Have you worked with public figures or artists like ours before?", "s": 1386, "trick": "Honest gap, then close it", "url": "https://fathom.video/calls/271080025"}, {"a": "Luke said they have moving companies, flooring companies like Garage Floors that do well on Meta, plus a roofer and a painter, though they are bigger accounts.", "better": "Yes, home services is a big part of what we do. We work with roofing, painting, flooring and moving companies, and we know the lead to job process. I would not name numbers I cannot back up, but I can share a couple of real examples after this call. Would that help?", "call": "Eric D Shepard", "good": false, "q": "Do you do a lot of work in our industry, home improvement and services?", "s": 1238, "trick": "Real examples, no hype", "url": "https://fathom.video/calls/470388378"}, {"a": "Luke said they have no peptide clients but work with sensitive health clients like a doctor in a strict Google category, are Google partners, and have over 50 clients.", "better": "I will be honest with you, we have not run peptides yet. What we have done is health advertising where Google is very strict, and that is the hard part. I can show you one of those accounts after we decide to move forward. Would that help you feel comfortable?", "call": "Brian Rose", "good": false, "q": "Have you done Google Ads for peptides or products like ours?", "s": 879, "trick": "Admit the gap, show close proof", "url": "https://fathom.video/calls/288749754"}, {"a": "Luke said sure, but his screen share and connection were failing, and no numbers were given.", "better": "Yes, I will send you a real example with numbers. It is a Boston moving company where we run both SEO and ads, and I can show what they spend and what comes back. I will also pick one close to your world so it feels useful. Is email the best place to send it?", "call": "Mohamed Mohaimen Hany", "good": false, "q": "Do you have a case study with numbers you can share with us later?", "s": 899, "trick": "Promise proof, then deliver it", "url": "https://fathom.video/calls/358358872"}, {"a": "Luke said it is slightly competitive because they do cold email, but they do not use Facebook ads for their own lead gen, so he is okay with it.", "better": "Thanks for asking directly. Your offer is close to ours, but we sell to different people, so there is no conflict, and I would never use your ideas for anyone else. I like working with founders who know their numbers like you do. Does that feel okay?", "call": "David Marcyniuk", "good": false, "q": "Would you usually take on a client like me, given my landing page is a bit competitive with you?", "s": 946, "trick": "Name the worry, then calm it", "url": "https://fathom.video/calls/231509507"}, {"a": "Luke said yes with nonprofits and a little with gaming, asked Brian who their gamers were, and said they do their homework on any industry.", "better": "We have worked with both nonprofits and gaming brands, but I will not say we know your world better than you do. We study your market first and send you the plan, so you can fix any wording we get wrong. Would you review our plan before we launch?", "call": "Lindsey Carter", "good": false, "q": "Have you worked with the gaming market before?", "s": 1356, "trick": "Admit gaps, invite their expertise", "url": "https://fathom.video/calls/262584763"}, {"a": "Luke said they have done awareness and growth work, but they do not share client data or full campaigns, only snippets of ads, and pointed to over 100 five star reviews.", "better": "Yes, we have run growth and awareness campaigns, and I can show you ad examples. I keep client numbers private, just as I would for you. What I can do is connect you with a client who will share their own experience. Would that help you decide?", "call": "Anyro", "good": false, "q": "Do you have a case study of a client in a similar situation, growing an Instagram page?", "s": 740, "trick": "Protect privacy, offer a reference", "url": "https://fathom.video/calls/227623273"}, {"a": "Brian said Klaviyo is their first choice, easy to use, and they have a dedicated team, but he could not say which features they use and offered a follow up.", "better": "Yes, it is our first choice for email and texts, and we have a team that works in it daily. We chose it because it is easy to use and shows clear results. I will have that team send you what they build in it. Would a short call with them help?", "call": "Carolina", "good": false, "q": "Is Klaviyo in your wheelhouse, and why do you like it?", "s": 2182, "trick": "Bring in the expert", "url": "https://fathom.video/calls/274394195"}, {"a": "Luke said they have clients in both, named a medical company, but would not share details or case studies to protect client privacy.", "better": "Yes, we work with both a staffing company and a medical company. I cannot share their exact numbers, just like I would protect yours, but I can walk you through our process and set up a call with a client when you are close. Would that help?", "call": "Gio", "good": false, "q": "Do you have case studies in the medical or staffing space?", "s": 969, "trick": "Reason for the no, then offer", "url": "https://fathom.video/calls/267686901"}, {"a": "Luke said yes, they have about 50 clients including a fashion brand, lighting companies and pet food, and that they know how to do product.", "better": "Yes. We have worked with a fashion brand, lighting and pet food, so product brands are familiar ground for us. I would be glad to show you how one of those looked in the first few months. Would that help you feel sure about this?", "call": "Tiffani", "good": false, "q": "Do you work with consumer goods products like ours?", "s": 2095, "trick": "Offer a real example", "url": "https://fathom.video/calls/318560045"}, {"a": "Luke said he would send them.", "better": "Yes, I will send a few ad examples and results today. I will pick ones close to events and ticket sales so they feel real to you. Is there a result you would most like to see?", "call": "Dean Strober", "good": false, "q": "Can you send case studies or examples of the ads your team has created?", "s": 878, "trick": "Pick proof that matches them", "url": "https://fathom.video/calls/335111266"}], "intl": [{"a": "Luke said the plan must be smart and specific, using long tail and location keywords, and gave the Mudrock example with a 20 mile radius and about a $100,000 contract.", "better": "You are right, trying to rank for everything is how money gets wasted. We start with a couple of days of research on your competitors and your best paying markets. Then we pick a small set of easy wins, like one industry in one city, and grow from there. We will bring you a plan in plain words and you tell us if it feels right. Sound good?", "call": "Chris Savor", "good": true, "q": "We cannot go after everything. How do we choose which market or industry to focus on first?", "s": 1025, "trick": "Agree, then show the first step", "url": "https://fathom.video/calls/251114242"}, {"a": "He suggested one campaign across all countries at first, watch where purchases come from, then split off a campaign for the best country and move budget over.", "better": "Great thing to plan early. I would start with one campaign so Meta can learn fast, then let the sales data tell us which country deserves its own campaign and language. We would not guess, we would follow the data. Which country do you think will be your biggest?", "call": "Leonard Emini", "good": true, "q": "How would you set up ads for several countries with different languages?", "s": 858, "trick": "Let data decide, not guesses", "url": "https://fathom.video/calls/271080025"}, {"a": "Luke defended the old agency a bit, saying Meta AI finds the right people and that they would test narrow and open age ranges and let the data decide.", "better": "Your instinct makes sense, and honestly it could go either way. Meta now often does better with a wide audience. We test both a narrow and an open age range and keep what gives cheaper leads. Does that sound like a fair way to settle it?", "call": "Eric D Shepard", "good": true, "q": "You said Facebook ads at 18 to 65 plus is wasteful, are you saying our agency was wrong?", "s": 1649, "trick": "Agree, then let data decide", "url": "https://fathom.video/calls/458078657"}, {"a": "Luke said it is a little trickier but they can translate with AI and it is not a massive deal.", "better": "Yes, we can. French is not our first language, so I will not pretend it is nothing. We would write in English, translate, and ask you to check the wording since you know your customers best. That keeps it accurate and keeps it quick. Would you be happy to review the French?", "call": "Mathieu Bolle", "good": false, "q": "We speak French here, could you manage it?", "s": 506, "trick": "Admit the gap, share the work", "url": "https://fathom.video/calls/545661967"}, {"a": "Luke said the team may know better, but location may matter less than the words people use to find a bespoke custom build, since anyone building has money.", "better": "Great question. Your best clients came from Chile, America and Switzerland, so I would test those first. We also target the words people type, like custom home architect. Then we watch which places bring good inquiries. Does that sound fair?", "call": "Alexandra Bailey", "good": false, "q": "Which locations should I target, since my clients are all over the world?", "s": 1693, "trick": "Use their own wins as a guide", "url": "https://fathom.video/calls/527818977"}], "lower": [{"a": "Luke said there is nothing he can do at a flat $1,500, websites start around 6,000 and his average client spends about 5,000 a month, though you can find people for 1,000 to 1,500.", "better": "I hear you, you want to spend smart and keep it simple. I will be honest, at $1,500 I would not do a good job and I do not want to waste your money. What I can do is split it in two steps: the emails first, the website next, so you do not have to find the full amount at once. Would it help if I mapped out what step one would cost?", "call": "Gina Johnston", "good": true, "q": "Can you do something for my $1,500 budget?", "s": 1824, "trick": "Honest no, then smaller step", "url": "https://fathom.video/calls/227574741"}, {"a": "Luke said he could bring the fee down to $1,000 for him and would hold the price that day, and asked him to keep it confidential.", "better": "Thank you for being open about that. I do not want to win on price alone, I want you to feel safe. I can do $1,000 a month for the fee because your budget is small, and the difference you are paying for is a US team that treats your ads like their own. Can I send you a short one page offer?", "call": "Cesar Diaz", "good": true, "q": "Other agencies offer half your price, can you go cheaper?", "s": 893, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/860109475"}, {"a": "Luke said people charge more because they have a team and get results, and that a cheaper SEO person might leave you waiting six months for nothing.", "better": "That is fair, you should compare. I will not tell you the cheaper option is bad. I would just ask who does the work, who makes the creative, and how fast they will tell you if something is not working. If they answer well, go with them. If not, I would love to show you how our team does it.", "call": "John Cho", "good": true, "q": "You are the highest price I found. Why should I pay more than the $1,500 option?", "s": 2842, "trick": "Invite them to compare fairly", "url": "https://fathom.video/calls/320715151"}, {"a": "Luke said Meta ads start at 1,500, brought it down for her nonprofit with a 1,000 dollar ad spend, for roughly 2,200 a month in total.", "better": "Yes, one platform is the right way to start, and I do not want you stretched. I would pick Facebook and Instagram because that is where parents are. For a nonprofit I can lower our fee, and you add about 1,000 in ad spend. Want me to write that out so you can take it to your partners?", "call": "Erin Rosenstock", "good": true, "q": "Is there a cheaper version, maybe only one platform, since we are so small?", "s": 513, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/262474173"}, {"a": "Luke said they would not go crazy, and that he would look at Google and test cold email lightly instead of going all in.", "better": "I hear you, and I will not push you into something that stretches you. We can start small, test one channel and see the first sale before adding more. I will have my team build a lighter plan that keeps cash flow safe. Is a smaller start what you would like?", "call": "Gregory Corbin", "good": true, "q": "I cannot afford the $10,000 package. Can we do something smaller?", "s": 1091, "trick": "Protect them from overspending", "url": "https://fathom.video/calls/325605508"}, {"a": "Luke said it was an interesting idea but they could not take him on as a client and it was not their specialty.", "better": "That is a smart way to think about it. A small site for around $3,000 is not something we build, so I would not want to say yes. A freelancer can do the simple site, and when you see sales, we would love to talk about ads. Can I keep your details for then?", "call": "Yesset Karayev", "good": true, "q": "Can you give me a first step offer, a simple website around 3k plus part of your management?", "s": 2319, "trick": "Say no kindly, leave the door open", "url": "https://fathom.video/calls/455546501"}, {"a": "Luke said it is a lot of work, showed a similar Apple client with ROAS above seven, then offered $2,000 only if he moved forward that day.", "better": "I like that you want to grow step by step, that is smart. I cannot go to 1,500 because the work is the same on day one. What I can do is start you at $2,000, no lock in for the first weeks, and raise it only when sales grow. Does that feel fair to you?", "call": "Mathieu Bolle", "good": true, "q": "Can we start lower, maybe 1,500 and go up month by month?", "s": 744, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/545661967"}, {"a": "Luke said it is a little too low, that they need at least $1,500 to manage plus $1,000 ad spend minimum, and offered to find a cheaper freelancer.", "better": "Thank you for asking up front, I respect that. Honestly, we would not do a great job for you at that level, because management alone starts higher than your whole budget. I would rather point you to someone who fits. Can I send two freelancers I trust?", "call": "Konstantin Genkin", "good": true, "q": "Is a budget of a bit under 1,000 pounds a month too low for you to work with?", "s": 102, "trick": "Honest no with a helpful handoff", "url": "https://fathom.video/calls/329568754"}, {"a": "Luke said yes if you do more than one thing, but margins on cold email are tight, and he would discuss it when the time comes and said the cold email price will rise toward 10k.", "better": "Yes, when you bring more than one service, I can look at the bundle price. I would ask that we start with Meta and Google first, then add email in a month or two. That way you see results first. Shall I put together a bundle for you and your partner?", "call": "Joseph Gissy", "good": true, "q": "Is there any wiggle room on price if we do more than one service?", "s": 1943, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/230308235"}, {"a": "Luke said it is mid range for the US, freelancers may charge about $1,000 but have no team, and they lowered their price a bit to keep clients long term.", "better": "Right, $2,500 is the fee and your ad spend is on top. Freelancers can be cheaper, but you get one person, not a strategist, editor and buyer working together. We keep the price fair because we want you for years. Does that help you compare?", "call": "Dean Strober", "good": true, "q": "So it is $2,500 a month for management and then ad spend on top, right?", "s": 924, "trick": "Fair comparison, no pressure", "url": "https://fathom.video/calls/335111266"}, {"a": "Luke said the normal fee is $1,500 but he would bring it down to $1,200 a month to manage, and noted he did not want to eat into ad spend.", "better": "I get it, you are early and every dollar counts. Normally it is $1,500, but for a test I can do $1,200 because I want your ad budget to do the work. In return, we agree to look at results together after month one. Does that feel fair?", "call": "Justin Mitchell", "good": true, "q": "Your price is on the high end for me, can you do anything on the fee?", "s": 2532, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/464049834"}, {"a": "Brian said they could do $1,500 for Meta ads including creatives, and later said he agreed with Luke on 1,500.", "better": "Yes, I can honor that. It is $1,500 a month for Meta management, and the designer's work is part of it. I want you to feel good about the price, so let me confirm the video details and send it all in one email today. Does that work?", "call": "Purepiel", "good": true, "q": "Luke said we could do 1,500 if we leave Fiverr, is that right?", "s": 2202, "trick": "Honor the promise fast", "url": "https://fathom.video/calls/272300366"}, {"a": "Luke said the normal price is $1,500 a month for Google Ads but he could drop it to $1,000 confidentially because the business is new.", "better": "I will be straight with you: our normal fee is $1,500, but you are new and doing well, so I am happy to start you at $1,000 a month. I do that so we can prove it works and grow together. Does that sound like a fair place to begin?", "call": "Michael Cash", "good": true, "q": "Can I start with my small budget?", "s": 494, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/867124558"}, {"a": "Brian said SEO is $2,500 and the paid package is $2,500, but he could bring all three to $4,000 for him.", "better": "Yes, bundling helps us, so I can do all three for $4,000 instead of $5,000. That works because we can share the strategy and reporting across the team. Would you like to start with all three or just paid ads first?", "call": "Brian (mock call 1)", "good": true, "q": "Can you give me a discount if I do Facebook ads, Google ads and SEO together?", "s": 2619, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/267787294"}, {"a": "Luke offered $2K a month for six months with ad spend capped at 15K, then to reevaluate, and said he was open to negotiating.", "better": "That is a fair concern, margins matter. Here is what I can do: a flat $2,000 a month for six months while your spend stays under $15K, so we can prove it with your numbers. Does that feel safer?", "call": "Mark H", "good": true, "q": "If I spend 10,000 and pay you 5,000, I do not think I make enough profit for that.", "s": 2611, "trick": "Make a clear, safe offer", "url": "https://fathom.video/calls/524683610"}, {"a": "Luke said the creative fee can be waived for a small campaign, so it would stay at 1,500 if they are ready to go.", "better": "It would be 1,500. Because your budget is small, I will drop the creative fee, and it is a real saving. I do that when I believe we can make it work. Does that fit where you are?", "call": "Shiv Patel", "good": true, "q": "For Facebook alone, is it 1,500 plus 500 for creative?", "s": 807, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/242052539"}, {"a": "Luke said 4,500 is already reasonable, that cheaper providers cannot personalize properly, and that cold email fails about 30 percent of the time.", "better": "I hear you, Frank, that is a real number for a business your size, and I would feel the same. I do not want you to spend money that stretches you. The honest truth is cold email needs a few months to learn what works, so a one month test would not tell you much. Can I show you two cheaper ways to get your first national lead, and then you decide?", "call": "Frank Modarelli", "good": false, "q": "4,500 a month is not sustainable for me, is there any way to do a month or two to test the waters?", "s": 960, "trick": "Honor the budget, offer options", "url": "https://fathom.video/calls/264528192"}, {"a": "Brian pointed to the included designer and daily care, then offered to bring the price down to $1,500.", "better": "I hear you, and with the retreat costing you already, I want to keep this easy. We do not usually have an intro rate, but I can start you at $1,500 for the first stretch, because I want you to see results before you pay full price. We can look at it again after the retreat. Does that help?", "call": "Chris Bilyk", "good": false, "q": "The 1,800 is a little steep. Is there an introductory rate?", "s": 2037, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/271182973"}, {"a": "Luke said the call taker could not decide on price but would pass the note to Luke, who might offer a special deal for the first three months.", "better": "Thank you for saying that so clearly, and you are right that one campaign should not cost the same as five. Let me ask Luke to look at a smaller plan for your single campaign and send you a real number this week. You deserve a fair price for what you need. Would that work for you?", "call": "Leah Vogt", "good": false, "q": "Our pricing is usually 1,000 to 1,500 and I only run one campaign at 50 dollars a day, so this seems steep. Can you do a custom quote?", "s": 1038, "trick": "Thank them for the honest feedback", "url": "https://fathom.video/calls/347069031"}, {"a": "Luke said they do not work like that, that they are expensive and work with companies making $1 to 10 million a year, and quoted about $25,000 for a year.", "better": "I understand wanting a number you can plan around. Our work is monthly at $2,400, so a year would be about $28,800, and I do not want to lock you into more than you can afford. If that is too much right now, the $1,000 plan is a good start. What budget feels comfortable to you?", "call": "Kevin Huang", "good": false, "q": "Can we fix a total budget at the start instead of paying monthly?", "s": 1316, "trick": "Respect their limit, offer a step", "url": "https://fathom.video/calls/300079094"}, {"a": "Luke said it depends, then said their price is fixed for most spend levels, and explained the team does strategy, creative and daily management so the client does not have to.", "better": "I hear you, and I would feel the same way. Smaller spend is a little less work, but the setup, creative and watching it daily is still needed. For your size, I would rather lock down one channel first and prove it pays back. Would a smaller starting plan make this feel safer?", "call": "Christian Hoeffel", "good": false, "q": "If I spend less, is it not less work? Why do prices seem so high for my budget?", "s": 1220, "trick": "Echo their words first", "url": "https://fathom.video/calls/317379106"}, {"a": "Luke said he had to jump to another call, that even stripped down he could not go below about 5k, and asked her to email if she could stretch the budget, then offered 500 a month for 10 months.", "better": "Thank you for telling me that number, it really helps. With $6,000 I can do the email sequence and the key fixes to your site, and I would keep the rest simple. I will write up exactly what that includes so you can see it in black and white. Can I send it to you today?", "call": "Gina Johnston", "good": false, "q": "We have $6,000 to put toward this, can it be set up now?", "s": 1973, "trick": "Turn their number into a plan", "url": "https://fathom.video/calls/227574741"}, {"a": "Luke said the prices are not the cheapest but do not price clients out, and that multiple locations are priced one by one, then asked about company revenue.", "better": "I appreciate you being honest about timing. Since the number does not scare you, a smaller first step may fit better than the full service. We could start with a tracking review now and grow into full management when you are ready. Would that work with your boss?", "call": "Jessica Wagner", "good": false, "q": "We are not big enough yet for the budget, is there a way to start smaller?", "s": 520, "trick": "Offer a smaller first step", "url": "https://fathom.video/calls/459408894"}, {"a": "Luke said ReachGiant does not do consulting or one off fixes, they take over the full account, and Ken said it was not a fit right now.", "better": "I hear you, a drop from $30 to $100 per lead hurts, and you only need a fix. On $10,000 a month, saving even a few dollars per lead would more than cover our fee. Would it help if I looked at the account for 15 minutes and showed you where the money is leaking?", "call": "Ken", "good": false, "q": "Can you just fix our account for a lower price, we only have $500 a month?", "s": 721, "trick": "Show the cost of doing nothing", "url": "https://fathom.video/calls/342310585"}, {"a": "Luke said the lowest package is 1,500 for base SEO, but with only 5,000 in revenue she is pretty tight, and a 500 provider likely would not get results.", "better": "I respect you being upfront. Our lowest package is 1,500 a month, which is the Liftoff plan. I will be honest that it is a big step at your income, so I only want you to start if it makes sense. Can we look at how a few extra clients would pay it back?", "call": "Kay Pollard", "good": false, "q": "Do you offer anything lower than 5,000, since I am a business of one?", "s": 480, "trick": "Honest about fit, then tie to return", "url": "https://fathom.video/calls/241212547"}, {"a": "Luke said they start at 1,500 a month for Google Ads but would drop it to 1,000 to show what they can do, only if they decide today.", "better": "With a small budget I want it to make sense for you. Our usual fee is 1,500, and I can do 1,000 to start because I think we can win you as a long term client. No pressure to decide today, what would you need to see to feel good about it?", "call": "Safa", "good": false, "q": "Can you go cheaper, given our small ad spend?", "s": 1310, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/259170120"}, {"a": "Luke said it could be broken up, that 20,000 is the base, and that it would not go above that for their size.", "better": "Good question. Yes, we can split it into phases, like brand first, then the website build, so you are not paying it all at once. I would not want you to feel locked in. Want me to put a phased version in the follow up email?", "call": "Jade Pyne", "good": false, "q": "Can this be broken into phases, or do I just owe you 20,000?", "s": 1673, "trick": "Make the big price feel safe", "url": "https://fathom.video/calls/242102912"}], "notdo": [{"a": "Luke said they do web development, design and branding, Google paid ads, AI search and Meta ads, and that they stopped LinkedIn and cold email because it is too saturated.", "better": "Yes, I can help with the simple message and the website, and that is where I would start. I will be honest, we do not do LinkedIn or cold email anymore because everyone gets flooded and it stopped working well. I would rather tell you that now than take your money for something we are not great at. Would it help if we looked at one clear offer first?", "call": "Greg Laskody", "good": true, "q": "Can you help me with that? Is that what ReachGiant and your team does?", "s": 896, "trick": "Honest no, then a clear yes", "url": "https://fathom.video/calls/804786478"}, {"a": "Luke said it was strong two years ago, got harder in the past 12 months, and ReachGiant now focuses on Google Ads where it has a 90% success rate; he offered to review with his email lead.", "better": "Honestly, it was great two years ago and got much harder last year. Inbox rules tightened and everyone started sending the same emails. We do not want to take your money unless we think it can work. Let me have my email lead look at your market, then I will tell you straight. Does that sound fair?", "call": "Conal Brady", "good": true, "q": "When did cold email stop working, and why?", "s": 405, "trick": "Be honest about what you do not do", "url": "https://fathom.video/calls/541074501"}, {"a": "Luke said it was not a fit because they work with companies that sell from their own websites and cannot help with Facebook Marketplace or Google Maps.", "better": "Thank you for explaining your business so clearly. I want to be honest, we do best when ads lead to your own website, so I do not want to take your money and under deliver. You have two good paths, a simple site of your own or local Google Maps reviews. Can I point you to the best first step?", "call": "Yesset Karayev", "good": true, "q": "Can you help me with marketing when I sell on a third party auction site?", "s": 1408, "trick": "Honest no that still helps", "url": "https://fathom.video/calls/455546501"}, {"a": "Luke said they do not shoot the products, she would provide existing photos and videos, and the team would edit them and suggest what else to capture.", "better": "Good thing to ask. We do not shoot your products, but we do everything after that: edits, ads, images and reels. You send what you have, and we will tell you exactly what extra to film. Your story is a big asset too. Do you have any footage of your grandfather's farm or the kitchen?", "call": "Tiffani", "good": true, "q": "Do I need to shoot the product content, or send samples to you?", "s": 1811, "trick": "Say what you do not do, plainly", "url": "https://fathom.video/calls/318560045"}, {"a": "Luke said no, ReachGiant does not do UGC, Sam would need influencers or supplier videos, and later said trust on the landing page matters most.", "better": "We do not make UGC, and I would rather tell you that now. Many suppliers already have product videos you can ask for, and that is a free place to start. For your first sales, a clean page that builds trust matters even more than video. Want me to point out what to fix first?", "call": "Sam Daoud", "good": true, "q": "Do you make UGC videos for me, or do I have to do it myself?", "s": 932, "trick": "Say no, then give a workaround", "url": "https://fathom.video/calls/551904290"}, {"a": "Luke said yes, they will look at the LSA, check conversion tracking and landing pages, and fix them or suggest changes.", "better": "Yes, that is part of it. We would look at why LSA went quiet first, probably the setup or bidding, and tell you what we find. We will also check your tracking so you can see calls and forms. Want to share your LSA access after you start so we can get on it day one?", "call": "Michael Cash", "good": true, "q": "Does the $1,000 include fixing my Google LSA problem?", "s": 1936, "trick": "Say yes, then say how", "url": "https://fathom.video/calls/867124558"}, {"a": "Luke suggested a freelancer and told him to split the project into steps, build the website first and then find someone to run ads.", "better": "I am glad to help. I would split it up, first a simple site from a freelancer, then local reviews on Google Maps, then ads once you see what sells. One person who does everything is rare and costly. Would a short list of what to ask a freelancer help?", "call": "Yesset Karayev", "good": true, "q": "What advice can you give me to find a smaller company to work with?", "s": 2407, "trick": "Give a useful next step", "url": "https://fathom.video/calls/455546501"}, {"a": "Luke said they can pay influencers for posts using apps, around $200 each, and then use those posts in Facebook ads.", "better": "Yes, I like that for social workers, because people trust someone in their own field. We can pay creators or offer an affiliate cut, then run their posts as ads to reach more people. I will include that in the plan I send you. Does that sound right?", "call": "Jason Adkins", "good": true, "q": "Can you get influencers to be affiliates for us?", "s": 1404, "trick": "Validate their own idea", "url": "https://fathom.video/calls/325652328"}, {"a": "Luke said they offer Google Ads, Facebook ads and warm email like Klaviyo, but no longer offer cold email.", "better": "Fair question, and I am sorry cold email is not on the menu. We stopped because it stopped working well for our clients. What we do offer is Google Ads, Meta ads, SEO and warm email. What is the main thing you want them to do for you?", "call": "Daniel", "good": true, "q": "What kind of services do you offer?", "s": 120, "trick": "Honest no, then redirect", "url": "https://fathom.video/calls/286220389"}, {"a": "Luke said yes, they have a designer who edits video for Facebook and Google Pmax, and have done UGC for two or three clients using an influencer app.", "better": "Yes, we make video ads in house and have done UGC for a few clients, though not hundreds. I will send you some examples so you can judge the quality yourself. Is it more for cold leads or for your past customers?", "call": "Andrew Silagy", "good": true, "q": "Do you do video marketing for ads, or UGC content?", "s": 2240, "trick": "Honest scope plus examples", "url": "https://fathom.video/calls/341420869"}, {"a": "Luke said they do not sell leads, they run Google and Meta campaigns that get leads from the platforms for the client.", "better": "Good question. We do not sell leads. We run your own ads so the leads are yours alone, and nobody else gets them. You own the ad account and the data. Does owning your leads matter to you?", "call": "Michelle Johns", "good": true, "q": "Do you sell exclusive leads, shared leads, or system builds?", "s": 125, "trick": "Turn a no into a benefit", "url": "https://fathom.video/calls/537594627"}, {"a": "Luke said ReachGiant can handle Amazon and may add it soon, but has focused on Google and Facebook for the past couple of years.", "better": "Thanks for asking straight out. Amazon is not something we do today, and I would rather tell you that than learn on your money. Where we can help is sending shoppers from Google and Facebook to your own Shopify store, which you will own for the long run. Would it help if I pointed you to someone good for the Amazon side?", "call": "Barry Smoak", "good": false, "q": "You said you do not do Amazon, so can you still help me?", "s": 797, "trick": "Honest no, then a useful path", "url": "https://fathom.video/calls/283039215"}, {"a": "Luke said they do not do video or photography and only focus on the marketing side, and said they could make recommendations.", "better": "We do not shoot video or product photos ourselves, and I would rather stay great at ads than be average at everything. What we do is write the ideas and scripts, and then we tell you which clips are working. I can also suggest a few people who shoot for a fair price. Would that give you what you need?", "call": "Barry Smoak", "good": false, "q": "Do you have content creators who can shoot videos and commercials?", "s": 841, "trick": "Say no, then offer a bridge", "url": "https://fathom.video/calls/283039215"}, {"a": "Luke said no, email templates are not included and would be a separate project.", "better": "Not in the base price, that is a separate small project. But it is easy once the brand is set, because templates just follow your guideline. I would do it right after the brand so you get the full payoff. Would you like me to price it out as a next step?", "call": "Jade Pyne", "good": false, "q": "Do we get email marketing templates as part of this too?", "s": 1834, "trick": "Turn a no into a next step", "url": "https://fathom.video/calls/242102912"}, {"a": "Luke said no, they tried LinkedIn outreach automation but it was not profitable, and LinkedIn ads are simple enough that anyone can run them.", "better": "Not right now. We tried it and could not get results worth charging for, so I would rather say no than sell you something weak. Google and Meta are where we are strongest. If LinkedIn ever becomes a priority, I will tell you who I trust. Fair?", "call": "Mark H", "good": false, "q": "Do you also work with customers using LinkedIn ads?", "s": 847, "trick": "Say no to build trust", "url": "https://fathom.video/calls/524683610"}, {"a": "Luke said they do Klaviyo but charge separately, and that she probably does not need it yet and could handle it herself.", "better": "That is a smart thing to ask, because speed after sign up matters a lot. We can set it up as a small extra, or I can give you the simple emails to run yourself. With your volume, I would start simple and add us later. Which would you prefer?", "call": "Christy Acton", "good": false, "q": "Would the automatic email nurture for new sign ups be part of what you do?", "s": 2482, "trick": "Offer two easy choices", "url": "https://fathom.video/calls/358280745"}, {"a": "Luke said they do not take small one off jobs like that, they only want ongoing client relationships.", "better": "Good idea, and I would not want to hand you a rushed job. Writing emails by themselves is not something we sell alone. But once you are a client, we can build the copy into your plan so it fits the ads. Want me to include that in the quote?", "call": "Joseph Gissy", "good": false, "q": "Could you write 52 nurture emails for us as an add on?", "s": 2322, "trick": "Say no, then offer a yes", "url": "https://fathom.video/calls/230308235"}, {"a": "Luke said they have entertained it for bigger brands and it would come at a cost, but it is not something they usually do.", "better": "We can, and it makes sense with a team of nine. I'd do it as short sessions where we walk through your own account, so they learn on real work. It's an extra cost, and I'd set the price once I know your goals. Would that help your team?", "call": "Tori Hudson", "good": false, "q": "Do you offer Google Ads training for our team?", "s": 647, "trick": "Say yes with a clear shape", "url": "https://fathom.video/calls/562647779"}, {"a": "Luke said they do YouTube ads through Google Ads and can give keyword advice, but do not upload videos or specialize in YouTube search.", "better": "Good thing to ask. We can run YouTube ads and give you the keywords to use when you upload. We do not edit or upload videos for people, so I would not want to oversell that. Would ads or keyword help be more useful to you?", "call": "Jennifer Metcalf", "good": false, "q": "What do you do on the YouTube side?", "s": 673, "trick": "Say what we do not do", "url": "https://fathom.video/calls/247960459"}], "onboard": [{"a": "Brian said they send a Stripe payment link and a month to month scope of work, an onboarding form, then a call with the general manager and account manager. Existing ads can be worked on right away and new ads launch in days to a week.", "better": "It is simple. You pay through the link, fill out a short form, and the team contacts you right away to book a call, usually within 48 hours. Since you already have ads, we start on those first and launch new ones within a few days. I will send you the account manager's name once it is set. Want me to send the link today?", "call": "Chris Bilyk", "good": true, "q": "What are the next steps, how fast would you start, and who would be the account manager?", "s": 2495, "trick": "Make the next step easy", "url": "https://fathom.video/calls/271182973"}, {"a": "Luke said the site would jump the queue, the design would be ready in days, and go live in two or three weeks alongside the cold email setup, with 5,250 paid up front and the cold email paid monthly a month later.", "better": "Here is how it would go. You pay 5,250 today, your site goes to the front of the line, and we start the cold email setup the same day. Your site is live in about two or three weeks while the domains warm up. After that it is a simple monthly payment. Would you like me to send the plan in writing so you can look it over?", "call": "Doug Fiore", "good": true, "q": "If I do the website and the outreach together, how soon can we start and how would I pay?", "s": 3553, "trick": "Walk through the first days clearly", "url": "https://fathom.video/calls/242167771"}, {"a": "Luke explained the team of eight, around 50 clients, a first seven day workbook of competitors and keywords, then content, manual backlink outreach and relevant traffic.", "better": "Of course. In the first seven days we build a plan: who you compete with, which keywords bring buyers, and what to fix. Then each month we create content and do real outreach to get you links. I will keep it simple and show you what is happening every month. What matters most to you, residential jobs or commercial?", "call": "Stefan Gutowski", "good": true, "q": "Can you break down exactly what your game plan would be for us?", "s": 239, "trick": "Simple steps, then ask about goal", "url": "https://fathom.video/calls/293071198"}, {"a": "She explained cold email covers lead lists, verification, custom emails, sending and reports on positive reply rate, and SEO covers blogs, backlinks, keyword clusters and a workbook.", "better": "Of course, you deserve to know exactly what you are paying for. Step one is research on you and your buyers, step two is building and checking the lead list, step three is writing personal emails, then we send, test and report every week. I can send a one page version so you can compare us side by side. Want that?", "call": "Ricardo Amaya", "good": true, "q": "Can you walk me through the process and what we are paying for? Other vendors explained it in detail.", "s": 390, "trick": "Walk it as simple steps", "url": "https://fathom.video/calls/269795639"}, {"a": "Matthew said it will hold keyword research, the full launch structure, new ad copy and a place for Ali to comment or cross out keywords, with a Loom video walking through each tab.", "better": "It's the plan for what we're about to do, so you can see our starting point before we go live. It has the keywords, the campaign changes and the new ad copy. You can comment or cross out anything you don't like, and I'll record a short video that walks you through each tab. Does that give you enough control?", "call": "Ali Kamel", "good": true, "q": "Will the spreadsheet show what you have done or what you plan to do?", "s": 2524, "trick": "Give them a voice in the plan", "url": "https://fathom.video/calls/827514516"}, {"a": "Luke said even a small campaign can have 160 ads, several objectives like lead gen, awareness and email building, plus creatives, data checks and new split tests.", "better": "Fair question, you deserve to know what you pay for. Each week we build new ads, check what is working, turn off what is not, and test new ideas. Because you have run ads before, we skip the basics and focus on your 1.2 to 1.3 return and how to grow it. Want me to share what week one would look like?", "call": "David Marcyniuk", "good": true, "q": "What would the 1,500 a month actually cover week to week?", "s": 854, "trick": "Make the work visible", "url": "https://fathom.video/calls/231509507"}, {"a": "Luke said she gets strategy, daily management, multiple campaigns, sometimes 160 ads at once, and watching CPC and conversion rate, with the 500 creative fee included.", "better": "You get a whole team. We plan the strategy, build the ads, test many versions, and watch the numbers every day, like cost per click and sales. Each week we send a short video that shows what we did. You focus on your brand, we focus on the ads. What part of this is hardest for you to do alone today?", "call": "Temisan", "good": true, "q": "What do I get for the 1500?", "s": 1213, "trick": "Paint the day to day picture", "url": "https://fathom.video/calls/229608484"}, {"a": "Luke said they do everything in Klaviyo, including the technical side, flows, new campaigns and the existing ones, plus a strategy for what to send and how often.", "better": "Great question. We would start with the flows and list you already have, since those are making you money. We fix what is weak, add new flows, and plan the weekly emails so you do not have to. You will see what we change and why. Would it help if I sent you a short list of what we would check first?", "call": "Tiffani", "good": true, "q": "For Klaviyo, will you work with our existing flows and list or only new things?", "s": 1671, "trick": "Start from what already works", "url": "https://fathom.video/calls/318560045"}, {"a": "Daniel said you get a payment link and a 5 to 10 minute onboarding form, then about one month to warm things up, with traffic picking up around month two.", "better": "It is simple. You pay, you fill in a short form in about ten minutes, and we meet the team. We usually launch ads in the first week or two, and then spend the first month testing so we find what works. By month two or three you should see clear patterns. Does that timeline fit what you had in mind?", "call": "Kristina Shumilova", "good": true, "q": "If I say yes, what do we do and how long until my campaign goes live?", "s": 1707, "trick": "Walk them through step by step", "url": "https://fathom.video/calls/234074760"}, {"a": "Luke said they use an onboarding form, a team brief and a 30 to 60 minute kickoff, and would be up to speed within a week with weekly updates.", "better": "A week is realistic to be fully up to speed. You fill out a short form, my team reads both calls before they meet you, and the next day we sit down for about an hour. We work on your old account while we build the new one, so you do not lose momentum. Does that sound like the pace you need?", "call": "Jennifer Metcalf", "good": true, "q": "How long will the transition take before we start cooking again?", "s": 1215, "trick": "Walk through the first week", "url": "https://fathom.video/calls/247960459"}, {"a": "Luke said after payment link, onboarding form and a small contract, Matthew Overbay does an onboarding call and they get to work right away, building a plan with keywords, competitors and negatives.", "better": "Fast. Once you say yes, we send the form and a short agreement, and Matthew calls you within a day or two. Then we build the plan, which usually takes about a week. Since registration opens in May, we have plenty of time to get tracking right first. Does that timing work for your team?", "call": "Tori Hudson", "good": true, "q": "How long from saying let's get started to deploying?", "s": 424, "trick": "Tie timeline to their date", "url": "https://fathom.video/calls/562647779"}, {"a": "Luke said they send a contract with a scope of work, a three month term, no ownership of the client's ad accounts, then a payment link and a 30 minute onboarding form.", "better": "Yes. I will send a short contract with the scope, a payment link, and a 30 minute form about your business. You always own your ad accounts, and after three months we go month to month. Then the team gets to work right away. I will have it to you by end of day tomorrow, does that work?", "call": "Christian Hoeffel", "good": true, "q": "Could you send a proposal? What do the next steps look like?", "s": 3190, "trick": "Walk through simple next steps", "url": "https://fathom.video/calls/317379106"}, {"a": "Luke described an initial workshop, brand ideas, a design file for review, then a rebuild of the site with brand guidelines and logo files, with a final design in about four weeks.", "better": "You get a kickoff workshop with our designer and my manager, then brand ideas and a full design for your approval. Nothing gets built until you love it. After that, we rebuild the site and hand you the logo files, brand guidelines and mood board. Does that match what you hoped to get?", "call": "Jade Pyne", "good": true, "q": "What do we receive for 20,000?", "s": 1708, "trick": "Paint the picture step by step", "url": "https://fathom.video/calls/242102912"}, {"a": "Luke said the team manages the Google Ads daily, including search terms, negatives, ad groups, campaigns, conversion tracking and split tests.", "better": "Good thing to ask. Every day we check the search terms, block the wasted clicks, test new ads and make sure every lead is tracked. Think of it as someone watching your account like a hawk so you do not have to. Want me to write that out as a one page list you can show your president?", "call": "Jeroen Reuven Bours", "good": true, "q": "When you say you run the ads, what do you mean by that?", "s": 305, "trick": "Plain picture of daily work", "url": "https://fathom.video/calls/259216207"}, {"a": "Luke said yes, the team handles strategy, planning, testing and analysis, and that they only take on ongoing management, not one off pixel setups.", "better": "Yes, it covers it all. We set up the tracking, plan the tests, and watch the numbers daily. Since you already have content, we can focus on what to test first. We do not do one off setups, because the real value comes from months of improving. Does that match what you want?", "call": "Anyro", "good": true, "q": "So that 1500 package covers everything, setup, testing, all of it, even though we already have content?", "s": 565, "trick": "Say what you do and do not do", "url": "https://fathom.video/calls/227623273"}, {"a": "Luke said they get access to the ad account, break down and rebuild the campaigns, set up conversion tracking, check the landing pages and work on it daily.", "better": "Simple. You give us access, and on day one we audit your account to find where money is leaking. Then we rebuild the campaigns, fix your call tracking and check your landing page. After that we work on it every day and send you results. Want me to send the access steps?", "call": "After hours alcohol delivery prospect", "good": true, "q": "How does your agency work?", "s": 410, "trick": "Walk through it in simple steps", "url": "https://fathom.video/calls/858246139"}, {"a": "Luke said it is about the roadmap and that he would write a plan, get the logos into a Figma file, a website plan and a marketing plan within a week.", "better": "You have done a lot already, so just send me everything you have, even rough. In a week I will bring a website plan, a marketing plan, and a price, so you can say yes or no. And your $1,000 goes toward it or comes back if it is not a fit. Does that feel simple enough?", "call": "Brett Hines", "good": true, "q": "What can we give you so we can keep the ball rolling?", "s": 3079, "trick": "Lay out next steps and the safety net", "url": "https://fathom.video/calls/293124897"}, {"a": "Luke said they would not make quick risky moves, would fix wasted spend immediately, then in 5 to 6 days present a new plan on a call before going live.", "better": "We will never make a big move without running it by you. In the first days we clean up wasted spend in the running campaigns, and in about 5 to 6 days we show you the new plan. Then we adjust every week or two. Does that timing work with how busy you are this week?", "call": "Michael Cash", "good": true, "q": "If something gets flagged, what then, and how fast will you act?", "s": 1681, "trick": "Walk the first week", "url": "https://fathom.video/calls/867124558"}, {"a": "Luke said week one is keyword research, planning, a look at Google Business reviews, then ongoing articles, backlinks and technical fixes.", "better": "Sure. Week one we study your market, keywords and Google Business profile. Then we make a plan, and you approve it. After that we write articles, build links and fix the technical side. You would see progress in reports as we go. Want me to send you a sample plan?", "call": "Kay Pollard", "good": true, "q": "Can you walk me through the process on the lowest package?", "s": 960, "trick": "Simple step by step map", "url": "https://fathom.video/calls/241212547"}, {"a": "Luke said it is not about the number of campaigns, they would run a lot more than one, test many things, and move budget toward what works.", "better": "Good thing to ask. It is not a set number of campaigns. We run what the data shows is needed, usually several, with tests and new ads each month. Right now you have one campaign, so you will see a big difference. Want me to list exactly what we would set up first?", "call": "Eric D Shepard", "good": true, "q": "How many campaigns do we get for the $1,800, and what exactly is included?", "s": 1169, "trick": "Answer with a concrete picture", "url": "https://fathom.video/calls/458078657"}, {"a": "Luke said the first week is research and planning, then they open several tests at once and keep adjusting forever.", "better": "Simple version: week one we study your competitors and your best families and make a plan. Then we launch a few tests together, see which wins, and put the budget there. You see everything before it goes live. Does that fit with your winter registration timing?", "call": "Mike Worden", "good": true, "q": "How does it typically work, what is your process?", "s": 560, "trick": "Three step simple picture", "url": "https://fathom.video/calls/831260309"}, {"a": "Luke said Stripe is the best way, they pay about 2.8 percent, it is automated, and she can cancel or ask for a refund any time.", "better": "I love that you care about this, Erin. Stripe costs us about 2.8 percent, and it keeps billing easy so we can focus on your ads. You can cancel any time, and if you ask for a refund we will do it. If a bank transfer is much better for you, let me check. Okay?", "call": "Erin Rosenstock", "good": true, "q": "Can I pay a different way than Stripe so you lose less money to fees?", "s": 1767, "trick": "Respect their values", "url": "https://fathom.video/calls/262474173"}, {"a": "Luke said yes, everything: Matthew would lead onboarding, they would use an onboarding form, study competitors, link to his Facebook and Google accounts and present a plan.", "better": "Yes, we do all of it, so you do not carry that weight alone. First comes a short form, then a call with Matthew, my manager. We look at your accounts and your competitors, then show you the plan before we change much. Does that sound like the help you want?", "call": "Mathieu Bolle", "good": true, "q": "If we start, do you build the strategy?", "s": 844, "trick": "Walk through simple first steps", "url": "https://fathom.video/calls/545661967"}, {"a": "Luke said she fills a 15 minute intake form, the team books a call, researches, and launches ads in about a week to 10 days, then adjusts and sends reports.", "better": "It is a mix of both. You fill a short form, about 15 minutes, then the team talks with you to learn your ideal client and the words they use. We do the research and launch in about a week. Then you get a monthly report. Any part you want me to explain more?", "call": "Alexandra Bailey", "good": true, "q": "How do you work out my target market and areas?", "s": 1036, "trick": "Walk through steps and timing", "url": "https://fathom.video/calls/527818977"}, {"a": "Brian said they send a payment link and the contract, then an onboarding form, a team intro call, and then set up the account and conversion tracking, and the account stays yours.", "better": "Easy. You get a payment link and a short contract. Then a form that takes about 15 minutes, and a call to meet the team. We set up the account and tracking, and it is always your account. You can be live in about a week. Shall I send it tomorrow morning?", "call": "Kyle", "good": true, "q": "If I decide to go ahead, what are the next steps?", "s": 2127, "trick": "Make the next step feel small", "url": "https://fathom.video/calls/263406837"}, {"a": "Luke said usually about seven days, with day one spent checking the existing campaign, then payment link, onboarding, and a team meeting, with Loom videos for updates.", "better": "We move fast. After you pay and fill in the form, we meet the team, and the first ads are usually ready in about a week. On day one we also look at your current ads and find out why spend dropped. Shall I send the payment link and form after this call?", "call": "David Marcyniuk", "good": true, "q": "What are the next steps, and how long will it take to get the creatives done?", "s": 1094, "trick": "Offer a quick win on day one", "url": "https://fathom.video/calls/231509507"}, {"a": "Luke said it is fine, they can coordinate with the other team, and they only need access to the website and Google Analytics, and will set up Search Console if missing.", "better": "That is very common, and it works well. We just need access to your website and Google Analytics, and we are happy to meet the other team so nobody steps on toes. If anything is missing, like Search Console, we set it up. Who should I ask for access?", "call": "Annie", "good": true, "q": "Our paid search is already run by another team. What access do you need and how does this work?", "s": 1127, "trick": "Make the start feel easy", "url": "https://fathom.video/calls/301373694"}, {"a": "Luke said that with live accounts the ads could go live in about three days after checking everything, and a fresh brand takes seven to 10 days.", "better": "Since your accounts are already live, we could be in them the same day and have fixes running in about 3 days. A brand new account takes 7 to 10 days. In the first 48 hours you also get a workbook with the plan. Shall we book the kickoff call today?", "call": "Larry Pomerantz", "good": true, "q": "If you start now, how long until the ads are live?", "s": 1808, "trick": "Give a clear timeline", "url": "https://fathom.video/calls/276740502"}, {"a": "Luke said they send a Stripe payment link, a HelloSign contract and an onboarding form, the manager emails the same day, and they are usually live in about seven days.", "better": "Easy. You get a payment link, a short contract that says you own your account, and a quick form. Same day our manager books a call and we are usually live in about seven days. For you that means set up before Christmas. Does that timing work?", "call": "Rehan Amir", "good": true, "q": "If we agree, what does onboarding and launch look like and what do you need from me?", "s": 1783, "trick": "Walk the steps in order", "url": "https://fathom.video/calls/490898315"}, {"a": "Luke said no notice is needed, they send a payment link and onboarding form on a month to month agreement, and it takes about seven days to go live.", "better": "No notice needed. When you are ready, I send a payment link and a short form, and we are live in about seven days. Since you launch in April, we can start two months before so we have time to warm people up. Want me to map out dates for you?", "call": "Temisan", "good": true, "q": "When would you be ready to start, how much notice do you need?", "s": 1896, "trick": "Work backward from their date", "url": "https://fathom.video/calls/229608484"}, {"a": "Luke said he would send a follow up email that day and she can reply by email.", "better": "Simple. I will send you an email today with the lowest package and what it includes. When you are ready, reply and I will send a payment link, and we start with a planning call. No rush at all. Is email still the best way to reach you?", "call": "Kay Pollard", "good": true, "q": "If I want to move forward, what are the next steps?", "s": 1528, "trick": "Make the next step tiny", "url": "https://fathom.video/calls/241212547"}, {"a": "Luke passed it to Matthew, who said one week at most, often a couple of days, and for Google they add seasonal keywords to existing campaigns.", "better": "Good question since your plant seasons move fast. If you plan ahead, a few days is normal and one week is the most. Send us the idea early and we will have copy ready, so launch is just adding your photos. Does that fit your calendar?", "call": "Hailey Baird", "good": true, "q": "How quickly can you launch new creative, from us sending it to the ad going live?", "s": 743, "trick": "Tie answer to their calendar", "url": "https://fathom.video/calls/512674658"}, {"a": "Luke said they send a Stripe link for a recurring monthly payment he can cancel any time, then a contract, an onboarding form, and a call with Matthew.", "better": "Simple steps. You get one Stripe link for the monthly fee, a short contract to read, then a 15 minute form. After that Matthew calls you and we get into your account within a day or two. Which part would you like me to explain more?", "call": "Marius Negru", "good": true, "q": "How do I pay, in advance or part now and part later?", "s": 960, "trick": "Walk through the steps clearly", "url": "https://fathom.video/calls/525995385"}, {"a": "Luke said it is a large account so setup depends, then said they can do it much quicker than four weeks, in seven to 10 days.", "better": "Great question. Once you say yes, we set up the ad groups, keywords and tracking, and that usually takes 7 to 10 days. You will know the date on day one so there are no surprises. Would you like me to put that date in the contract?", "call": "Shabnam Akrami", "good": true, "q": "After I pay the 1,500, how long until the account is set up?", "s": 946, "trick": "Give a clear date", "url": "https://fathom.video/calls/282988891"}, {"a": "Luke said the usual range is seven to ten days but for Dean it could be a couple of days since he has active accounts.", "better": "Usually 7 to 10 days. With your active accounts and festival dates, we can often go live in a couple of days. We spend a day or two studying what you did and your competitors so we do not make mistakes. Which event is next for you?", "call": "Dean Strober", "good": true, "q": "What is the onboarding time from saying yes to the first ad running?", "s": 849, "trick": "Match speed to their deadline", "url": "https://fathom.video/calls/335111266"}, {"a": "Luke explained they send an onboarding form, a manager reaches out the next day, the team meets with the client, studies competitors, builds a plan, then runs ads with check ins.", "better": "Great question. You fill in a short form, and tomorrow our manager Matthew sets a team call. Your competitor list helps a lot, and so do your best videos. Then we show you the plan before any money is spent. Want the form today?", "call": "Isak Peterson", "good": true, "q": "What inputs would help from our side when building the campaign?", "s": 1878, "trick": "Walk through the steps simply", "url": "https://fathom.video/calls/329401485"}, {"a": "Brian said they would help set up the ad account and connect it to her page and Instagram, and Luke said they connect through a partner account so she owns everything.", "better": "You never need to share your password. We help you make an ad account, then connect it to your page and Instagram with safe access. You own everything, always. We will walk through it together on a call. Does that sound easy?", "call": "Erin Rosenstock", "good": true, "q": "Would you promote under my existing Facebook account, and do you need my password?", "s": 1549, "trick": "Remove the fear, then guide", "url": "https://fathom.video/calls/262474173"}, {"a": "Luke said they audit everything, run competitor analysis, build ad groups and new campaigns and handle conversion tracking until leads come in.", "better": "Yes, every account starts with a deep look at what is going wrong. We check tracking, search terms, competitors and your campaign setup, then show you what we found. That is the first thing we do, not an extra.", "call": "Safa", "good": true, "q": "Do you do audits of our account to see what is going wrong?", "s": 223, "trick": "Audit as first step", "url": "https://fathom.video/calls/259170120"}, {"a": "Luke said they usually require three months but for Justin he would watch weeks one and two and not hold him to the budget being too small, then said he would send a payment link and contract.", "better": "Happy to. It would show the monthly fee, the ad budget you choose, what we do each month, and a check in at the end of month one. I will send it today. Would you rather start in December or wait until January?", "call": "Justin Mitchell", "good": true, "q": "What would a three month proposal look like on paper?", "s": 3606, "trick": "Make the next step easy", "url": "https://fathom.video/calls/464049834"}, {"a": "Luke said they start the same or next day after payment and form, then Matthew Overbay does an onboarding call, then about seven to 10 days to set up and light testing in month one. He said the March goal was very tight but doable.", "better": "We can start the day after you pay and send the form. Matthew will call, and setup takes about a week. March is tight, so I'll start the Shopify move first. I'll give you a week by week plan. Sound good?", "call": "Dorian Fleuri", "good": true, "q": "If we confirm this week, when can you start?", "s": 2548, "trick": "Give a clear date plan", "url": "https://fathom.video/calls/564365833"}, {"a": "Brian explained the $1,500 Google plan: review the Performance Max campaign, maybe add search, restructure, and then do daily maintenance.", "better": "First we look under the hood and find out why spend dropped from $3,000 to $566. Then we fix it, test a search campaign alongside it, and watch it every day. Does that sound like what you need?", "call": "Nathan Riley", "good": true, "q": "How would you help us with the Google account?", "s": 495, "trick": "Name their problem first", "url": "https://fathom.video/calls/266725821"}, {"a": "Luke said about a week to get started and plan, and seven to 10 days until ads are ready.", "better": "We are fast. The first week is planning and set up, and in about 7 to 10 days your ads are live. We can start even while you finish the other agency contract. Want me to send the start plan?", "call": "Amy N Neighbors", "good": true, "q": "How long does the rollout take?", "s": 2160, "trick": "Give a clear time frame", "url": "https://fathom.video/calls/485151651"}, {"a": "Luke said they would be in the account the same day, check it daily, and work in phases, first turning off what is wrong, then building bigger strategy, all in the first week.", "better": "We move fast. Day one we are in the account, and in week one we stop what is wasting money and fix the basics. The bigger plan comes right after. Would you like to start this week?", "call": "Joyce", "good": true, "q": "How long is the turnaround time for the plan?", "s": 858, "trick": "Show day one action", "url": "https://fathom.video/calls/470472685"}, {"a": "Megan said about six to seven days after signing, within a week, everything is live.", "better": "About a week after you sign and fill out the onboarding form. We use that week to set up your tracking and build your first ads right. Want me to walk you through the steps?", "call": "Kristina Shumi", "good": true, "q": "How long does it take to get this going?", "s": 1335, "trick": "Clear timeline, clear steps", "url": "https://fathom.video/calls/284134646"}, {"a": "Luke said he could send it by probably tomorrow if they were really ready to go.", "better": "You will have it tomorrow. I will include the plan, the price and how we start. If you reply, we can start within a few days. Is there anything else you would like in it?", "call": "Maria Costa", "good": true, "q": "How long will you take to send the proposal?", "s": 1347, "trick": "Specific next step and date", "url": "https://fathom.video/calls/253101615"}, {"a": "Luke said they could start new campaigns or dig into why the old ones stopped working, and that the team would specialize in that, but he said he did not have deep knowledge of it himself.", "better": "That makes sense, those old campaigns have been through a lot of changes. Our team would first look at 6 to 9 months of your data to see what worked in March, then decide together whether to rebuild from scratch. We would change one thing at a time so we always know what helped. Would it help if you met the person who would run it so they can walk you through it?", "call": "Mohammed Sharifi", "good": false, "q": "How would your team approach the Google Ads, since our old campaigns have been changed so much?", "s": 1025, "trick": "Show a calm, careful plan", "url": "https://fathom.video/calls/323376725"}, {"a": "Luke said it depends, shared his screen to show paid ads, maps and organic results, and said they build a detailed plan with negative keywords and work the account daily.", "better": "Good question, Frank. We build the whole account for you. That means research on what your buyers search, writing the ads, setting up tracking, and checking it every day. You get a short video each week showing what we did and what came in. Would you like to see what that plan could look like for your business?", "call": "Frank Modarelli", "good": false, "q": "On Google Ads, what does your team actually come in and do?", "s": 1886, "trick": "Answer plainly, then offer a peek", "url": "https://fathom.video/calls/264528192"}, {"a": "Luke described reviewing the account, competitor and keyword reports, building several campaign types, daily negative keyword work, and moving a return from 0.8 toward 3x or 4x.", "better": "First we look at your Google account and see what is wasting money. Then we build better campaigns, check search terms every day, and shift budget to what sells. Think of it as a full time expert for a fraction of one salary. Want me to show you one example of what we changed for a client?", "call": "Stephanie Webb", "good": false, "q": "What are you actually doing with the 1500 to make us money?", "s": 1435, "trick": "Compare to hiring one employee", "url": "https://fathom.video/calls/227326702"}, {"a": "Luke said it depends on the business goals and results, and most clients keep it running, or shift to paid ads if SEO slows down, so there is no one answer.", "better": "Good question. After the first few months we keep adding content and links, and the work moves from building to growing. If SEO starts to slow, I will say so and we can shift some budget to ads. So you are never paying for something that is not working. Does that feel fair?", "call": "Stefan Gutowski", "good": false, "q": "Once it is set up, does maintaining it look different?", "s": 639, "trick": "Promise honesty about what is working", "url": "https://fathom.video/calls/293071198"}, {"a": "Luke said it is up to her to choose the company she wants, and that he would send a recap by email.", "better": "I am glad it feels right. Here is what happens next: I send you a short summary today, and you can share it with your trustees. If you say yes, Matthew, our general manager, will set up a team call within a few days. Does a week from now work for you to decide?", "call": "Christy Acton", "good": false, "q": "I like the sound of it, so where do we go next?", "s": 1960, "trick": "Give clear next steps", "url": "https://fathom.video/calls/358280745"}, {"a": "Luke said they do not do anything until someone pays because it takes a lot of work, but everything is shown before going live.", "better": "Good question. Because the planning takes days of real work, we start after payment, but you approve every ad and video before anything goes live. With month to month terms and a 10 day exit, the risk is small. Would you like to see a past client example now?", "call": "Mike Worden", "good": false, "q": "Do you show us creatives before we pay?", "s": 1738, "trick": "Show an example instead", "url": "https://fathom.video/calls/831260309"}, {"a": "Luke said it depends on budget and there is no straight answer, then moved to showing his pricing page.", "better": "Yes, that is how it starts. We look at your site and your competitors, then send a plain plan of the keywords and pages we would go after in the first three months. Then you pick the level that fits your budget. Want me to put that together for you?", "call": "Joseph Gaspero", "good": false, "q": "Starting from zero, what do you typically do, review our site and make a proposal?", "s": 1160, "trick": "Say step one, step two", "url": "https://fathom.video/calls/247180673"}, {"a": "Luke said first they set a budget range to know the options and goals.", "better": "Simple. First we agree on a rough budget and your goals. Then I send a clear plan with price, and you meet our manager to go over it. No pressure, and your wife is welcome on any call. Want me to send that plan after we talk?", "call": "Matt Holdridge", "good": false, "q": "How do you normally handle the pitch and the sale, do you write a proposal?", "s": 1485, "trick": "Lay out the path ahead", "url": "https://fathom.video/calls/469763535"}], "outbound": [{"a": "Luke said citations are Google Maps listings and would not be a priority for them, and that landing pages, manual backlinks and improving existing content matter most.", "better": "Good catch. Citations are listings of your business on maps and directories, and they matter most for local shops. For a global group like yours they are not the main thing. Your biggest wins would come from new pages, quality backlinks and improving pages you already have. Want me to show what the first month would look like for you?", "call": "Chris Savor", "good": true, "q": "What does five citation submissions mean?", "s": 418, "trick": "Translate jargon, then redirect", "url": "https://fathom.video/calls/251114242"}, {"a": "Luke said they do not reuse lists, they are cautious with every list and rebuild it custom for each client, spending hours checking every name.", "better": "Great thing to ask. We never reuse another client's list, because the list needs to match your exact buyer and the emails need to be fresh and checked. That keeps you safe and keeps your emails out of spam. Want me to explain how we check a list?", "call": "Andrew Silagy", "good": true, "q": "Can you reuse lead lists you built for other campaigns, like banks or healthcare, and what about the ethics?", "s": 1638, "trick": "Tie answer to their protection", "url": "https://fathom.video/calls/341420869"}, {"a": "Luke said they use those and more, including Ahrefs and SEMrush, to see what competitors are doing.", "better": "Yes, we use those and a few others like Ahrefs and SEMrush. We look at what your competitors say in their ads, then build better versions and sometimes run ads against their names. Would you like us to look at your top three competitors first?", "call": "Brian Rose", "good": true, "q": "Are you familiar with tools like SpyFu or Rival Flow for competitor ads?", "s": 1925, "trick": "Confirm, then show the use", "url": "https://fathom.video/calls/288749754"}, {"a": "Luke said they use lots of tools including Ahrefs and SEMrush, plus custom APIs.", "better": "Yes, we use Ahrefs and SEMrush, and a few custom tools too. The tools matter less than what we do with them, which is finding the buyer type searches that your best customers actually type. Want me to show you how that looks for your topic?", "call": "Mcbride", "good": true, "q": "Do you use specific programs like SEMrush for keywords?", "s": 376, "trick": "Tools matter less than the plan", "url": "https://fathom.video/calls/241078094"}, {"a": "Luke said clients can suggest keywords but it is nearly impossible to pick the right ones without expert tools, and that they use broad match with negatives.", "better": "Yes, we want the client's list, it tells us what he cares about. Then we test it against real search data and add what he may have missed. Nothing gets thrown out without a reason. Can you send the list so I can check it?", "call": "Maria Costa", "good": true, "q": "Will you work with the keywords the client already chose?", "s": 485, "trick": "Respect their input", "url": "https://fathom.video/calls/253101615"}, {"a": "Luke explained they reach out to bloggers in the niche and offer to write an article for them, which helps their traffic and sends traffic back.", "better": "Good question. We find real sites your customers already read, and offer them a helpful article for free. They get fresh content, and you get a trusted link. It is slow, careful work, not a link blast.", "call": "Mcbride", "good": true, "q": "When you say manual backlinks, what do you mean?", "s": 404, "trick": "Simple example, not jargon", "url": "https://fathom.video/calls/241078094"}, {"a": "She said 5,000 plus emails a month, with the focus on lead quality and follow ups.", "better": "On this plan we send 5,000 plus emails a month, with follow ups to the best fits. We care more about the right people than the biggest number. What kind of customer would you most want to reach?", "call": "Ricardo Amaya", "good": true, "q": "How many leads or emails do you send per month on that plan?", "s": 767, "trick": "Number plus quality point", "url": "https://fathom.video/calls/269795639"}, {"a": "Luke said they include everything, including leads, verification, customization and communication, starting at $4,500 per business.", "better": "We handle the whole list, finding, checking and cleaning it, so you do not need to lift a finger. We would just ask you about your ideal customer. Would you like me to show how we build one?", "call": "Gio", "good": true, "q": "Do you provide the lead list, or do I need to?", "s": 717, "trick": "Take work off their plate", "url": "https://fathom.video/calls/267686901"}, {"a": "Luke said there is a base of four to six articles a month on the site, that guest post outreach has no fixed number, and that they usually double the minimums.", "better": "Fair question, you should know what you are paying for. Month one, you would get four to six articles on your own site as a floor. Guest posts I cannot promise by number, because a good one can bring thousands of visits and others never land. What I can promise is steady outreach every week and a clear report on what came back. Does that feel fair to you?", "call": "Chris Savor", "good": false, "q": "In month one, what would the mix be between guest posts and work on our own site?", "s": 642, "trick": "Firm floor, honest unknown", "url": "https://fathom.video/calls/251114242"}, {"a": "Luke said he had not dug in yet, that it is a niche, and that backlinks may not be the main tactic. He said they might focus on keyword clusters instead.", "better": "You are right, that is a real problem in your space, because many bloggers see you as competition. So I would not lean on that. I would start with the keywords and pages first, and look for partners who are not rivals, like podcasts and public health groups. I can map that out for you in the plan.", "call": "Mcbride", "good": false, "q": "Many bloggers in our field sell their own programs, so how would that work?", "s": 455, "trick": "Agree with the worry first", "url": "https://fathom.video/calls/241078094"}, {"a": "She said they use several domains so emails do not get burned and go to spam, but did not know the exact number and offered to ask the cold email team.", "better": "Great question, it shows you know cold email. We spread sending over several warmed up domains and inboxes so nothing lands in spam, and I will get you the exact number from our team today. Would a short call with the person who builds them help?", "call": "Ricardo Amaya", "good": false, "q": "How many domains and inboxes do you build, and how many email steps in a sequence?", "s": 1168, "trick": "Offer an expert, not a guess", "url": "https://fathom.video/calls/269795639"}], "partner": [{"a": "He said it would not interfere but recommended keeping everything in house, and mentioned a Google plus Meta package at $2,500 and a lighter SEO option.", "better": "It would not break anything, so you are free to choose. The one thing I would watch is website changes, because Meta and SEO share your site, so we would just need to stay in touch with your SEO person. If it helps, I can price a light SEO add on so everything sits in one place. Want me to do that?", "call": "Leonard Emini", "good": true, "q": "If we do SEO with someone else, would that interfere with your work?", "s": 1013, "trick": "Say yes first, then advise", "url": "https://fathom.video/calls/271080025"}, {"a": "Luke said they do not, they charge a flat retainer starting at $1,800 a month, and there has to be real money for him to get excited.", "better": "We do not work on pay per lead, because I cannot control what happens after the lead. I like to see numbers first, so bring me a signed client and let us run the math together. Would that be a good first step?", "call": "Hendry", "good": true, "q": "Have you ever partnered with someone for a percentage per lead?", "s": 561, "trick": "Kind no, clear next step", "url": "https://fathom.video/calls/505799799"}, {"a": "Luke offered $1,000 for every client Hendry brought for Google Ads and SEO, and said he would run the sales call himself.", "better": "Yes, I would pay a referral fee, say $1,000 for every client who signs. You bring the introduction and I run the call. Send me your first real lead and we will start from there. Sound fair?", "call": "Hendry", "good": true, "q": "For Google Ads is there an extra fee, and would you pay me for clients I close?", "s": 793, "trick": "Offer a simple clear deal", "url": "https://fathom.video/calls/505799799"}, {"a": "Luke said they could either re up with Red Wing and increase the heat, or turn their ads off and let his team manage them, with a separate Meta campaign possible.", "better": "Not necessarily. We could run local Meta and a fresh Google campaign for each store beside what Red Wing does. We would just track ours separately so you can see what works. Would that give you the local control you want?", "call": "Jarrad Beard", "good": false, "q": "Would we have to cut Red Wing's ads out to work with you?", "s": 1377, "trick": "Offer the least disruptive path", "url": "https://fathom.video/calls/241168945"}], "perf": [{"a": "Luke said they do not do revenue share, but clients can pause and start, and he would not recommend only one campaign because awareness between campaigns matters.", "better": "I get why that is appealing, you want to see proof before you commit. We keep one flat fee instead of a bonus, so we only care about your results. We can start with the winter league, and you can pause if it is not working. Would a three month start feel okay to you?", "call": "Mike Worden", "good": true, "q": "Could we do one campaign for a fixed fee plus a performance bonus?", "s": 950, "trick": "Explain why, offer a start", "url": "https://fathom.video/calls/831260309"}, {"a": "Luke said no, they are not a trial bunch and have over 40 clients.", "better": "No trial, and here is why. Good ad work takes a few weeks of real data, so a short trial wouldn't show you the truth. What I can do is a first month with a 10 day exit if it isn't right. That way you take a small risk. Would that feel safe?", "call": "After hours alcohol delivery prospect", "good": true, "q": "Do you guys use some trial, or how does it work?", "s": 466, "trick": "Give a reason then a safe option", "url": "https://fathom.video/calls/858246139"}, {"a": "Luke argued that accounts need daily management, that a one time fix would fall again, and said it is a pro and a con.", "better": "That is a fair ask, and I do not want you to take a big risk again. An audit alone can help, but Google changes fast, so I would be lying if I said one fix lasts forever. What if we start with a one month trial and you stop anytime if you do not see progress?", "call": "Safa", "good": false, "q": "Can you work in a way that gives us more guarantee, like an audit first before managing?", "s": 1270, "trick": "Agree, then offer small first step", "url": "https://fathom.video/calls/259170120"}, {"a": "Luke said no, they do not do free pre audits because it takes five to ten hours, and they only work with paying clients.", "better": "I hear you, you want to see our thinking before you commit. A full audit takes our team 5 to 10 hours, so we keep it for clients. What I can do is a short call where I look at your numbers live and show you two things I would fix. Would that help?", "call": "Joyce", "good": false, "q": "Can you look at our account first and tell us what you would do?", "s": 363, "trick": "Say no, then offer a small yes", "url": "https://fathom.video/calls/470472685"}, {"a": "Luke said he has done it when clients show conversions and ROAS on Meta, but tracking gets complicated, so the fee stays the same.", "better": "I like that you're thinking about shared risk. Pure results pay gets messy to track, so I keep a flat fee for the work. What I can do is a lower start while we test, then a clear plan once sales are coming in. Would that help with cash flow?", "call": "Dorian Fleuri", "good": false, "q": "Could we offset the payment and I pay more based on results?", "s": 1414, "trick": "Offer a middle path", "url": "https://fathom.video/calls/564365833"}], "price": [{"a": "Luke said cold email is $4,500 a month and covers leads, research, personalized emails, domains, infrastructure and replying to leads.", "better": "Good question, and I like that you want to plan for it. It is $4,500 a month, and that covers finding and checking every lead, writing each email by hand with some AI help, setting up the sending domains, and replying for you. The reason it costs more is that nothing is generic. I can send the price in writing so you can plan it with your team. Does that work?", "call": "Shayaan Abbas Houssen Aly", "good": true, "q": "What type of cost are we looking at and how does the process work?", "s": 873, "trick": "Price then what it covers", "url": "https://fathom.video/calls/253053797"}, {"a": "Luke said Google Ads is a flat $1,500 a month up to a $10K ad spend, then $2K up to $20K, Meta is $2K, and bundles run $3K and up.", "better": "Of course, money is tight right now and I get why you want this first. Google Ads is a flat $1,500 a month with no setup fee, and that covers tracking, campaigns and landing page fixes. Since you are spending about $3,000 a month already, the first goal is to get that spend working harder. Does that feel doable if we start there?", "call": "Marius Negru", "good": true, "q": "I need to know some costing because it is quite important for me at the moment.", "s": 392, "trick": "Acknowledge stress, then simple price", "url": "https://fathom.video/calls/525995385"}, {"a": "Luke said Google Ads alone is $1,500 a month for up to $15,000 ad spend, then offered $1,300 a month if Sam moved forward that same day.", "better": "Great question, and it is the right one to ask. For a brand new store, I would start with Google only, because those people are already searching to buy a sauna. That is $1,500 a month to manage it, and ad spend goes straight to Google. Does it feel okay to start with one channel and grow from there?", "call": "Sam Daoud", "good": true, "q": "What can you offer my website, and what is the price?", "s": 639, "trick": "Start small, grow with proof", "url": "https://fathom.video/calls/551904290"}, {"a": "Luke said SEO has four packages starting at 1500 a month and going up to 4500, and the difference is the volume and pressure put on it. He then walked through a client workbook.", "better": "Happy to. SEO packages run from 1500 to 4500 a month, and the main difference is how much work we put in each month. Results depend on how competitive your topic is, so I will not promise a number today. Can I ask what you would need to see in the first few months to feel good about it?", "call": "Mcbride", "good": true, "q": "Can you tell me about your pricing, your results, and what I should expect?", "s": 199, "trick": "Give price then ask their goal", "url": "https://fathom.video/calls/241078094"}, {"a": "Luke said Facebook ads start at 1,500 for up to 10k ad spend plus 500 for design (about 2,000), Google plus Facebook is 3k, large spenders pay about 10 percent of ad spend.", "better": "Here is the simple version. For you, Facebook is $1,500 for up to $10,000 of ad spend, plus $500 for design and video, so about $2,000 a month. If we add Google later, it moves to $3,000. No contract, so you only stay if it is working. Which of those feels closest to what you need?", "call": "Mark", "good": true, "q": "What is your price point?", "s": 2615, "trick": "Plain number, then a question", "url": "https://fathom.video/calls/226492580"}, {"a": "Luke said cold email starts at 4,500 a month and includes leads, copywriter and tech, and the first month is 50 percent off at 2,250 because it is mostly setup and warming.", "better": "For what you need, it is 4,500 a month, and that covers everything: the leads, the tools, the copywriter and the tech person. Month one is half price at 2,250 because it is mostly setup and warming, and we do not send at full speed until later. Does that fit what you had in mind?", "call": "Doug Fiore", "good": true, "q": "What does cold outreach cost per month?", "s": 1431, "trick": "Price, what is inside, then a check", "url": "https://fathom.video/calls/242167771"}, {"a": "Luke said websites are custom, but Google and Meta ads are a set price of 2,400 for both or 1,500 each, with a three month commitment.", "better": "Good question. Websites are custom because every one is different, and the ads are simple set prices. Since you run one campaign, I would first ask what you spend now and what you want to grow to. Then I can tell you honestly what fits. How much do you spend on Google right now?", "call": "Leah Vogt", "good": true, "q": "Do you have pricing for everything, or is it all custom?", "s": 517, "trick": "Ask about budget before quoting", "url": "https://fathom.video/calls/347069031"}, {"a": "Brian showed Google Ads only at 1,500 and Google Ads plus SEO at 3,500, and Luke offered to bring the package to 2,500 for a nonprofit.", "better": "Happy to lay it out simply. Google Ads alone is 1,500 a month, and both Ads and SEO is 3,500. Since you are a nonprofit and I love what you do, I can do both for 2,500. If money gets tight I would start with ads only, because it is the quickest win. Which one fits you better?", "call": "Chloe Puig", "good": true, "q": "What would the packages look like if we added SEO on top of Google Ads?", "s": 1219, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/264491733"}, {"a": "Luke said start with Precision to learn what works, then scale fast, and that the only difference between the plans is the number of emails and lead lists.", "better": "I would start on Precision, because the first month is about finding what works. Hyperscale is the same system with more emails and bigger lists, so we can move you up fast once we see good replies. You are not locked in to either one. Does starting there feel right to you?", "call": "Andrew Milstead", "good": true, "q": "Would you start us on the Precision plan and then move to Hyperscale?", "s": 1282, "trick": "Recommend one clear path", "url": "https://fathom.video/calls/229583830"}, {"a": "Luke said they charge monthly, $2,400 a month per website, with plans, workbooks, strategy, blog content and backlinks included, and noted cheap SEO runs about $500 and good SEO $1,500 to $6,000.", "better": "Fair to ask. The plan is part of the work, not a separate bill. It is $2,400 a month per site, and that covers the plan, the content, the links and the reporting. Cheaper options exist, but they usually do very little. Does that range feel in line with what you had in mind?", "call": "Annie", "good": true, "q": "Do you need a month to assess, or can you lay out a plan in a few hours, and what do you charge?", "s": 854, "trick": "Anchor price with what is included", "url": "https://fathom.video/calls/301373694"}, {"a": "Brian said Meta management is $1,800 a month on top of ad spend, month to month with no strict contract, and the in house designer is included.", "better": "For Meta it is $1,800 a month, and your ad spend goes straight to Facebook. That fee covers daily checks, the designer, new creative every week, and tracking setup. There is no long contract. Since your first goal is the retreat, does it feel like the right size for you?", "call": "Chris Bilyk", "good": true, "q": "What is your rate and what does it include?", "s": 1932, "trick": "Price with what it includes", "url": "https://fathom.video/calls/271182973"}, {"a": "Luke said Facebook management is 1500 for up to 10k ad spend plus 500 for creatives, which he waived for her, and that ad spend is on top, so a 2000 pound total budget is tight.", "better": "Our Facebook management starts at 1500 a month, and I will include the 500 creative fee for you. Your ad spend goes on top of that. With your budget, I want to be honest that we would start small and prove it works first. Does that range feel workable for the relaunch?", "call": "Temisan", "good": true, "q": "What are your fees?", "s": 1075, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/229608484"}, {"a": "Luke said Precision Growth is 4,500 a month, around 5,000 emails a month (3,000 to 8,000), with about 50 mailboxes, and Scale is higher with about 200 mailboxes.", "better": "Cold email starts at 4,500 a month. That covers finding and checking the leads, writing personal emails, and managing the mailboxes so you stay out of spam. We focus on quality, not volume. Do you want me to send a one page breakdown to share with your partner?", "call": "Joseph Gissy", "good": true, "q": "What is the pricing for cold outreach?", "s": 1294, "trick": "Price plus what it covers", "url": "https://fathom.video/calls/230308235"}, {"a": "Luke said yes for her kind of target, but a hard niche that needs custom paid lead sources could cost extra.", "better": "For you, yes, the lead sources are included in the 4500. The only time we would talk about extra cost is a very hard niche where leads are costly to find, and that is not your case. I will always tell you before any extra cost, never after. Does that feel fair?", "call": "Andrew Milstead", "good": true, "q": "Is all of that included in the price?", "s": 1108, "trick": "Promise no surprise costs", "url": "https://fathom.video/calls/229583830"}, {"a": "Luke said it switches to the percentage, usually 7 to 8 percent rather than the full 10, and it is negotiated since some clients spend a quarter of a million.", "better": "Good thing to ask. It switches, it is not added on top. At 30K you would be around 7 to 8 percent, so roughly $2,100 to $2,400, and we do not get paid unless the work pays off. I will email the full table so you can plan your numbers. Does that sound fair?", "call": "Rehan Amir", "good": true, "q": "If I spend 30K, is it 10 percent on top of the $1,500 or does it switch to the percentage?", "s": 865, "trick": "Do the math out loud", "url": "https://fathom.video/calls/490898315"}, {"a": "Luke said it is $4,500 a month, with about $1,000 of that going to personalization, and 50 percent off the first month, so $2,250.", "better": "Good to ask. It is $4,500 a month, and about $1,000 of that is just the personalization work. Since the first twelve days are setup, month one is half price at $2,250. By month two you will know if it is working. Does that feel like a fair way to test it?", "call": "Tony Small", "good": true, "q": "How much would cold outreach be over one month?", "s": 931, "trick": "Reason for the discount", "url": "https://fathom.video/calls/246099180"}, {"a": "Luke said most projects start around 25K, branding only is about 8K to 10K, rebuilding the whole platform maybe 20K, and a workshop is 1500, and that cheaper people can be hired too.", "better": "Yes, there are good options at every level. A workshop is 1500 and gives you a plan and a quote. Branding only is about 8K to 10K, and a full rebuild is around 20K. Start with the workshop if you want to test us first. Want me to send you what it covers?", "call": "Pete Patrino", "good": true, "q": "Is it possible to do branding for not too much money?", "s": 1812, "trick": "Lay out small to big options", "url": "https://fathom.video/calls/849585251"}, {"a": "Brian said the proposal was priced for weekly testing, that this project needs more setup than ongoing work, and that he would send an updated proposal after talking with Luke.", "better": "That makes sense, and you are right to ask. That fee was built for weekly testing, and your project needs a strong setup with light check ins after. So we will change it to match what you really need. Does a small monthly amount for tweaks sound fair?", "call": "Carolina", "good": true, "q": "Why should I pay 3,000 a month if the drip campaign is set up once for the year?", "s": 1099, "trick": "Agree, then reshape the offer", "url": "https://fathom.video/calls/274394195"}, {"a": "Luke said it looks simple but they want it to work, and that their ideal clients are already profitable, so starting out is difficult for them.", "better": "Fair to ask. Our websites start at $10,000 because we build them for conversions, not just looks. For a simple one page site, a freelancer may serve you better and cost far less. I would rather tell you that than sell you something that does not fit.", "call": "Yesset Karayev", "good": true, "q": "Would even a simple website cost about $10,000?", "s": 1763, "trick": "Put the client's interest first", "url": "https://fathom.video/calls/455546501"}, {"a": "Luke said it is $1,500 a month for accounts under $15,000 ad spend, doing everything including Pmax, search and tracking, then 10 percent above that with tiers.", "better": "Simple. It is $1,500 a month when you spend up to $15,000, and that covers campaigns, tracking and the team. Above that we move to a percentage that gets smaller as spend grows. Based on what you spend on Meta, where do you think Google would land?", "call": "Rehan Amir", "good": true, "q": "How does your monthly pricing work for Google Ads?", "s": 779, "trick": "Price plus what is included", "url": "https://fathom.video/calls/490898315"}, {"a": "Luke said it is separate, but he can do a combo. Google Ads management is about 1500 a month on average, and SEO plus Google Ads management would be around 2000 a month.", "better": "It is separate, but they work well together, so I bundle them. Google Ads alone is usually around 1500 a month, and a base SEO plus ads management combo is about 2000 a month. Would you like me to put both options on one page so you can compare?", "call": "Mcbride", "good": true, "q": "Is Google Ads management included with the SEO price?", "s": 772, "trick": "Bundle then offer a compare page", "url": "https://fathom.video/calls/241078094"}, {"a": "Luke said management and creative are different jobs, the in house designer makes new ads, and clients with their own designers or assets can skip it.", "better": "Fair question. The 1500 covers running the campaigns. The 500 pays our designer to make fresh ads, which takes real time. If you already have good images and video, we can skip it. Which would you rather do, send us assets or have us make them?", "call": "Stephanie Webb", "good": true, "q": "Why is there a separate 500 a month for creative design?", "s": 1853, "trick": "Offer a choice, not a push", "url": "https://fathom.video/calls/227326702"}, {"a": "Luke said $1,500 a month if ad spend is under $15k, then about 10% above that, which is negotiable, and that Brian's $3,000 to $5,000 spend would stay under that.", "better": "Google Ads management is $1,500 a month while your ad spend stays under $15,000, and you are at $3,000 to $5,000, so that is your number. Bigger accounts move to a percentage, but you are not close to that. Does that fit what you had in mind?", "call": "Brian Rose", "good": true, "q": "What is the cost or packages for Google Ads management?", "s": 1200, "trick": "State one clear price", "url": "https://fathom.video/calls/288749754"}, {"a": "Luke said Google Ads is $1,500, Facebook is $1,800, and a combined plan is $2,500, which he offered to bring down for him.", "better": "Good thing to figure out before you commit. Google Ads is $1,500 and Meta is $1,800, and both together is $2,500. Since your budget is under $3,000 all in, I would suggest one channel first. Want me to show you what each one would look like?", "call": "Christian Hoeffel", "good": true, "q": "What would it cost for a marketing pro to manage my budget?", "s": 977, "trick": "Lay out options then narrow", "url": "https://fathom.video/calls/317379106"}, {"a": "Luke said there is nothing extra and no upsell, as everything including the design, Google tools and SEO software is included.", "better": "Nothing extra, Chloe. The package covers our time, our software and the design work. The only other money is your ad spend, which goes straight to Google. I will show you the full list in writing so there are no surprises. Does that help?", "call": "Chloe Puig", "good": true, "q": "Are there any other tools or costs we would have to pay for besides the package?", "s": 1962, "trick": "Say what is and is not included", "url": "https://fathom.video/calls/264491733"}, {"a": "Luke said the $500 is flat and covers video and image edits done by an in house designer.", "better": "It is flat at $500 a month, and you will not get a surprise bill. Our designer builds and edits the ads, and we often run many versions at once. You send us your photos and videos and we handle the rest. Is that what you were hoping for?", "call": "Tony Small", "good": true, "q": "Is the creative cost a flat fee or does it grow if I need many ads?", "s": 1540, "trick": "Remove the surprise fear", "url": "https://fathom.video/calls/246099180"}, {"a": "Luke gave Google at $1,500, Meta at $1,800, SEO and AI search at $2,500, Google and Meta at $2,800, Google and SEO at $3,400 and Rocket Fuel at $5,000, with 10 percent above $15,000 spend.", "better": "Happy to. Google is $1,500 and Meta is $1,800 a month, up to $15,000 in spend. Both together are $2,800, and the full package is $5,000. Based on what you told me, I would start with Meta and Google. Does that match what you had in mind?", "call": "Ivona", "good": true, "q": "What are your prices and what do you offer?", "s": 504, "trick": "Recommend one clear fit", "url": "https://fathom.video/calls/481051622"}, {"a": "Luke said Meta is $1,800 flat up to $15,000 spend, then a percentage that drops as spend rises, such as 10, 8 or 6, and it includes creative, strategy and daily upkeep.", "better": "Meta is $1,800 a month up to $15,000 in spend. Above that the percentage starts near 10 and steps down as you grow. Creative, strategy and daily work are all included, so there are no surprise add ons. Want me to send the exact steps?", "call": "Rehan Amir", "good": true, "q": "What is the percentage model for Meta?", "s": 1211, "trick": "Anchor on what is included", "url": "https://fathom.video/calls/490898315"}, {"a": "Luke said Google management is $1,500 a month, Facebook is $1,800, and both together are $2,500, with a three month commitment paid monthly.", "better": "I can tell you straight. Google is $1,500, Meta is $1,800, and both are $2,500 a month, so it is well under what you pay now. You get a real person watching it every day. What is the main thing you need to see in the first 30 days?", "call": "Eric D Shepard", "good": true, "q": "What does the management fee cost, and could it be a fraction of what we pay now?", "s": 1037, "trick": "Plain price, then ask value", "url": "https://fathom.video/calls/458078657"}, {"a": "She said cold email starts at $4,500, SEO at $2,400, and both together are $5,500 a month.", "better": "Cold email starts at $4,500 a month, SEO is $2,400, and doing both is $5,500, so the bundle saves you money. That includes the leads, the writing, the sending and weekly reports. Which of the two matters more to you right now?", "call": "Ricardo Amaya", "good": true, "q": "How does pricing work?", "s": 742, "trick": "Price then what is included", "url": "https://fathom.video/calls/269795639"}, {"a": "He said it is monthly at $1,800 on top of about $1,000 ad spend, month to month with no contract, no profit share and no hidden fees.", "better": "Good question. It is monthly, $1,800 for management, and the ad spend goes straight to Meta on top of that. There is no contract and no hidden fees, so you can stop any month. Does that fit how you were picturing it?", "call": "Leonard Emini", "good": true, "q": "Is the management fee a monthly cost or a one time cost?", "s": 776, "trick": "Plain numbers, no surprises", "url": "https://fathom.video/calls/271080025"}, {"a": "Luke shared his screen and said the Paid Ads Vault, Google and Meta together, is $2,500 a month, with custom tracking and budget moved between platforms.", "better": "Our plan for Google and Meta together is $2,500 a month. That covers strategy, creative and managing both, plus tracking so we see what each dollar does. Ad spend is separate. Does that fit what you had in mind?", "call": "Dean Strober", "good": true, "q": "What is the pricing structure?", "s": 663, "trick": "State price, then what it covers", "url": "https://fathom.video/calls/335111266"}, {"a": "Luke said there is no setup fee, it is $1,500 a month to manage Google Ads with no year long contract but a three month commitment paid monthly.", "better": "Thanks for being so open about your budget. There is no setup fee. It is $1,500 a month for Google Ads, so about $1,500 plus your ad spend fits your range. We start small and learn fast. Does that work for you?", "call": "Razi Hecker", "good": true, "q": "What would you charge for setup and management? Our other consultant said 3,000 setup and 1,000 a month.", "s": 1342, "trick": "Match their stated budget", "url": "https://fathom.video/calls/507313039"}, {"a": "Luke said $1,500 flat for one business under a $20K ad spend, covering daily management, setup, conversion tracking and landing page fixes.", "better": "It is $1,500 a month for Google Ads, no setup fee. That includes daily management, tracking and small landing page fixes. For a business your size it is a fair middle price. Does that fit what you had in mind?", "call": "Darren Lebel", "good": true, "q": "What are we looking at from a monthly retainer standpoint?", "s": 641, "trick": "Simple number, then check fit", "url": "https://fathom.video/calls/504983103"}, {"a": "Luke said there is nothing else, only the fee: $1,500 for Google or $2,000 for Meta, and you just need good ads, leads and sales.", "better": "That is all of it. $2,000 a month for Meta covers the campaigns, ads, tracking and daily care, with no setup fee and no hidden extras. Your ad spend goes straight to Meta. Does that fit what you had in mind?", "call": "Michelle Johns", "good": true, "q": "What is your price, other than the $2,000 a month?", "s": 1671, "trick": "Make the price simple and clear", "url": "https://fathom.video/calls/537594627"}, {"a": "Luke said they take no cut on anything. The ad spend goes to the client and the 5,500 a month package covers influencer, SEO, Google and Meta.", "better": "No cut at all. You pay us one flat fee, 5,500 a month for everything, and your ad money goes straight to the ad platforms. If we find an influencer worth paying, I will tell you the cost and you decide.", "call": "Lasse Jensen", "good": true, "q": "Do you take any cut on top of ad spend?", "s": 1168, "trick": "Flat fee, nothing hidden", "url": "https://fathom.video/calls/240196889"}, {"a": "Luke said it is a flat 1,500 dollars a month, including analysis, plans, keywords, daily management, negatives, search terms, conversion tracking and optimization.", "better": "Yes, 1,500 dollars flat per month, in US dollars. That covers the plan, the setup, daily care of the account and tracking, with ad spend paid to Google on top. Does that fit what you expected?", "call": "Maria Costa", "good": true, "q": "Is it 1,500 dollars a month, and what does that cover?", "s": 448, "trick": "Clear price, clear inclusions", "url": "https://fathom.video/calls/253101615"}, {"a": "Luke said it covers everything, the whole team, design, video edits, and page changes.", "better": "No hidden costs. That price covers the team, design, video edits and changes to your pages. Your ad spend is separate, and that goes straight to Google. Anything else you want me to explain?", "call": "Joyce", "good": true, "q": "Are there any other extra costs, or is that just for services and time?", "s": 1726, "trick": "Name what is and is not included", "url": "https://fathom.video/calls/322118977"}, {"a": "Luke confirmed it starts around $4,500 a month and Gregory said to start with that.", "better": "Yes, it starts around $4,500 a month. I do not want you carrying more than you need, so I will check with my team whether to start smaller. Our aim is that it pays for itself. Is that okay?", "call": "Gregory Corbin", "good": true, "q": "The packages were something like $4,500 or $4,900 a month, right?", "s": 368, "trick": "Confirm price, protect their cash", "url": "https://fathom.video/calls/325605508"}, {"a": "Brian said the setup is priced by scope, not by time, and Jonathan confirmed that the 3,750 covers the full launch even if it takes 5 and a half weeks.", "better": "Good question. The setup is one price for the whole launch, not a clock. If it takes a bit longer, the price does not change. Is it helpful if I write exactly what is included?", "call": "Carolina", "good": true, "q": "Is the setup fee for the time or for the full launch?", "s": 2930, "trick": "Say it simply, put it in writing", "url": "https://fathom.video/calls/274394195"}, {"a": "Luke said USD.", "better": "It is USD, 2,300 dollars. I will put that in writing in your welcome email so there are no surprises. Anything else you want clear before you pay?", "call": "Chad", "good": true, "q": "Is the first invoice of 2,300 in USD or AUD?", "s": 48, "trick": "Confirm it in writing", "url": "https://fathom.video/calls/322275597"}, {"a": "Luke did not give a number and asked about their revenue and goals instead, then said SEO is one of the best investments for traffic.", "better": "That is a smart way to think about it. With a small budget I would not spread it thin. Twelve thousand a year is about $1,000 a month, which is below our lowest SEO plan at $1,500, so I would rather be honest than promise too much. I would start at $1,500 a month for three months and see real numbers before you spend more. Does that fit how you would like to test it?", "call": "Chris Savor", "good": false, "q": "How much budget do we need a year to see real growth, maybe 12,000?", "s": 2151, "trick": "Honest number, small test", "url": "https://fathom.video/calls/251114242"}, {"a": "Luke said websites start around 10 thousand dollars for a custom Shopify build and that marketing is multifaceted, so with a 10 thousand budget they would need to be very strategic.", "better": "That is a fair thing to ask, and nobody should have to guess. A website starts around 10 thousand, and ad management is priced on its own, so you do not need to buy everything at once. With about 10 thousand for ads, I would not spread it thin. Can I tell you the one thing I would start with so every dollar works hard?", "call": "Barry Smoak", "good": false, "q": "What do these things cost, like a website, content and managing ads?", "s": 652, "trick": "Make costs feel safe and simple", "url": "https://fathom.video/calls/283039215"}, {"a": "Luke said it is just for the work, then offered to bring it to $2,500 as the lowest, citing a team of 12, work for Porsche and Spotify, and average US pricing.", "better": "Good question. The fee is only for our team, and your ad money goes straight to Google or Meta. I hear that $3,000 feels like a lot for a growing business. Let me tell you what you get: a full team running campaigns, ads, video edits and daily checks. What number would feel comfortable to you?", "call": "Mathieu Bolle", "good": false, "q": "Does the $3,000 include ad spend or just your service?", "s": 433, "trick": "Clarify, then ask their number", "url": "https://fathom.video/calls/545661967"}, {"a": "Luke said to just Google it, that companies are in the 5k to 10k range, and that no US company does it right for less.", "better": "Fair to check, Frank, please do, I would. You will see most agencies doing real cold email land around 5 to 10 thousand a month. That gap is because of the lists, the domains and the writing. The goal is a fair price you feel good about, not the cheapest. Does that match what you are finding?", "call": "Frank Modarelli", "good": false, "q": "If doing it right costs 1,500 just to cover costs, will anyone doing it right charge me double that or more?", "s": 2145, "trick": "Invite them to verify", "url": "https://fathom.video/calls/264528192"}, {"a": "Luke said the price is the same for anything under a $10,000 ad spend, and above $15,000 in spend they charge $10,000.", "better": "Fair question. Our fee stays the same up to about $10,000 in ad spend, so at your size you are paying for the full team, not extra work. You are right that smaller spend can mean less to manage, so I can look at a smaller plan for you. Can I walk you through what you would get for it?", "call": "Christian Hoeffel", "good": false, "q": "Is this one price whether I spend $3,000 or $100,000 a month?", "s": 1179, "trick": "Agree with their logic", "url": "https://fathom.video/calls/317379106"}, {"a": "Luke said they could dive into it later and that he would hold the $1,000 price, but he did not list what is included.", "better": "Good thing to ask. It covers building your Google campaigns, daily management, conversion tracking, landing page advice, and weekly updates from us. It does not cover CRM or email follow up. I will put that in a one page summary so you can see it clearly. Would that help you decide?", "call": "Cesar Diaz", "good": false, "q": "What exactly does the fee include?", "s": 1454, "trick": "List it plainly", "url": "https://fathom.video/calls/860109475"}, {"a": "Luke was unsure, then showed pricing: Google Ads $1,500, Meta Ads $1,800, Klaviyo $2,000, SEO $2,400, and about $3,400 for Google ads and SEO, plus ad spend.", "better": "Happy to give you a clear number. SEO is $2,400 and Google Ads is $1,500, and doing both together is $3,400 a month, plus the money you spend on ads. I would start with the one that fits your budget and add the other later. Want me to put it in a one page summary for your owner?", "call": "Stefan Gutowski", "good": false, "q": "How much would SEO and the ad campaigns cost together?", "s": 1153, "trick": "Know your numbers cold", "url": "https://fathom.video/calls/293071198"}, {"a": "Luke said they only do Google Ads, Meta, SEO and cold email, with a 5,500 a month maximum impact package and an 8,500 hyperscale package. He said he could bring the price down a little.", "better": "We do have all in one packages. Maximum impact is 5,500 a month, and hyperscale at 8,500 covers everything including influencer. Since you already do some of this, we could just pick the pieces that are not working. Can I ask which channel you feel is weakest right now?", "call": "Alex Szilagyi", "good": false, "q": "Do you offer a full suite package for all of our marketing?", "s": 772, "trick": "Offer fit, then ask their weak spot", "url": "https://fathom.video/calls/240152980"}, {"a": "Luke said there is a plan for both Google Ads and SEO at around $3,400, he thought, and offered to share the pricing page.", "better": "SEO and Google Ads are priced separately, and together they are about $3,400 a month. I will put the exact numbers in my email so you can compare them side by side. Since your paid search is already running, we can start with SEO only if you like. Would that make sense?", "call": "Annie", "good": false, "q": "Is Google Ads included in the monthly plan or is it extra?", "s": 1149, "trick": "Be exact, offer a smaller start", "url": "https://fathom.video/calls/301373694"}, {"a": "Luke said they charge monthly and for Google Ads it is under 10k ad spend, without giving a number.", "better": "Happy to tell you. Google Ads is $1,500 a month to manage up to $10,000 in ad spend, and one time setup with tracking is $5,000. Since you are strong on Meta, I would tell you straight what you actually need. Do you want the setup only, or someone to help run it after?", "call": "Noah Sandmann", "good": false, "q": "What is your price?", "s": 79, "trick": "Clear number, then clarify need", "url": "https://fathom.video/calls/248076422"}, {"a": "Daniel quoted 500 a month for creatives, Growth Accelerator at 1,500 a month for up to 10k ad spend per platform, and about 3,000 for Google and Meta together.", "better": "Of course. Before I give numbers, can I ask what you would love the ads to do for you in the first three months? Then I can point you to the one option that fits, so you do not pay for things you do not need. For Meta only, it is 1,500 a month plus 500 for creatives.", "call": "Kristina Shumilova", "good": false, "q": "Can we go over price and fees?", "s": 1728, "trick": "Ask first, then give one price", "url": "https://fathom.video/calls/234074760"}, {"a": "Luke quoted 2,400 for SEO, 1,500 for Google Ads, and 3,400 for both, then offered 2,000 for SEO alone or 2,500 for both, in USD.", "better": "Yes. SEO is 2,400 a month, Google Ads is 1,500, and both together is 3,400, all in US dollars. Because you are new, I can do both for 2,500 if you are ready to start. I would also fix the ads first, so the money works harder. Does that fit your budget?", "call": "Joyce", "good": false, "q": "Do you have a pricing structure, and how would that work for someone in our position?", "s": 1604, "trick": "Give a reason for the discount", "url": "https://fathom.video/calls/322118977"}, {"a": "Luke said it is $1,500 up to $3K of ad spend, then it reverts to 50% of ad spend, so $5,000 on a $10,000 spend.", "better": "Let me make this clearer, because it should not be confusing. Based on your spend of about $11,000, I will give you one flat monthly number instead of a formula. Then you can compare it with what the ads bring in. Can I send you that quote today?", "call": "Mark H", "good": false, "q": "So you are 1,500 plus what? Is it 50 percent of ad spend plus the 1,500, or instead?", "s": 2353, "trick": "Replace formula with one number", "url": "https://fathom.video/calls/524683610"}, {"a": "Luke said he would give a quote and keep it minimal if they do the marketing, though they normally charge 25K minimum for sites.", "better": "Your site is simple with one product, so it should be much smaller than a full build. I'll check with my developers today and send one clear number, bundled with the ads so it stays fair. You'll have it by email today. Does that work?", "call": "Dorian Fleuri", "good": false, "q": "What is the budget to migrate from Wix to Shopify?", "s": 2081, "trick": "Make it small, give a date", "url": "https://fathom.video/calls/564365833"}, {"a": "Luke said he would get back to him and asked how many landing pages he wanted, later confirming $1,500 plus $500, or $2,000 a month.", "better": "Here it is in simple terms. Facebook management is $1,500 a month up to $10,000 in ad spend, and creative is $500 a month flat. That is $2,000 a month, and landing pages are about $500 each when we need them. Does that fit your plan?", "call": "Tony Small", "good": false, "q": "What would the overall price be for Facebook ads, creative and a landing page?", "s": 1650, "trick": "Say the total up front", "url": "https://fathom.video/calls/246099180"}, {"a": "Luke said that is true for something like SEO on a smaller plan, then moved into asking about his revenue.", "better": "Yes, that $1,500 is our smallest plan, and for you I can use it. I would pick Google or Meta, not both, so we can see a clear return. Then we add the second channel once it pays for itself. Does starting with one channel sound okay?", "call": "Christian Hoeffel", "good": false, "q": "Your website says the minimum is $1,500, so how does that fit with these prices?", "s": 1297, "trick": "Connect the price to a plan", "url": "https://fathom.video/calls/317379106"}, {"a": "Luke said it starts at 20,000 and that the 30,000 project he showed was a medium one for them.", "better": "A full brand overhaul with the website starts at 20,000. I want to be honest that it is a real investment, so let me tell you exactly what it covers before you decide. Does it help if I send the scope and what you get for it?", "call": "Jade Pyne", "good": false, "q": "What does a brand overhaul cost?", "s": 1497, "trick": "Price with honesty, then offer detail", "url": "https://fathom.video/calls/242102912"}, {"a": "Megan showed the pricing page: Google Ads from $1,500 a month for spend up to $15k, Meta $1,800, warm email $2,000 and SEO $2,400, all management only and not including ad spend.", "better": "Sure, I will share it. Google Ads starts at $1,500, Meta is $1,800, and SEO is $2,400, and ad spend is separate. Before you pick, can I ask what you want this to do for the business so I point you to the right one?", "call": "Eric Tsu", "good": false, "q": "Can you break down the cost of each service individually?", "s": 646, "trick": "Answer, then get curious", "url": "https://fathom.video/calls/287693226"}, {"a": "Luke answered that it is American dollars.", "better": "It is in US dollars, and I know that stings with the exchange rate. Let me give you the full picture so you can plan, including the first month of ad spend. Does a total of about 5,000 to start still work for you?", "call": "Shabnam Akrami", "good": false, "q": "Is the 1,500 in Canadian or American dollars?", "s": 2225, "trick": "Acknowledge the feeling, then total it", "url": "https://fathom.video/calls/282988891"}, {"a": "Luke said that is with ad spend, that no client spends less than that, and said Meta alone is 1,500 plus 500 for creatives, or 3,000 for both Meta and Google.", "better": "Close. Meta alone is 1,500 to manage, and both platforms are 3,000, with ad spend on top. With a budget this tight I would lean to Meta alone. I want every dollar working for you. Would you like to start there?", "call": "Shiv Patel", "good": false, "q": "Would I expect 5,000 to 7,000 a month with ad spend if we do Meta and Google?", "s": 461, "trick": "Recommend the smaller, safer start", "url": "https://fathom.video/calls/242052539"}, {"a": "Luke said the management fee is $1,500 a month.", "better": "Our management fee is $1,500 a month for Google. Before I say more, let me ask, with a $10,000 ad budget, what would one extra good lead be worth to you? That helps me show you if the fee pays for itself.", "call": "Ken", "good": false, "q": "What does it cost?", "s": 669, "trick": "Tie price to their value", "url": "https://fathom.video/calls/342310585"}], "restricted": [{"a": "Luke said it is a small thing, they are a Google partner, and they handle sensitive words for clients like doctors and clinics with paperwork and long tail keywords.", "better": "That sounds frustrating, and it is more common than you would think. We handle restricted words with Google all the time, with the right paperwork and different phrasing. Since competitors run ads, we know it can be done. Can you send me the ban email so I can see the exact reason?", "call": "Justin Mitchell", "good": true, "q": "My Google ads got banned because of the word Zeolite, can that be fixed?", "s": 775, "trick": "Calm the worry, ask for detail", "url": "https://fathom.video/calls/464049834"}, {"a": "Luke passed it to Asad, who said one general page or policy telling people to consult a doctor is fine and it does not have to be on every product.", "better": "Good thing to check. I am not a lawyer, so I would not promise anything here. From what we see, one clear notice in your policies is usually enough, and less text helps the ad page convert. We can look at it together in week one. Is that okay?", "call": "Sam Daoud", "good": true, "q": "Do I have to put the FDA text on every product page?", "s": 1335, "trick": "Admit limits, offer a next step", "url": "https://fathom.video/calls/551904290"}, {"a": "Luke said they are used to restrictions, research the brand rules first, run all copy through AI checks, and share a Google Sheet she can approve.", "better": "Good that you raised it. We learn your rules first, then check every ad before it goes live. You approve the copy in a shared sheet, so nothing runs without your yes. Would you like to send me a list of words to avoid?", "call": "Matt Holdridge", "good": true, "q": "How do you handle product claims we cannot make, since our natural products are not FDA approved?", "s": 2145, "trick": "Give them final approval", "url": "https://fathom.video/calls/469763535"}, {"a": "Luke said they would look at the history, likely set up a new account and check the URL, and said they follow Google's policies.", "better": "It depends on why it was flagged, so I would look at the history first. Sometimes we can appeal, and sometimes a clean new account is safer. Either way, we check every ad against the policy before it goes live. Can you send me the notice Google gave you?", "call": "Kay Pollard", "good": false, "q": "Can you recover a Google Ads campaign that was flagged, or would you start a new one?", "s": 1403, "trick": "Be honest, then ask for facts", "url": "https://fathom.video/calls/241212547"}], "results": [{"a": "Luke said the goal is as high as possible and walked her through a sample workbook covering competitors, keywords, guest post outreach and content, without promising a rank.", "better": "Page one is a fair goal, and I get why you want it soon when others already have the authority. I will not promise a spot, because nobody honest can. What I can promise is a clear plan: we find who you are up against, pick keywords that are easier to win first, and build links the right way. Want me to show you how that looks on a real example?", "call": "Annie", "good": true, "q": "Can you get us onto page one of Google, and what does it take?", "s": 284, "trick": "Honest goal plus clear plan", "url": "https://fathom.video/calls/301373694"}, {"a": "Luke said no agency can honestly promise a specific ROAS, he will give 110 percent every day and work month to month so clients can leave if it does not improve.", "better": "I understand the pressure you are under with your management. I will be honest with you, nobody can promise a number, and anyone who does is guessing. What I can promise is we will break down the campaign in week one, show you what is wasting money, and report on it weekly. Can we agree what progress would look like in 60 days?", "call": "Mark", "good": true, "q": "Can you get us above a 2.5 ROAS?", "s": 3507, "trick": "Honest no, then a milestone", "url": "https://fathom.video/calls/226492580"}, {"a": "He refused to guarantee any ROAS, said it differs by business, and said results on Meta can come fairly quickly.", "better": "I will be straight with you, no honest agency can promise a number, and I would not trust one that did. With bottles at 128 and 228 euros and a fan base that already cares, we have a good setup, and Meta usually shows early signals in the first few weeks. We will track it weekly and show you every number. Does that feel fair?", "call": "Leonard Emini", "good": true, "q": "What ROAS can we expect, even a rough average for a Shopify store?", "s": 1528, "trick": "Honest no, then real reasons", "url": "https://fathom.video/calls/271080025"}, {"a": "Brian said it is tough to put a number on it, setup takes up to 7 days, results can come right away, and he could not guarantee ROAS.", "better": "I wish I could give you an exact day, but anyone who does is guessing. Here is what I can say: we launch within 7 days, Meta usually shows early signals in the first couple of weeks, and the real gains come from weekly testing. I would measure the first month by whether you are moving toward break even. Does that sound fair?", "call": "Purepiel", "good": true, "q": "How many days will it take to get results and be profitable?", "s": 670, "trick": "Honest about what we can promise", "url": "https://fathom.video/calls/272300366"}, {"a": "Luke said they start right away, move after two to five days, and he would know by month one or two.", "better": "I hear you, after five years of waiting you need proof fast. In the first few days we fix the biggest mistakes in your account. Within two to four weeks you should see calls cost less and the budget lasting longer. I won't promise a number before I see your account, but I'll show you the data every week. Fair enough?", "call": "After hours alcohol delivery prospect", "good": true, "q": "How many days until I will know it is working?", "s": 313, "trick": "Acknowledge pain then give timeline", "url": "https://fathom.video/calls/858246139"}, {"a": "Luke said nobody can guarantee that, but it is highly likely, and that paid Google ads can get him there right away with about $2,000 ad spend.", "better": "I wish I could promise that, but anyone who does is not being honest with you, because Google decides. What I can promise is a clear plan, hard work, and updates you can see every month. And if you need traffic sooner, ads can start sending visitors in days. Which matters more to you right now, speed or lower cost?", "call": "Kevin Huang", "good": true, "q": "Can you guarantee my website will be on the first page of Google?", "s": 1874, "trick": "Be honest, then give a choice", "url": "https://fathom.video/calls/300079094"}, {"a": "Luke said matching the old site might take six to nine months or a year, but profit can come much sooner.", "better": "Honestly, the old site has years of history, so catching it fully takes time, about 6 to 9 months. Making money is a different goal and can happen much sooner, because we start with the keywords that bring buyers. I would watch profit first and rankings second. Does that feel like the right way to measure it?", "call": "Shabnam Akrami", "good": true, "q": "How long until the new site can match the old site?", "s": 1166, "trick": "Split the goal in two", "url": "https://fathom.video/calls/282988891"}, {"a": "Brian said they would research the competitor and their ads, use tools to see their best ads, and put more focus on other countries while working on Canada.", "better": "That would frustrate me too, seeing someone grow so fast on a similar product. I cannot promise we will beat them, but I can promise a plan: we study their best ads, find what they are missing, and also sell in markets they are not in. Would you like me to run a quick look at their ads and share what I find?", "call": "Purepiel", "good": true, "q": "Can we take back market share in Canada from a competitor making 10 to 15k a day?", "s": 1444, "trick": "Acknowledge the feeling first", "url": "https://fathom.video/calls/272300366"}, {"a": "Luke said hundreds of searches is not bad, it is long tail with less competition, and they use Semrush, Ahrefs and Keyword Planner to build a plan.", "better": "That is smart research, Kyle. Low volume is common for niche services, and it can be a good thing, because fewer people bid on those words. With a project worth about 10,000, a few good leads a month can pay off. We will check real numbers in our paid tools before you spend anything. Does that make sense?", "call": "Kyle", "good": true, "q": "Will the low search volume I found for my keywords hurt what we can do with ads?", "s": 796, "trick": "Turn the worry into an upside", "url": "https://fathom.video/calls/263406837"}, {"a": "Luke said sales can come in days or hours for some clients, but he would not bet on that for Kyle, and week one and two will show what is happening.", "better": "Honest answer, Kyle, nobody can promise a date. Some accounts get leads in days, and for a niche like yours I would expect the first signs in two weeks, and clear direction by month one. Google also gets smarter over time. If it is not working at month one, I will tell you straight. Is that a fair deal?", "call": "Kyle", "good": true, "q": "How fast do results start, does it hit the ground running or take a month?", "s": 1563, "trick": "Promise honesty, not a date", "url": "https://fathom.video/calls/263406837"}, {"a": "Luke said he does not promise sales or ROAS, shared that clients range from a 15x return to some at 0.8 who lose money, and said most land in the middle.", "better": "I wish I could give you a number, but anyone who does is guessing. I can tell you what we have seen, from a 4x to a 15x, and a few that did not work. Your product looks special and you already have a list, which helps a lot. We will know a lot by month three. Can I show you what we would measure first?", "call": "Temisan", "good": true, "q": "If everything goes to plan, what level of sales would you expect after 12 months?", "s": 2404, "trick": "Honest range builds trust", "url": "https://fathom.video/calls/229608484"}, {"a": "Luke said about four to five months to start getting traffic, about a year for really good traffic, and it keeps getting stronger in years two to four.", "better": "I get why you want to know, nobody likes waiting. Honestly, you will usually see traffic start to move around month four, and it gets strong around month twelve. I would rather tell you that now than promise something fast. Does a first year plan like that fit how you are thinking about this business?", "call": "Kevin Huang", "good": true, "q": "How long until the first stage gives a good result?", "s": 1705, "trick": "Say the honest timeline first", "url": "https://fathom.video/calls/300079094"}, {"a": "Luke said month one is warming and light testing, month two scales what works above a 2 to 3 percent reply rate, month three is full capacity, and he wants a verbal three month commitment.", "better": "Think of it in three steps. Month one we warm the mailboxes and test messages. Month two we grow what works, looking for a 2 to 3 percent reply rate. Month three we run at full speed. You will see numbers each month, so you always know where you stand. Does that match how you build your own campaigns?", "call": "Joseph Gissy", "good": true, "q": "How long does it take to know if an email campaign is working?", "s": 1689, "trick": "Give a simple 3 step timeline", "url": "https://fathom.video/calls/230308235"}, {"a": "Luke said Google paid ads are pretty fast and a fresh account will not take three months, but SEO is slower and she would be competing with her own other site.", "better": "I hear you, you need this to pay for itself and not sit and wait. Paid ads are the fastest part, so we would aim for leads in the first weeks, not months. SEO is the slower one, so we would add it after the ads are making money. Is it okay if I show you what a realistic first 90 days looks like?", "call": "Shabnam Akrami", "good": true, "q": "How fast can this work, because I do not have months to wait?", "s": 360, "trick": "Echo their words first", "url": "https://fathom.video/calls/282988891"}, {"a": "Luke said with a 10k package paid ads can start in week one and leads come quickly, while SEO grows in the background.", "better": "Paid ads can bring leads in the first week, because people are searching right now. The first month is also testing, so I expect things to get better after that. SEO is slower, about three or four months. Does it help to know which part gives quick leads and which part builds over time?", "call": "Garret Ashton", "good": true, "q": "Is there a ramp up period before leads start coming in?", "s": 1929, "trick": "Split fast and slow results", "url": "https://fathom.video/calls/228223662"}, {"a": "Luke said it is what they do all day, they are Google premier partners with direct information, and he would not promise ROAS but would work hard daily.", "better": "That cycle sounds exhausting, and it should not be on your plate. Watching Google changes is part of our day job, and we are a Google premier partner so we hear early. I cannot promise a number, but I can promise we will find what broke first. Does that sound like the help you need?", "call": "Marius Negru", "good": true, "q": "Do you stay informed about Google changes? Updates keep hurting my sales.", "s": 1250, "trick": "Echo the pain, honest promise", "url": "https://fathom.video/calls/525995385"}, {"a": "Luke said every campaign runs on splits, with around 160 ads at once and tiny changes to lower CPC, and Kristina added that the current Facebook ads stay running so leads do not stop.", "better": "Great question, nobody wants a gap in leads. We do not turn off what works. We keep your current ads running, then add new tests next to them and phase out the weak ones. Usually you see the first test results in a few weeks. Does that kind of smooth handover feel right for you?", "call": "Eric D Shepard", "good": true, "q": "Will you do split testing, how long does it take, and will we keep getting leads while you do it?", "s": 581, "trick": "Remove the fear of a gap", "url": "https://fathom.video/calls/470388378"}, {"a": "Luke said they pivot all the time, run up to 160 ads, and by about six weeks they know if it works, with roughly 15 percent not hitting ROI and then a changed plan.", "better": "Great question. We watch the numbers daily and change things every week, but by about six weeks we know if the channel is working. About 15 percent of the time it is not, and we tell you straight and change the plan or step back. You never get surprised. Does that sound fair?", "call": "Joseph Gissy", "good": true, "q": "When do you decide a campaign is not working and change course?", "s": 1099, "trick": "Share the honest failure rate", "url": "https://fathom.video/calls/230308235"}, {"a": "Luke said he is confident in his team and reputation but only promises full dedication, and that his monthly model means he loses too if it falls flat.", "better": "I feel good about it because I can see others already paying for these clicks. I will not promise a result, nobody honest can. What I promise is daily work and straight talk, and we only win if you do. The one thing I would fix first is your page. Can I show you what I mean?", "call": "Amy N Neighbors", "good": true, "q": "Are you confident I can get a client?", "s": 3035, "trick": "Honest confidence, no hype", "url": "https://fathom.video/calls/485151651"}, {"a": "Luke said they do not guarantee numbers because no one honestly can, but they guarantee a great plan, hard work and monthly retainers that keep them accountable.", "better": "I wish I could promise a number, but anyone who does is not being honest. What I can promise is a clear plan, monthly reports, and that you can leave if it is not working. Authority is just one signal, and sales matter more. What number would make you happy a year from now?", "call": "Joyce", "good": true, "q": "Do you guarantee results, like raising our website authority from 9 to 20 or 30 in 12 months?", "s": 830, "trick": "Honest no, then what we promise", "url": "https://fathom.video/calls/322118977"}, {"a": "Luke said yes, the first week of analysis gets them off the ground, though it will not match a client with four years of data.", "better": "Yes, and your season makes that important. We would skip the long learning and start with the cities and keywords most likely to sell, then adjust every day. You should see early signals in the first couple of weeks. Can I show you what the first 14 days would look like?", "call": "Larry Pomerantz", "good": true, "q": "Can you shorten the testing so we see results in weeks, not months?", "s": 1423, "trick": "Match their urgency", "url": "https://fathom.video/calls/276740502"}, {"a": "Luke said if a $2,000 test gives a contract or two leads it works, a few leads and two calls in month one is a big win, and they scale only when data shows profit.", "better": "Smart thing to ask before spending. I would watch three things: leads that match your buyer, calls booked, and cost per call. Even five leads and two good calls in month one tells us a lot. We will not guess, we will show you the data. What would a win look like for you?", "call": "Justin Mitchell", "good": true, "q": "What gauges should I use for success, and how much should I put in before I know?", "s": 2074, "trick": "Define a win together", "url": "https://fathom.video/calls/464049834"}, {"a": "Luke said we do not guarantee anything, they work extremely hard, charge monthly so they have to make sales to keep him, and think Sam can make sales after site tweaks.", "better": "I will be honest with you, nobody can guarantee sales, and I would not trust anyone who does. What I can say is we have run a very similar product with a good return before. You only stay with us if the sales come, so our goal is the same as yours. Does that feel fair?", "call": "Sam Daoud", "good": true, "q": "You have worked with something like this, right? It will at least return my money?", "s": 1196, "trick": "Honest no guarantee, shared goal", "url": "https://fathom.video/calls/551904290"}, {"a": "She said a 5% positive reply rate is actually high, and agreed that around 10 meetings a month is realistic but not guaranteed.", "better": "Good thing to ask. A positive reply rate of 2 to 5 percent is strong in cold email, so 5,000 emails could give you roughly 10 meetings, though the first month is mostly testing. I would rather be honest now than overpromise. Does 10 meetings a month work for you?", "call": "Ricardo Amaya", "good": true, "q": "If you send 5,000 emails, how many meetings does that turn into?", "s": 810, "trick": "Reality check with a range", "url": "https://fathom.video/calls/269795639"}, {"a": "Luke said he is not an expert in auctions, that it could work if SEO and Google Ads lead to highbid.com, but he did not want to advise on something he does not fully understand.", "better": "Honestly, auctions are new to me, so I will not guess. What I can say is that Google works best when people are searching for what you sell. A tiny test of search ads would tell you quickly if that is true. Would you like to try that before spending on a site?", "call": "Yesset Karayev", "good": true, "q": "Does my step by step strategy seem okay to you, and would Google ads work for auctions?", "s": 2537, "trick": "Admit limits, suggest cheap test", "url": "https://fathom.video/calls/455546501"}, {"a": "Luke said they range from 0.8 to 15 or 20 ROAS, most clients sit at 3 to 4, no guarantees, and the goal is lower cost per click and more conversions.", "better": "I will be straight with you. We do not promise a number, because anyone who does is guessing. Most clients land around 3 to 4, a few are at 8 or more, and a few struggle near 1. We will know by month two which group you are in. Is that honest picture helpful?", "call": "David Marcyniuk", "good": true, "q": "Do you have a standard ROAS goal you aim for with each client?", "s": 1385, "trick": "Honest range builds trust", "url": "https://fathom.video/calls/231509507"}, {"a": "Luke said the rebrand takes about four to six weeks and the build another two to three weeks, depending on feedback.", "better": "About four to six weeks for the brand and two to three more for the site build, so around eight weeks if we move well together. It can shift if we need to start a direction over, and I would tell you early if so. Does that timing work with your plans?", "call": "Jade Pyne", "good": true, "q": "How long will the whole brand and website process take?", "s": 1860, "trick": "Honest range with a reason", "url": "https://fathom.video/calls/242102912"}, {"a": "Luke said they pivot daily, watch each ad, and may run around 160 ads at once even on a small budget, turning things on and off.", "better": "We expect content to wear out, so we plan for it. We test new reels all the time and watch each one every day. When one slows down, we replace it fast. You send us fresh content and we tell you what to make more of. How often do you post new reels?", "call": "Anyro", "good": true, "q": "How do you handle an industry where creative changes fast and content stops working?", "s": 1344, "trick": "Plan for the problem openly", "url": "https://fathom.video/calls/227623273"}, {"a": "She said there is a warm up period and she cannot guarantee immediate results, but they will keep testing to get them as fast as possible.", "better": "Ten is a realistic goal, but I will not promise it for month one. The first weeks are warm up and testing, then results usually build in month two and three. I will show you the numbers every week so nothing is hidden. Is that okay with you?", "call": "Ricardo Amaya", "good": true, "q": "So should we expect around 10 leads a month out of that?", "s": 1082, "trick": "Set the timeline up front", "url": "https://fathom.video/calls/269795639"}, {"a": "Luke said they start slow and strategic, for example 2K on Google, watch clicks and sales, and pivot or stop if traction is bad.", "better": "That fear is healthy, it's your money and you were close to bankrupt before. We start small, watch every click and sale, and I'll tell you straight away if it's not working. You can pause anytime. Would starting with one platform feel safer?", "call": "Dorian Fleuri", "good": true, "q": "I'm afraid to spend lots of money and get no return. How do I know it's worth it?", "s": 675, "trick": "Honor the fear then lower the risk", "url": "https://fathom.video/calls/564365833"}, {"a": "Brian said they do not promise ROAS because it varies, but promise hard work, daily optimization and communication.", "better": "I will be honest, nobody can promise 5X, and I would worry about anyone who does. What I can promise is daily work, clear numbers and fast changes when something is not working. Would you like to hear what a realistic first goal looks like?", "call": "Brian (mock call 1)", "good": true, "q": "Can you guarantee me a 5X ROAS?", "s": 2403, "trick": "Honest no, then offer a goal", "url": "https://fathom.video/calls/267787294"}, {"a": "Luke said he would send videos, citing Mango Vans going from about 1M to 4M, Decoyer Assault from 1M to 3M, a client at 5X in two months and Blue Planet at 8.5X.", "better": "Happy to. With Mango Vans we fixed tracking in month one, then grew spend only on what worked, and they went from about 1M to 4M. Results differ for every business, so I will not promise yours. I will send the video today. Sound good?", "call": "Darren Lebel", "good": true, "q": "Give me an example of where you started with a client, month one and month two.", "s": 1236, "trick": "Tell the story, no false promise", "url": "https://fathom.video/calls/504983103"}, {"a": "Luke said start right away, her site looks good with nothing blocking sales, and they will move the data over to the new site.", "better": "Great question, nobody wants to waste money. Your current site works, and the data we gather now moves to the new site. So we learn first and launch stronger. Would you like us to keep a small test budget until the new site is live?", "call": "Joyce", "good": true, "q": "Should we start before our new website launches or wait?", "s": 527, "trick": "Remove the waste fear", "url": "https://fathom.video/calls/470472685"}, {"a": "Luke said not lower than $2,500, that he has no clients spending $4,000 to $10,000 under a 4X ROAS, and that some fail, mostly startups and very competitive niches.", "better": "I like that you think this way. Around $2,500 a month is where I would start, and two booked jobs in two months at your price would already pay for it. I cannot promise it, but I will tell you early if it is not working. Fair?", "call": "Amy N Neighbors", "good": true, "q": "What do we need to spend to at least get one client and start churning?", "s": 1996, "trick": "Show the break even math", "url": "https://fathom.video/calls/485151651"}, {"a": "Luke said that is her choice but people buy just as much, Thanksgiving is not a big hurdle, and he would not wait.", "better": "I get the worry, it feels like a busy time. For B2B, buyers still search in November and December, and starting now means we have data by January. Waiting does not make it easier. Would you rather start light now?", "call": "Amy N Neighbors", "good": true, "q": "Is now a bad time to start because we are heading into the holidays?", "s": 2979, "trick": "Answer the fear, then give a low risk option", "url": "https://fathom.video/calls/485151651"}, {"a": "Luke said they always try to reduce cost per click, that it sounded reasonable and the keywords were straightforward, and he would check with the team.", "better": "Six dollars is a good target to work toward. I cannot promise a number before I see real search data, but I will check your keywords and tell you what looks realistic. Fair?", "call": "Maria Costa", "good": true, "q": "Can you keep the cost per click under 6 dollars?", "s": 1402, "trick": "Honest about limits", "url": "https://fathom.video/calls/253101615"}, {"a": "Luke walked through month one setup and warming, scaling in months two and three, said about 15 percent of cold email clients never catch, and said the team aims for 4 to 6 positive leads per week.", "better": "I will be straight with you, I cannot promise a number, and anyone who does is guessing. What I can say is month one is setup, month two we scale what works, and we aim for 4 to 6 positive leads a week. You will know by week five or six if it is working. And if it is not, I will tell you right then, not hide it. Does that feel like a fair way to start?", "call": "Doug Fiore", "good": false, "q": "What should my expectations be in terms of success with cold outreach?", "s": 1538, "trick": "Honest range and early checkpoint", "url": "https://fathom.video/calls/242167771"}, {"a": "Brian said he believes so but it depends on creatives and targeting, and that he could not guarantee ROAS, only daily work from a Facebook team.", "better": "I will not promise break even, because I do not know your margins yet. What I can say is that most of the result comes from creative and targeting, and those are the two things we will fix first. Let us run the audit, work out the sales you would need to cover our fee, and decide together if it makes sense. Can I look at your numbers this week?", "call": "Purepiel", "good": false, "q": "With a $1,000 ad spend, can we at least break even after paying you?", "s": 1654, "trick": "Replace a promise with a plan", "url": "https://fathom.video/calls/272300366"}, {"a": "Luke said it is a complicated question, they have not tested campaigns yet, he thinks they can make sales, and they would decide what to cut in month one.", "better": "I hear you, you have worked hard on this and you want to know it is worth it. Honestly, I cannot promise sales before we test. What I can say is we will start with your best two or three products, like the cold plunge, and watch the data for a few weeks. Then we keep what sells and drop what does not. Would you be okay starting small like that?", "call": "Sam Daoud", "good": false, "q": "Will this generate sales, or are there too many products on my site?", "s": 823, "trick": "Honest about doubt, narrow the start", "url": "https://fathom.video/calls/551904290"}, {"a": "Luke said he still thinks it will be improved and that the brand and new site are good, without giving a number.", "better": "Fair question, and I want to give you a real answer. I would rather show you the actual numbers for our speaker client than quote a figure, because their order value is much higher than yours. What I can say is we start by rebuilding the campaign structure, then test the creative. Would you like me to share that case study in my email?", "call": "Mark", "good": false, "q": "What ROAS do you get for your other speaker client?", "s": 1023, "trick": "Offer proof, not a vague line", "url": "https://fathom.video/calls/226492580"}, {"a": "Luke first said it depends on the offer, then gave a 2 to 8 percent reply rate and a goal of over 20 percent positive replies, and said they will not scale until a campaign shows at least 2 to 2.5 percent replies.", "better": "I will be honest, I can not promise a number, because it depends on your offer. What I can tell you is what we usually see, 2 to 8 percent replies, and we do not turn up volume until we hit about 2.5 percent. So you never pay for a campaign that is not working yet. Can we talk about your offer so I can give you a more exact guess?", "call": "Andrew Milstead", "good": false, "q": "How many appointments do you usually get from the leads you send out?", "s": 1212, "trick": "Honest range plus a safety rule", "url": "https://fathom.video/calls/229583830"}, {"a": "Luke replied with a question about whether he can control CPC, then said it is their job to reduce the CPC and raise the conversion rate.", "better": "Great question. We can't set the price of a click, but we can lower it with better ads, tighter keywords and a stronger landing page, because Google rewards good ads with cheaper clicks. Then we raise how many clickers become calls. I'd need to see your account to know how much room there is. Can we take a look together?", "call": "After hours alcohol delivery prospect", "good": false, "q": "How do you get the CPC down to the lowest?", "s": 452, "trick": "Explain the real levers simply", "url": "https://fathom.video/calls/858246139"}, {"a": "Luke said it comes in levels: at least 3 to 4 months for rankings to come in well, and up to a year for top of page results, but it depends on budget and goals.", "better": "Great question. Here is the honest picture. In the first 7 to 10 days we build your plan. Around month 3 or 4 you should see rankings move, and the big wins usually take closer to a year. Healthcare is competitive, so I would rather tell you that now than surprise you later. Does that timeline fit what your team needs?", "call": "Annie", "good": false, "q": "How long does it take to set up a plan like this and see results?", "s": 779, "trick": "Simple timeline in stages", "url": "https://fathom.video/calls/301373694"}, {"a": "Luke said it depends and it is hard to give an exact figure, and that their job is to lower cost per click and cost per conversion every day.", "better": "That is the right question, and anyone who gives you an exact number today is guessing. Here is how I would find out fast: run a small test on your best cities for two weeks, then we know your real cost per sale. If it does not make sense at 50 dollars, we say so and stop. Would a two week test fit your season?", "call": "Larry Pomerantz", "good": false, "q": "What will it cost to get a customer from Google for a 50 dollar barrel?", "s": 914, "trick": "Offer a small test, not a promise", "url": "https://fathom.video/calls/276740502"}, {"a": "Luke's side moved straight to the pricing page and did not answer the proof request directly; they later mentioned a fashion client on Shopify with solid ROAS.", "better": "That makes total sense, you are about to put real money behind a launch, so you should see proof first. I can share how we run a similar Shopify store, and if you want, we can talk to one of our clients near the end once you are close to deciding. Would it help if I send over a short example after this call?", "call": "Leonard Emini", "good": false, "q": "We want to see proof that your ads work, not just talk about budget.", "s": 723, "trick": "Honor the proof request first", "url": "https://fathom.video/calls/271080025"}, {"a": "Luke said it is hard to gauge, gave examples of 350 leads a month for a 40k ad spend client and about 45 for smaller clients, and said they will definitely get leads.", "better": "I can not give an exact number and I will not make one up. Smaller service clients often see around 45 leads a month, and bigger budgets see a lot more. Your competitors already run ads in Houston, so we know people are buying. We can set a target together after week two when we see real data. Fair?", "call": "Garret Ashton", "good": false, "q": "Is there any idea how many leads or calls we can expect in the first month?", "s": 5157, "trick": "Share real examples, skip the promise", "url": "https://fathom.video/calls/228223662"}, {"a": "Luke said they would talk it through and look at it for him, without giving a reason.", "better": "That is frustrating, and you are right to be annoyed. Reviews help, but they are only one piece. Page content, keywords and your site setup also count, and Wix makes that harder. Let us look at why you are missing and give you a clear fix. Would you like us to check your profile and site this week?", "call": "Colin Hornbaker", "good": false, "q": "I have 10 times the Google reviews of my competitors and still do not show up on Google, why?", "s": 662, "trick": "Validate the frustration first", "url": "https://fathom.video/calls/231727969"}, {"a": "Luke said a lot of work goes into SEO and they can keep putting pressure on the search engines, and asked if the price was in his range.", "better": "Almost. Tracking and a clean Google Ads setup can be done in about a week or two. SEO is different, it takes a couple of months to build and then keeps growing. Since you want the ads and tracking right first, I would start there. Want me to walk you through what we would check in your tracking?", "call": "Noah Sandmann", "good": false, "q": "We should have everything set up in a month or two?", "s": 234, "trick": "Split fast fix from slow build", "url": "https://fathom.video/calls/248076422"}, {"a": "She said ROI is tricky, they track positive reply rate and bookings, they have similar clients, and a client call can be a final step.", "better": "Fair question. We track positive replies and booked meetings, and your numbers on what a meeting is worth will tell us the real return. We do have clients like you, and when you are close to deciding I can set up a short call with one of them. Roughly what is a new client worth to you?", "call": "Ricardo Amaya", "good": false, "q": "Do you have similar clients, and what ROI could we expect?", "s": 660, "trick": "Turn ROI into their numbers", "url": "https://fathom.video/calls/269795639"}, {"a": "Luke said that would only be break even and he would be happy to get that, and mentioned some clients spend 2K and make 70K while others do not make money.", "better": "Careful, that's the right way to think about it. With your margins, 10K from 5K may only break even, so we aim higher over time. In month one we learn, and I can't promise a number. Let's look at your margin and set a target return together. Want to do that on the next call?", "call": "Dorian Fleuri", "good": false, "q": "If I spend 5K a month and reach 10 or 15K, is it worth it?", "s": 1789, "trick": "Use their numbers to set a target", "url": "https://fathom.video/calls/564365833"}, {"a": "Luke gave a long answer about Google being underused at 20 dollars a day, tracking profit on ad spend, and said if they do not make money clients will leave.", "better": "Great question. We look at the numbers every week, and if something is not working we change it fast or turn it off. You are never locked in, so you can stop any month. I would rather tell you early than waste your money. Does knowing you can walk away make this feel safer?", "call": "Stephanie Webb", "good": false, "q": "What if the marketing does not work well, do we look at it and stop spending?", "s": 793, "trick": "Answer the fear in one line", "url": "https://fathom.video/calls/227326702"}, {"a": "Luke said it could be many things like strategy, ad quality or landing pages, and that it is probably the wrong strategy or manager.", "better": "I know that is frustrating. It could be a few things, such as feed quality, audience, or the landing page, and I would not blame anyone without the data. We would check each of these in week one and fix the biggest one first. Can I see your funnel numbers after we start?", "call": "Joyce", "good": false, "q": "Why is our conversion rate lower than the industry average?", "s": 637, "trick": "Name causes, not blame", "url": "https://fathom.video/calls/470472685"}, {"a": "Luke said they do not commit to a number, it ranges from zero to several replies a day, and it depends on the offer and audience.", "better": "I understand wanting a number. I do not promise one, because it depends on your offer and audience, and I think you would rather hear honest. A good plan is to test small, then show you real numbers after the first few weeks. Would you like to see how we set targets?", "call": "Gio", "good": false, "q": "How many demos can we expect per month with this strategy?", "s": 1407, "trick": "Honest range, not a promise", "url": "https://fathom.video/calls/267686901"}, {"a": "Luke said only from the surface of what Doug told him, and that Doug's background is a strength they would play on.", "better": "From what you have told me, yes, I feel good about it. You close above 50 percent and your background is a real hook for us to use. I would want a week of research to be certain, but I do not see a red flag. Want me to test a few hooks and show you the first replies?", "call": "Doug Fiore", "good": false, "q": "Do you feel confident you could drive leads into my business?", "s": 2507, "trick": "Confidence with a real reason", "url": "https://fathom.video/calls/242167771"}, {"a": "Luke said most clients run Google Ads and SEO together, so paid ads give quick results while SEO builds. He did not give a specific time.", "better": "Fair to ask, since you want to at least break even. Ads can bring sales in the first weeks, while SEO usually takes a few months to build. That is why I like running both, so ads pay the bills while SEO grows. I will give you honest checkpoints at 30, 60 and 90 days.", "call": "Mcbride", "good": false, "q": "How long would we have to wait to see a return on the investment?", "s": 914, "trick": "Give honest checkpoints, not promises", "url": "https://fathom.video/calls/241078094"}, {"a": "Luke said the success comes from the right setup so people search for the right things, and gave painter and pink elephant examples, without saying plainly that there is no guarantee.", "better": "You are right, there is no guarantee, and I would not trust anyone who gave one. What I can promise is the setup is done properly, so you only pay for people who want an architect. And we check it every day. Would you like to hear how we would protect your budget?", "call": "Alexandra Bailey", "good": false, "q": "There is no guarantee of success with this, is there?", "s": 1315, "trick": "Agree first, then reassure", "url": "https://fathom.video/calls/527818977"}, {"a": "Luke said there is no fixed number, from a few clients with 15x to others with 2 to 3x, and some not profiting.", "better": "It really varies, and I will be straight with you. Some clients grow 10 times, many grow 2 to 3 times, and a few are harder. Where you land depends on your market and your starting point, so I would show you one example close to yours. Can I send that over?", "call": "Joyce", "good": false, "q": "How much do your clients improve after they work with you?", "s": 1005, "trick": "Honest range, then a close example", "url": "https://fathom.video/calls/322118977"}, {"a": "Luke said Google is where customers search, offered testimonials, and said he would show live non competing accounts only if Eric was about 90% sure.", "better": "Fair question. I cannot promise a number, but we can set one up together: how many leads you need, what a job is worth, and we track calls and form fills so you see it every month. Want to figure out what a good number looks like for you?", "call": "Eric Tsu", "good": false, "q": "Is there any way to measure results beyond showing me someone else's revenue?", "s": 1193, "trick": "Make the proof measurable", "url": "https://fathom.video/calls/287693226"}, {"a": "Luke said they keep client information private.", "better": "I understand wanting numbers. I cannot share a specific client's, but I can say what we aim for: a 2 to 4 percent reply rate with 20 percent or more positive. We will track yours from week one so you see it first hand. Would that work?", "call": "Gio", "good": false, "q": "Do you have numbers on demos booked for your cold email clients?", "s": 1100, "trick": "Share targets, not secrets", "url": "https://fathom.video/calls/267686901"}, {"a": "Luke said nobody can predict ROAS, that the team works every day to raise ROAS and lower cost per click, and the main goal is just to keep going up.", "better": "I wish I could promise a number, but nobody honest can. With your site and product, 3 is a fair goal to aim for. We would set a baseline in week one and track it every week. Can you share your current ROAS so we can plan from there?", "call": "Joyce", "good": false, "q": "If it goes on the right track, can we get to a 3 ROAS?", "s": 448, "trick": "Honest about limits, then plan", "url": "https://fathom.video/calls/470472685"}, {"a": "Megan said it is a monthly budget, recommended three months to get the best results, said it is month to month, and that clients often get customers in two to three weeks, though not guaranteed.", "better": "That is per month. Most people see first leads in a few weeks, but the best results come around month three once Google has learned. I cannot promise it, but I will be honest with you along the way. Does that timeline work?", "call": "Daniel", "good": false, "q": "A thousand for what period?", "s": 445, "trick": "Honest timeline, no promise", "url": "https://fathom.video/calls/286220389"}, {"a": "Luke said it cannot be predicted because lead costs differ by market, though after keyword research they can estimate, and it is better to start and see.", "better": "I cannot give you an exact number yet, and I would rather be honest. After we study your keywords, I can show you what a lead usually costs in your market. Then we will have a real estimate, not a guess. Fair?", "call": "Alexandra Bailey", "good": false, "q": "How many leads will I get from the $1,000?", "s": 1479, "trick": "Honest uncertainty, then a plan", "url": "https://fathom.video/calls/527818977"}, {"a": "Luke said I think so, but he needed more detail on the target and keywords, and that Google ads has a 90 percent success rate though success is never guaranteed.", "better": "I want to say yes, but only after I look at your keywords and site. If it is a fit, you will hear a clear yes with a plan. If not, I will tell you honestly. I can give you that answer tomorrow.", "call": "Maria Costa", "good": false, "q": "Is this a project you are willing to take on and execute successfully?", "s": 912, "trick": "Confident but honest", "url": "https://fathom.video/calls/253101615"}, {"a": "Luke said ROI is hard to measure in cold email, clients get contracts of $5,000 to $100,000, and the job is booking meetings.", "better": "With cold email, the real number is deals from meetings, so we measure that together. Some of our clients land contracts from $5,000 up to $100,000. What would one new client be worth to you?", "call": "Gio", "good": false, "q": "What kind of ROI have your clients seen?", "s": 1030, "trick": "Make ROI about their math", "url": "https://fathom.video/calls/267686901"}, {"a": "Luke said he was not sure and passed the question to Matthew, his main Google lead.", "better": "Good question. Most likely yes, costs and demand move with the season, but I want Matthew to give you the real numbers for pools. I will have him send you a short answer today. Is that okay?", "call": "Darren Lebel", "good": false, "q": "Will cost per click be different between winter and the main season?", "s": 1128, "trick": "Honest, then take a next step", "url": "https://fathom.video/calls/504983103"}], "team": [{"a": "Luke said they do everything in house, from researching the ideal customer, to scraping and enriching lists, to a content writer producing the copy.", "better": "Great question, Frank. You do not have to write a word or build a list, that is our job. We study who your best customer is, build and clean the list, and our writer crafts every email. You only approve the message and take the replies. Would it help if I showed you how one of those campaigns looks?", "call": "Frank Modarelli", "good": true, "q": "Do you write the emails and build the lead list, or is that all on me?", "s": 660, "trick": "Take the work off them", "url": "https://fathom.video/calls/264528192"}, {"a": "Luke said the 1,800 entry fee may not match a freelancer but he lowered it, and his team has separate people for strategy, technical work, coding and design.", "better": "I get it, a freelancer can feel safer, and you already trust people like that. One person has to be good at strategy, tech, design and video, and that is hard. With us you get a team for the price of one person. And I already lowered the price for you. What matters most to you here, price or speed?", "call": "Christy Acton", "good": true, "q": "Why choose an agency over an individual freelancer when price is the barrier?", "s": 2117, "trick": "Respect their choice, then compare", "url": "https://fathom.video/calls/358280745"}, {"a": "Luke said they are a small team of about 10 with three people on every cold email account and one main contact who talks to the client daily or on calls.", "better": "Yes. Three people work on your account, one on lists, one on writing, one on strategy, and one of them is your main contact. You will know their names and talk to them often. We keep the team small on purpose so nobody gets lost. Does that kind of closeness matter to you?", "call": "Andrew Milstead", "good": true, "q": "Will we have someone dedicated to us who works hand in hand with us?", "s": 926, "trick": "Name the roles, not just a number", "url": "https://fathom.video/calls/229583830"}, {"a": "Luke said the team builds the strategy, manages accounts daily, makes new creatives, and has two devs who fix small landing page issues, but major site rebuilds are quoted separately.", "better": "Not a dumb question at all. Yes, we make the ads, test new ones, and handle small landing page fixes like buttons and layout. A full rebuild would be quoted separately, and we would tell you before we start. Does your current site need big changes, or mostly tweaks?", "call": "Eric D Shepard", "good": true, "q": "Are you going to produce the ads and the landing pages too?", "s": 1715, "trick": "Say what is and is not included", "url": "https://fathom.video/calls/470388378"}, {"a": "Luke said about 10 people work together, each account manager handles about 6 to 10 clients, there is one main contact, and clients get weekly update videos.", "better": "Yes. You will have one main contact, and a team behind them, all in the US. Each manager has only about six to ten clients, so you get real time. Every week you get a short video of what we did and what we saw. Would you like to meet your team before you decide?", "call": "Garret Ashton", "good": true, "q": "Would we have our own support team?", "s": 2781, "trick": "Show the people, not a promise", "url": "https://fathom.video/calls/228223662"}, {"a": "Luke said the whole team is in house, and Brian said they set up the account, manage it daily and send weekly video updates.", "better": "Yes, everything is done by our own team of about ten, no outsourcing. You will meet the people on your account in the first week. They set up your ads, check them every day, and send you a short video each week. Want me to introduce you to them on a quick call?", "call": "Kyle", "good": true, "q": "Is everything handled in house by your team?", "s": 1436, "trick": "Put faces to the team", "url": "https://fathom.video/calls/263406837"}, {"a": "Luke said you cannot find one person to do it all, his team has three people on cold email with copy and Clay skills, and at least two people are needed to do it well.", "better": "That is the right worry, and it is why I do not rely on one person. Our email team has three people, one on copy, one on the tech side, and one on delivery. You would not be our test case, we have done this before. Would you like to meet them on the next call?", "call": "Joseph Gissy", "good": true, "q": "I need someone who has done cold email and has all the pieces from day one, who would that be?", "s": 2238, "trick": "Show the team behind the work", "url": "https://fathom.video/calls/230308235"}, {"a": "Luke said it is a good ratio because staff work full weeks, and he compared it to overseas agencies where one person has 60 or 70 clients.", "better": "Good question. Each person has about five or six accounts, and everyone is in the US full time. That gives real hours for your campaign each week. Cheap agencies stretch one person across 60 clients, which we never do. Want to see how a week of work looks?", "call": "Tony Small", "good": true, "q": "With 10 employees and about 55 clients, is there enough time for my campaign?", "s": 1790, "trick": "Compare to the cheap option", "url": "https://fathom.video/calls/246099180"}, {"a": "Luke offered a link to book a call with the wider team, said he or Luke would email it, and that he would likely meet Matthew.", "better": "Of course, you should meet them before you trust us with your money. I will send a link today so you can meet Matthew, who would help run your account, and I will join too. Come with your hardest questions. Is there a day this week that works for you?", "call": "Mohammed Sharifi", "good": true, "q": "Can I meet the team first so I know who we will be working with?", "s": 1672, "trick": "Welcome the team meeting", "url": "https://fathom.video/calls/323376725"}, {"a": "Luke said they mix both, building graphics and video edits in house when assets are weak and pulling in what the client has, and they also suggest what to shoot.", "better": "Both, depending on what you have. We look at your photos and videos first, keep what works, and build new graphics and video edits where needed. You will not have to be the designer. Would you want to send me a folder of your best content to start?", "call": "Mark", "good": true, "q": "Will you use our assets or make your own?", "s": 3683, "trick": "Make the next step easy", "url": "https://fathom.video/calls/226492580"}, {"a": "Luke said they have an in house designer, and video editing and tools are included.", "better": "Yes, we have a designer in house, so images and video edits are part of the work. You do not need to hire anyone else for that. If you have photos of the barrels, send them and we will build from there. Does that cover what you were worried about?", "call": "Larry Pomerantz", "good": true, "q": "Do you make the creatives for the ads too?", "s": 1953, "trick": "Answer plainly, remove a worry", "url": "https://fathom.video/calls/276740502"}, {"a": "Luke said they learn the business first, share the monthly plan and blogs before going live, and can use a Google sheet or weekly check in so Kay can approve or tweak.", "better": "That worry makes total sense, it is your name on the line. You would see every topic and every draft before it goes live, and you can say yes, no or change this. We start by learning your voice. Would a weekly look at the drafts feel right to you?", "call": "Kay Pollard", "good": true, "q": "Will you write my blogs, and can I be comfortable with others writing for my business and reputation?", "s": 153, "trick": "Echo their words first", "url": "https://fathom.video/calls/241212547"}, {"a": "He said the team is about 10, with an account manager as main contact, plus himself and the general manager on the onboarding call.", "better": "You will have one main person who knows your account inside out, and a small team behind them for ads, design and SEO. You will also meet our general manager on the onboarding call. Would you like to meet your account manager before you decide?", "call": "Leonard Emini", "good": true, "q": "Will we have one contact person, or several people on our project?", "s": 1297, "trick": "One face, a team behind", "url": "https://fathom.video/calls/271080025"}, {"a": "Luke said yes, ten people, but it is not that quick and nobody can do SEO in under four months.", "better": "Yes, I have a team of ten, all based in the US, so work moves steadily. But I will be honest, a bigger team does not make Google faster. It makes the work better and more complete. Would you like me to tell you who would work on your site?", "call": "Kevin Huang", "good": true, "q": "Do you have a team that can get results faster than other agencies?", "s": 1757, "trick": "Do not overpromise speed", "url": "https://fathom.video/calls/300079094"}, {"a": "Luke said there are 10 of them, they only do Google, Meta and SEO, and they have about 50 clients. He said they will meet the whole team.", "better": "I hear you, you want people who care, not a side hustle. This is all we do every day, with a team of 10 and about 50 clients, and you will meet the people working on your account. Would it help to talk with one of them before you decide?", "call": "Mcbride", "good": true, "q": "You better not treat this as a side project, are you really focused on this?", "s": 1340, "trick": "Echo their words first", "url": "https://fathom.video/calls/241078094"}, {"a": "Luke said they do not do shared account management, they work as a unit on the accounts themselves and require a three month commitment.", "better": "We run the account ourselves so results stay clean, but Renato will be in the loop all the time. He gets plans, reports and quick answers, even to the small questions. I want him to look like the leader to his client. Would that work?", "call": "Maria Costa", "good": true, "q": "Can you work as part of our team with Renato, sharing the account?", "s": 786, "trick": "Say no, then give the benefit", "url": "https://fathom.video/calls/253101615"}, {"a": "Luke said his manager Matthew in New York, who is a musician, would oversee the account and Mark can meet him any time.", "better": "That makes sense, sound matters here, you cannot sell a speaker without understanding it. Matthew, my manager in New York, is a trained musician and would lead your account. Would you like me to set up a short call with him this week?", "call": "Mark", "good": true, "q": "We want someone who knows our industry, who would work on our account?", "s": 3457, "trick": "Match a person to the need", "url": "https://fathom.video/calls/226492580"}, {"a": "Luke said they do everything, including designs and creatives in house, using the client's video and images if they have them, and then manage the campaigns.", "better": "Yes, we do all of it, from ideas to creative to running the ads. Since you already have lots of video, we would start with that and make new versions. You can be as hands on or hands off as you like. How involved do you want to be?", "call": "Dean Strober", "good": true, "q": "Do you create the ads yourselves and then place them?", "s": 577, "trick": "Offer a choice of involvement", "url": "https://fathom.video/calls/335111266"}, {"a": "Luke said they have only 50 to 55 clients and 10 employees in the US and Canada, so they can start right away.", "better": "We are a small team on purpose, about 50 clients and more staff than clients. That means your account gets real attention, and with your season it moves to the top of the list. Would you like to meet the person who would run it?", "call": "Larry Pomerantz", "good": true, "q": "How much time can you commit, since we are in a rush?", "s": 1759, "trick": "Turn size into a benefit", "url": "https://fathom.video/calls/276740502"}, {"a": "Luke said they have 12 people, all doing ads, and that one person cannot cover all the skills.", "better": "We're a team of 12, so you're never relying on one person. You get a manager, people who build the ads, and developers who fix your site if it's the problem. I'm the owner, and I'm on calls too. Who would you like to meet first?", "call": "After hours alcohol delivery prospect", "good": true, "q": "Do you have a team or do you just do it yourself?", "s": 573, "trick": "Show the team behind the work", "url": "https://fathom.video/calls/858246139"}, {"a": "Megan said three years, over 50 clients, and a team of 10 across Canada, the US and the UK.", "better": "We have been going three years with over 50 clients, and our team is about 10 people, small on purpose. You will know the people working on your account by name. Would you like to meet the person who would run yours?", "call": "Kristina Shumi", "good": true, "q": "How long have you been going and how big is your team?", "s": 1583, "trick": "Small team as a strength", "url": "https://fathom.video/calls/284134646"}, {"a": "Luke explained that a point person leads with a team behind them, then brought Matthew and Brian onto the call.", "better": "Of course, and I would want that too. I will pick the person who fits your account and set up a quick 15 minute call before you start. If you do not feel they get it, tell me and we change it. Would later today work?", "call": "Tony Small", "good": true, "q": "Who would be my point person, and can I meet them first?", "s": 1967, "trick": "Let them test the person", "url": "https://fathom.video/calls/246099180"}, {"a": "Luke said a manager named Matthew oversees it and usually about four people work on an account, including a web dev, designer and strategist.", "better": "Good question. You get a lead manager, Matthew, plus about four people, a strategist, a web developer for tracking, and a designer. You always have one person to talk to. Would you like to meet Matthew first?", "call": "Joyce", "good": true, "q": "How many people from your team of 10 would work on our account?", "s": 709, "trick": "Name real people", "url": "https://fathom.video/calls/470472685"}, {"a": "Luke said yes, the team is US based and works on East Coast time.", "better": "Yes, our team is mostly US based and works on East Coast time, so you can reach us in your working hours. You will also have one person who knows your account. Is working in your time zone important to you?", "call": "Eric D Shepard", "good": true, "q": "Are your people US based?", "s": 1745, "trick": "Short answer, then ask why", "url": "https://fathom.video/calls/458078657"}, {"a": "Brian said no, the team is based in the US with a couple in Canada, and they do not outsource.", "better": "No, and I understand why you ask after that experience. Our team of 10 is all in the US and Canada, and your account is run by people you can talk to. Want to meet them on an onboarding call?", "call": "Brian (mock call 1)", "good": true, "q": "Do you outsource work overseas like my old freelancer in India?", "s": 754, "trick": "Echo the fear, then reassure", "url": "https://fathom.video/calls/267787294"}, {"a": "Megan said it depends, some managers focus on one channel, but the client talks to one account manager.", "better": "You will have one main person you talk to, even if a specialist works behind the scenes on each channel. You never have to chase two people. Does that sound good?", "call": "Kristina Shumi", "good": true, "q": "Will I have different account managers for Google and Facebook?", "s": 1304, "trick": "Make it simple for them", "url": "https://fathom.video/calls/284134646"}, {"a": "Luke said they would send a payment link and onboarding form, then the manager reaches out, and the team checks the account daily for search terms and negatives.", "better": "Great questions. A US based manager and specialist work on your account every day, and you will get a monthly report of what they did. In the first month we fix tracking and wasted spend, then grow leads. I do not promise numbers, but I will show you the work. Want me to introduce you to the team?", "call": "Safa", "good": false, "q": "What results can you deliver, who will work on it and how much time do they spend?", "s": 1440, "trick": "Show the people and the work", "url": "https://fathom.video/calls/259170120"}, {"a": "Luke gave a long answer about a hybrid of AI and human editing, naming Jessica and Matthew, tools like Surfer SEO, and saying articles are not written fully by hand.", "better": "Great question. Two people on my team, Jessica and Matthew, own the content. AI helps with the first draft, then they rewrite it with your real facts and check it with SEO tools. You would also review topics, because you know executive search better than we do. Want to meet them before you decide?", "call": "Chris Savor", "good": false, "q": "Who writes the articles, since our topics are very specific?", "s": 1368, "trick": "Name the people, keep it short", "url": "https://fathom.video/calls/251114242"}, {"a": "Luke said a team of ten gives skills one or two hires cannot, that SEO alone needs three people, and told a long story about letting go of weaker team members.", "better": "Many keep a small internal person and use us for the hard parts. Doing SEO and ads well takes five or six skills, and hiring that would cost far more than what we charge. Your own team knows your furniture best, and we add the marketing skills. Would that kind of partnership work for you?", "call": "Joyce", "good": false, "q": "Do your clients use you exclusively so they do not need an internal team anymore?", "s": 2121, "trick": "Partner with their team, not replace", "url": "https://fathom.video/calls/322118977"}, {"a": "Daniel said it is a partnership and the team will flag what is not working, send metrics and optimize a scalable strategy so it is not only her job to ask for changes.", "better": "You do not need to know the answer, that is our job. Since this is your first time with ads, we will pick the audience, the offer and the first tests, and explain why in plain words. You tell us about the moms you want to reach, and we do the rest. Does that take some weight off?", "call": "Kristina Shumilova", "good": false, "q": "Do you help figure out the best strategy, or do I have to know what I want and have you set it up?", "s": 1426, "trick": "Lift the burden off them", "url": "https://fathom.video/calls/234074760"}, {"a": "Luke first said they do not come up with the content, then said they create it from scratch, with a designer, a brander, a video editor and in house writers.", "better": "Yes, we do both. We have designers, a video editor and writers in house, so we write the ideas, scripts and ads, and then make them. If you have real footage or product shots, we use those too. I can show you a brand like yours so you see it first hand. Want to see one?", "call": "Rehan Amir", "good": false, "q": "Do your creative strategy and video edits include concepts and scripts, and do you have in house creators?", "s": 1297, "trick": "Show a real example", "url": "https://fathom.video/calls/490898315"}, {"a": "Luke explained each client has one main contact, managers handle six to ten clients each, and the team works together, with Matthew as a lead.", "better": "Yes, you will have one main contact and the whole team behind them. Each person only handles about six to ten clients, so you get real attention. If you want to meet the team before you start, I can set that up. Who would you like to meet first?", "call": "Temisan", "good": false, "q": "Can I have a specific person from your team, like Jessica?", "s": 2363, "trick": "Offer to meet the team", "url": "https://fathom.video/calls/229608484"}], "tracking": [{"a": "Brian said they need Facebook access, will help set up Google Ads and Analytics, and just need a login to the site to set up and test purchase tracking with a discount code.", "better": "This is easier than most people think. Your developers only need to add us as a user on the site, and we do the rest. We set up Analytics and purchase tracking, then place a test order with a discount code and cancel it, so we know a real sale shows up in Facebook and Google. Who is the best person on your team to add us?", "call": "Dylan Taylor", "good": true, "q": "What will I need to hand my developers to set up tracking?", "s": 1597, "trick": "Make the task feel small", "url": "https://fathom.video/calls/273322525"}, {"a": "Luke said they would help, tracking leads and the typical close rate such as 6 closes per 50 leads, or a Google Sheet where the team logs sources, and AI could assist.", "better": "This is a problem for most clients and you are right to care. We would connect Tag Manager and GA4, and ask your team to log where each registration came from, at first in a simple sheet. With that we show real cost per registration, not just clicks. Who on your team could help us with the registration data?", "call": "Mike Worden", "good": true, "q": "How can you track cost per acquisition with our own registration platform?", "s": 1337, "trick": "Agree it is hard, then fix", "url": "https://fathom.video/calls/831260309"}, {"a": "Luke said tracking and GTM are included when they run Google Ads, they check the whole flow, and they do not take projects that are only tracking fixes.", "better": "Yes, I know how frustrating it is to run three platforms and only see clicks. We map the whole path from your site to the shop to the event page, then fix the tracking as part of the ad work. I'd want to see the flow first so I know what is breaking. Could you send me a login for the site to look at?", "call": "Tori Hudson", "good": true, "q": "Do you include setting up our GTM and tracking?", "s": 168, "trick": "Echo the pain then be specific", "url": "https://fathom.video/calls/562647779"}, {"a": "Luke said planning keeps traffic targeted, not all traffic is perfect, and they would present a simple plan he can adjust fast.", "better": "You are right, wrong leads would waste your time and money. We solve that by choosing words only big project clients use, blocking small project words, and running harder in your busy seasons. We would share the plan with you before anything goes live. Does that sound like the control you want?", "call": "Mohamed Mohaimen Hany", "good": true, "q": "Will ads bring me people looking for small villas I do not want, and how do we time it with the project seasons?", "s": 1414, "trick": "Show how we filter bad leads", "url": "https://fathom.video/calls/358358872"}, {"a": "Brian said purchases still usually show in Facebook, but UTM tags may not be tracked, and they would check that tracking is set up properly.", "better": "Good thing to ask. Ad blockers can hide some tags, but Facebook usually still sees the purchase. Your jump in orders may just not be counted right, and fixing that would also help your ads leave the learning phase. Would it help if we checked your setup first, before you decide anything?", "call": "Chris Bilyk", "good": true, "q": "Does an ad blocker or privacy setting stop our orders from being tracked?", "s": 1456, "trick": "Offer a free first check", "url": "https://fathom.video/calls/271182973"}, {"a": "Luke said that is an amateur mistake and they use Clixy style spam filters on Google so their accounts do not get spam, and he said a bad setup or landing page is usually the cause.", "better": "That is frustrating, and it is common when nobody sets up spam filters. We use a tool that blocks fake clicks and bots, and we check lead quality every week, not just lead count. Nothing is perfect, but we catch it fast. Can I look at last year's leads with you to see what went wrong?", "call": "Eric D Shepard", "good": true, "q": "We got a lot of spam leads on Google before, have you seen that, and can you stop it?", "s": 1158, "trick": "Be honest, then offer a look", "url": "https://fathom.video/calls/470388378"}, {"a": "Luke said some clients do it but they prefer data: where people land, what they click, why they leave, and gave an example of catching a glitchy shipping button.", "better": "We can use heat maps, but I trust numbers first. We watch where people land, what they click and where they drop off, and that caught a broken shipping button for one client. If your data points to a page problem, a heat map is a good second step. Do you use one today?", "call": "Mark H", "good": true, "q": "Do you use any programs for heat mapping?", "s": 1361, "trick": "Give a real story as proof", "url": "https://fathom.video/calls/524683610"}, {"a": "Luke said for products they link Shopify and track profit, but for services it is harder, so they ask the client to share booked jobs and track them in a Google sheet.", "better": "For service businesses we need your help, because we do not see your sales. If you tell us each week which jobs came in and what they were worth, we track it in a shared sheet. Then you see exactly what each dollar did. Would you be happy to share that once a week?", "call": "Garret Ashton", "good": true, "q": "Do you track what return a company gets on their spend?", "s": 3692, "trick": "Make the client a partner", "url": "https://fathom.video/calls/228223662"}, {"a": "Luke said they track everything with Google Analytics and Tag Manager and use a conversion API with Stape on Meta, watching drop offs, calls and form fills, and that all accounts belong to the client.", "better": "Yes, 100 percent, and you will own it all. We track clicks, calls, forms and where people drop off, and put it in simple words so you can see how many leads came in last week. If we ever part ways, every account stays yours. Would you like to see a sample report?", "call": "Eric D Shepard", "good": true, "q": "Are you going to track everything, and will we always have access to see our leads?", "s": 1594, "trick": "Show it, and say you own it", "url": "https://fathom.video/calls/470388378"}, {"a": "Luke said ROAS is the main thing, and for a high value service they track visits, drop offs and forms, then ask the client how good each lead was and what profit came from the deal.", "better": "Yes, profit is the only thing we care about. Your cycle is long, so we track the early signs too: visits, forms, and calls with the right people. Then you tell me which leads were good and we tune from there. Can we set up a simple sheet where you mark each lead?", "call": "Justin Mitchell", "good": true, "q": "Is the focus on ROAS and how will you measure it for a long B2B sales cycle?", "s": 3408, "trick": "Match the measure to their cycle", "url": "https://fathom.video/calls/464049834"}, {"a": "Luke said conversion is a booked sales call, they use Smartlead, and they track reply rate, positive reply rate (aim 20 to 40 percent of replies), booking rate and closes.", "better": "We follow it like a funnel: replies, then positive replies, then booked meetings, then closed deals. A good target is 20 to 40 percent of replies being positive. You will see these numbers every week, and I will ask you which meetings turn into real deals. Fair?", "call": "Gio", "good": true, "q": "How do you track conversions?", "s": 808, "trick": "Walk the funnel simply", "url": "https://fathom.video/calls/267686901"}, {"a": "Luke said they control Google, not the other way around, using tight ad groups, negatives and exact landing pages.", "better": "Possible, and we would check it first. If tracking is off, Google learns from the wrong clicks. We would look at your conversions and keep the corporate team building ads fully separate from the spice shop. Can I get your Google Ads ID so I can look?", "call": "Safa", "good": true, "q": "Could Google not understand our customer profile because of our tracking?", "s": 1026, "trick": "Take their idea seriously", "url": "https://fathom.video/calls/259170120"}, {"a": "Luke said they track clicks and sales with Google Analytics and Stape for Facebook, report profit on ad spend, and will explain it so simply a 10 year old can understand.", "better": "That is very common, and I am glad to help. We track every click and sale, and I will show him one simple page, how much you spent and how much you made. I can join a short call with him and keep it plain. Should I do that next week?", "call": "Ivona", "good": true, "q": "How do you track sales, and how can you explain it to a CEO who knows nothing about online?", "s": 1757, "trick": "Offer to meet the decision maker", "url": "https://fathom.video/calls/481051622"}, {"a": "Luke said yes, all of it, and that his two developers can change things with permission.", "better": "Yes, because ads only work if the page turns visitors into buyers. We watch where people leave and fix the page with your OK. That's often where the biggest wins are. Would you like us to check your page before we launch?", "call": "Dorian Fleuri", "good": true, "q": "So you also analyze how people react on the website?", "s": 2039, "trick": "Link the page to the sale", "url": "https://fathom.video/calls/564365833"}, {"a": "Luke said they track everything, but ROI for service businesses is harder to pin down than a store, so they rely on conversions and talking it through together.", "better": "Yes, and we set it up before spending a dollar. We would track membership sign ups, certification purchases and form fills, so every ad has a clear result next to it. For a group like yours, that is better than guessing. We will send you the numbers every week in plain words. Does tracking those three things cover what your board wants?", "call": "Chloe Puig", "good": false, "q": "Can you show ROI with traffic and sign ups, not only sales, since we are a service and membership group?", "s": 1696, "trick": "Name exact things to track", "url": "https://fathom.video/calls/264491733"}, {"a": "Luke said there are lots of ways but did not explain, and said the language barrier made it hard to talk about it.", "better": "Great thing to ask, tracking is how you know it is working. We set up Google Analytics and Search Console and watch three numbers each month: visitors, the keywords you rank for, and inquiries. I will send you a simple report so you can see it clearly. Would it be easier if I wrote that out in chat so you can translate it?", "call": "Kevin Huang", "good": false, "q": "How do we set KPIs and track the results?", "s": 1169, "trick": "Make it simple and offer chat", "url": "https://fathom.video/calls/300079094"}, {"a": "Luke said with projects this big he would run both, even at 1,500 dollars a month on competitor campaigns and highly relevant keywords.", "better": "I understand that worry, because paying for clicks that go nowhere feels bad. We set up tracking so you see every call and form that comes from an ad, and we aim at searches like hire an architect, not browsing. That way you pay for people who are ready. Can I show you how we track that for another client?", "call": "Mohamed Mohaimen Hany", "good": false, "q": "How do Google Ads clicks turn into real leads, and are those people really interested?", "s": 1193, "trick": "Answer the fear before the number", "url": "https://fathom.video/calls/358358872"}, {"a": "Luke said he does not share details, said there are tricks they keep private, and only that they use a server side pixel rather than a basic one.", "better": "Yes, it does help. The pixel teaches Facebook who your best people are, so costs usually fall over time. We use a stronger server side setup that tracks more accurately. I will walk you through how it works once we start. Want me to explain what it means for your profile visits?", "call": "Anyro", "good": false, "q": "Is it true the pixel helps reduce cost per click and cost per visit over time?", "s": 1426, "trick": "Educate, do not hide", "url": "https://fathom.video/calls/227623273"}, {"a": "Luke did not answer directly and said he would check with Luke about whether an audit or consulting could be offered.", "better": "That one is very fixable, and it matters because you cannot improve what you cannot see. We would check your tags, remove old codes, and connect HubSpot forms so every lead shows in one place. I can put together what that would take. Can you share Tag Manager view access?", "call": "Jessica Wagner", "good": false, "q": "Our conversion tracking is broken and HubSpot forms are not captured, can you fix it?", "s": 357, "trick": "Name the fix in plain words", "url": "https://fathom.video/calls/459408894"}, {"a": "Luke said yes but not exactly, and that they use SEMrush and Ahrefs to build a report as a first stage of working together.", "better": "Those tools give a good rough guide on click prices, but not what a sale really costs. Your own account data is the truth. I can build you a competitor report this week so you can see the range. Do you want me to start with your top three competitors?", "call": "Larry Pomerantz", "good": false, "q": "Can a tool like SEMrush tell us what competitors pay to get a customer?", "s": 951, "trick": "Be honest about limits, add value", "url": "https://fathom.video/calls/276740502"}, {"a": "Luke said paid ads are more detailed, and for SEO they see where visitors land, where they come from and which keyword, and can set up conversions.", "better": "Simple answer. For SEO we show which keywords moved up, how many visits they brought, and how many of those turned into form fills or calls. We set up that tracking in week one so nothing is a guess. Is a form fill the main thing you want to count?", "call": "Joseph Gaspero", "good": false, "q": "What are the basic building blocks you report on for SEO?", "s": 1520, "trick": "Plain list of three numbers", "url": "https://fathom.video/calls/247180673"}, {"a": "Luke said his team uses Ahrefs and offered to bring a tag in, but did not know where to find it in Google Tag Manager or Analytics.", "better": "Good question. The best place is Google Search Console, under Pages, and it shows indexed and not indexed pages. If you do not have it yet, I can have my tech set it up and we will see the real number together. Want me to do that this week?", "call": "Billy Chung", "good": false, "q": "Where do I look to see how many pages got indexed?", "s": 791, "trick": "Give one simple answer", "url": "https://fathom.video/calls/499402776"}, {"a": "Luke said if someone sees the ad ten times and buys from an email, it is hard to track to Google, and Razi agreed the ad still helped.", "better": "Good thinking. We set up tracking so you can see which ads bring clicks, sign ups and meetings, and we tag the job title where Google allows. Email sales still get credit as assisted by ads. Want us to map that path during setup?", "call": "Razi Hecker", "good": false, "q": "Can you track who is clicking and which clicks lead to sales when emails are part of the path?", "s": 1631, "trick": "Show we can solve the real issue", "url": "https://fathom.video/calls/507313039"}, {"a": "Luke said it should be fine to attach multiple accounts but did not seem sure, and said he would not worry about it.", "better": "Good question. In most cases you can connect several Instagram accounts to one business account. I want to check the best setup for many creators and will confirm by email. Would you send me how many accounts you plan to run?", "call": "Anyro", "good": false, "q": "Is it a problem to attach multiple Instagram accounts to the same Facebook account?", "s": 1614, "trick": "Say I will confirm, not guess", "url": "https://fathom.video/calls/227623273"}], "trust": [{"a": "Luke explained the company is 5 to 6 years old with 11 people in the US, 35 to 40 clients, specialists in each area, and that every account gets the same effort as clients spending a quarter million a month.", "better": "That is the right worry, and two agencies gave you a reason to feel that way. Here is how we avoid it: we are small, about 40 clients, and the whole team works on every account, not a junior. You can watch what we do week by week, and there is no 12 month contract, so we have to earn it. Can I show you how the weekly updates look?", "call": "Michael Cash", "good": true, "q": "At my small spend, will I really get focus and follow through?", "s": 743, "trick": "Echo their words first", "url": "https://fathom.video/calls/867124558"}, {"a": "Luke said they are not a typical agency, have just under 50 clients and a team of nine, do everything in house with no offshore work, and use month to month terms, and he said she is right to be cautious.", "better": "That makes sense, and you are right to be careful, because you have seen the inside. We have under 50 clients, everything is done by our own team, and you can leave any month. If we do not make you money, you will not stay, and we know that. What did you see in those agencies that worried you most?", "call": "Temisan", "good": true, "q": "I have worked with agencies and seen how they run behind the scenes, and that makes me nervous.", "s": 1835, "trick": "Echo their words first", "url": "https://fathom.video/calls/229608484"}, {"a": "Luke said they care about ad spend and budget, they fail sometimes too, have about a 90% success rate on Google and 75 to 80% on Facebook, and have many reviews.", "better": "I am sorry you had that experience, and I do not take it lightly. We tell you when to pause and when to push, you keep your ad accounts, and you see every number. I will not promise it always works, but I will tell you early if it is not. What would you want to see in the first month to feel safe?", "call": "Michelle Johns", "good": true, "q": "How do I know you will not gouge me like other marketing companies did?", "s": 530, "trick": "Acknowledge the hurt, show openness", "url": "https://fathom.video/calls/537594627"}, {"a": "Luke said there were no real struggles on the work, the problem was communication and Sean blocking them, and that he would not work with Sean again.", "better": "Good question, and I will be straight with you. The ads were not the problem, we did not get enough access or time to rebuild things the right way. This time you decide who has access and we agree on goals first. That way nobody is blocking the work. Does that sound like the setup you want?", "call": "Shabnam Akrami", "good": true, "q": "What were the struggles on the first site and how do we avoid them?", "s": 733, "trick": "Own it without blaming", "url": "https://fathom.video/calls/282988891"}, {"a": "Luke said they have 60 clients, a US team that does everything in house, only Google, Meta and email, and a 90 percent success rate. He said he cannot promise results and ROAS can range from 0.8 to 15x.", "better": "I hear you, paying for help and seeing nothing change is exhausting. I cannot promise results, nobody honest can, but I can promise you will meet the people doing the work and see what they do each month. Can I do a free look at your account first so you can judge us on facts?", "call": "Safa", "good": true, "q": "How are you different from everyone who has taken our money and nothing changed?", "s": 633, "trick": "Echo their words first", "url": "https://fathom.video/calls/259170120"}, {"a": "Luke said he can put Doug on with a client named Andy, but asked him to call only when he is 95 percent sure, and pointed to video testimonials first.", "better": "Yes, I would be glad to. I protect my clients' time, so I like to set it up once you are close, and I will make sure it is a client who looks a lot like you. Until then, here are a few video reviews you can watch today. When would be a good time to connect you?", "call": "Doug Fiore", "good": true, "q": "Can I speak with a similar client of yours?", "s": 3294, "trick": "Say yes, then protect the timing", "url": "https://fathom.video/calls/242167771"}, {"a": "Brian said they do homework, present a plan, and ask her to flag any wrong terms, and Luke said they spend hours on plans and hold live calls at the start.", "better": "That is a real worry, and I am glad you said it. Before anything goes live, you will see every ad and word we plan to use. If something is off, you catch it. We would rather get it right than fast. Is it okay if we send you a word list to check first?", "call": "Lindsey Carter", "good": true, "q": "Will you get the very specific terms in my industry right, since fans get upset if it is not accurate?", "s": 1399, "trick": "Let them approve before launch", "url": "https://fathom.video/calls/262584763"}, {"a": "Luke said they do not own accounts and would transfer them any time, they would build the emails in Squarespace or Klaviyo, and she could be added to the list.", "better": "Your list is yours, always. We move it into a proper email tool, but you can see it any time and take it with you if you leave. We will never hold anything hostage, and it is written in the contract. Would you like to read that part first?", "call": "Erin Rosenstock", "good": true, "q": "What happens to my email list, will I still see it, and do you own it?", "s": 1971, "trick": "Put the promise in writing", "url": "https://fathom.video/calls/262474173"}, {"a": "Luke said the ads stay in his account, the contract says they never hijack or hold accounts hostage, and they are transparent.", "better": "Great question, and you should ask it. Your ads, your history and your data always live in your own account, and the contract says so in writing. If we ever part ways, you keep everything. Want me to point you to that line in the contract?", "call": "Marius Negru", "good": true, "q": "You are not going to move the ads away from my account, are you?", "s": 664, "trick": "Praise the question, show proof", "url": "https://fathom.video/calls/525995385"}, {"a": "Luke said it is not a problem, they can clone the account, request ownership from the old agency, and keep a backup so the client owns it.", "better": "I am glad you noticed that, it happens a lot. We would ask the old agency for access first, and also back up and copy the account so you keep your data. You will own the final account, not us. Do you know who set it up originally?", "call": "Jennifer Metcalf", "good": true, "q": "Our Google Ads account was not created by us. What happens to it?", "s": 1390, "trick": "Calm the worry, show the plan", "url": "https://fathom.video/calls/247960459"}, {"a": "Luke said about four years under ReachGiant with 45 to 50 clients, after an earlier web only company called Rework.", "better": "About four years as ReachGiant, and before that we ran a web design company. That is why we are strong on sites as well as ads. We have around 50 clients and most stay a long time. I am happy to connect you with one if that helps.", "call": "Rehan Amir", "good": true, "q": "How long have you guys been in this space?", "s": 1998, "trick": "Turn history into a strength", "url": "https://fathom.video/calls/490898315"}, {"a": "Luke said yes, they own none of the client's property, and clients can leave and keep everything.", "better": "Yes, everything is yours, the ad account, the pixel and the data. We never lock anything. If you leave, you take it all with you. We want you to stay because it works, not because you are trapped. Does that put you at ease?", "call": "Anyro", "good": true, "q": "Will the Facebook account and pixel belong to us?", "s": 1214, "trick": "Remove the lock in fear", "url": "https://fathom.video/calls/227623273"}, {"a": "Luke said they have solid reviews, he owns the company and does all sales calls, his US and Canada team cares, and clients value communication, quality and results.", "better": "That means a lot, and trust is what I care about most too. I do every sales call and talk to my clients myself, so you will always know who to reach. Would it help to talk to a couple of clients in your kind of business?", "call": "Stefan Gutowski", "good": true, "q": "Can we trust you? I need someone my company can work with long term.", "s": 1094, "trick": "Offer proof, not just words", "url": "https://fathom.video/calls/293071198"}, {"a": "Luke said around four years, with about 50 clients and 10 employees, and mentioned big clients like Porsche, Nescafe and Whole Foods.", "better": "About four years, with around 50 clients, and most of them are small and mid size, like you. We are small enough that you will know your team by name. I can connect you with a similar client if you like.", "call": "Matt Holdridge", "good": true, "q": "How long have you guys been in business?", "s": 642, "trick": "Make small a plus", "url": "https://fathom.video/calls/469763535"}, {"a": "Brian said three years, and that they grew pretty quickly.", "better": "We started three years ago and now work with about 50 clients. We grew because clients stay when they see results. Is there anything else you would want to check about us?", "call": "Brian (mock call 1)", "good": true, "q": "How long have you guys been in business?", "s": 712, "trick": "Short fact, then proof", "url": "https://fathom.video/calls/267787294"}, {"a": "Luke said it can happen, that Facebook can flop, that SEO is safer, and that they test about 160 things quickly and Facebook works about 80 percent of the time.", "better": "I am sorry that happened, that is a real problem in this business. We would agree up front on what a real lead is, a seller who wants to list in the next few months, and we would show you the numbers for that only. If it is not working, we will tell you early. Would you like to define that lead together on our first call?", "call": "John Cho", "good": false, "q": "I had a marketer who called home value requests seller leads. How do I know you will be honest about results?", "s": 2042, "trick": "Define a real lead together", "url": "https://fathom.video/calls/320715151"}, {"a": "Luke said he started the company about three years ago from a photography background, has 60 clients and a million in revenue, and wins on communication, results and perfect reviews. He also mentioned firing at least 50 percent of the people he hired.", "better": "Fair question, I would ask the same with that many pitches a week. Most agencies promise big and go quiet, so we keep our client list small, about 60, and the same US team does the work and talks to you. Can I ask what went wrong with the last vendors you tried, so I can tell you honestly if we are any different?", "call": "Alan Kadish", "good": false, "q": "What makes you different from the ten or more marketing groups that approach me every week?", "s": 175, "trick": "Honor the doubt, then differentiate", "url": "https://fathom.video/calls/261509501"}, {"a": "Luke said they only do Google, manage accounts daily, work to lower cost per click and cost per sale, and never promise results or ROAS.", "better": "That is the right thing to worry about, and it sounds like you have been burned before. I will not promise numbers, but I can tell you we start by working out what a sale is worth to you and the most you can pay to get one. Then we watch it daily against that line. What went wrong with your last manager?", "call": "Brian Rose", "good": false, "q": "I have had several Google Ads managers. How do I know the cost per sale will stay below my revenue?", "s": 1284, "trick": "Echo their pain, then ask", "url": "https://fathom.video/calls/288749754"}, {"a": "Luke pointed to work for Porsche and Spotify and said they only do Google and Meta, so that is why they are good.", "better": "I am sorry that happened, it is frustrating when a salesperson sells something the team cannot deliver. We only do Google and Meta, and I will tell you straight what we do not do, like CRM. You can also leave any time, so we have to earn it. What would you need to see in the first month to feel safe?", "call": "Cesar Diaz", "good": false, "q": "Past agencies over promised, why should I trust you?", "s": 928, "trick": "Say what you do not do", "url": "https://fathom.video/calls/860109475"}, {"a": "Luke said no to splitting payment and pointed to hundreds of reviews, Google, a Fiverr agency account with 125 stars and Upwork expert vetted status.", "better": "That makes sense, trusting a new team with money is a real step. I cannot split the first month because the setup work happens right away, but you can cancel any time and keep your account. Look us up on Google and I will send you reviews and a client to talk to. Would that help you feel safe?", "call": "Marius Negru", "good": false, "q": "Can I pay half now and half in two weeks? I do not know you and you do not know me.", "s": 1413, "trick": "Validate the fear, offer proof", "url": "https://fathom.video/calls/525995385"}, {"a": "Luke pointed to the Fiverr profile, ChatGPT, and past clients like Porsche, Spotify and Bulgari, and said people who work for free get cheap results.", "better": "You're right to want proof, nobody should trust a stranger with 6K a month. Let me show you real results from clients like you, and I'll share two reviews you can check yourself. You also keep full ownership of your account at all times. Can I send you the case studies today?", "call": "After hours alcohol delivery prospect", "good": false, "q": "We just met on Fiverr, so we have to build trust. Let me see how it works first.", "s": 870, "trick": "Agree then offer real proof", "url": "https://fathom.video/calls/858246139"}, {"a": "Luke said they answer emails within 24 hours, you can be as involved as you want, and the team treats clients like family and can only keep them if they impress them.", "better": "That sounds exhausting, and I am sorry. Here is our promise: one email and you get attention, usually the same day, and you get a person who knows your account by name. We would rather lose a lead than leave you guessing. What would good communication look like for you?", "call": "Eric D Shepard", "good": false, "q": "Our agency is passive and hard to reach, how will you be different?", "s": 1350, "trick": "Echo their words first", "url": "https://fathom.video/calls/458078657"}, {"a": "Brian said he did not want to criticise others and named three things: results, quality and communication.", "better": "I am sorry those did not work out, that is frustrating. The difference is we show you everything each week in a short video, a real person answers within a day, and you own every account. Judge us by that, not by what I say. What went wrong most with the last agencies?", "call": "Brian (mock call 1)", "good": false, "q": "Why are you the right agency, and different from the other agencies I used?", "s": 1594, "trick": "Ask what went wrong", "url": "https://fathom.video/calls/267787294"}, {"a": "Luke said it was a fair concern with nothing he could say, told them to check reviews, said not every campaign works, and said they try to keep clients long term.", "better": "That is a fair worry, and I am sorry she went through that. I would not ask her to trust me on words. You can read our reviews, speak to a client, own your accounts, and we start with a clear three month plan. Would a short call with her help? I will answer anything.", "call": "Matt Holdridge", "good": false, "q": "My wife was burned by a firm before, how can she trust you will not pick her pocket?", "s": 2240, "trick": "Feel the fear, then prove it", "url": "https://fathom.video/calls/469763535"}, {"a": "Luke asked him to share his current results and screen, and did not give a direct reason to choose ReachGiant.", "better": "Fair question, you have already put real money into this brand. I do not know yet if I am better, and I will not pretend. Show me your numbers and I will tell you honestly if I see something you are missing, or if you should stay put. Can you send those over?", "call": "Alex Szilagyi", "good": false, "q": "Why should I choose you instead of continuing the way I am doing it now?", "s": 979, "trick": "Honest curiosity builds trust", "url": "https://fathom.video/calls/240152980"}, {"a": "Luke said they had a similar client before and dropped them after two weeks, and that they have a security person who investigates, plus experience with hard verifications.", "better": "That is a smart worry. We check every new business first and follow Google's rules closely, so you are protected too. I would look at the website, the offer and your keywords before saying yes. Would you be okay sharing the business details so we can check?", "call": "Maria Costa", "good": false, "q": "How do you avoid problems with call centers in India and trademark keywords, so we are not seen as scammers?", "s": 574, "trick": "Calm, honest, no oversell", "url": "https://fathom.video/calls/253101615"}, {"a": "Luke said they can share testimonials but do not share live accounts.", "better": "I can send you testimonials right away. We keep client accounts private, but once you are close to a yes, I can show you a live account in a different industry on a quick call. Does that work for you and the person who reviews things with you?", "call": "Brian Rose", "good": false, "q": "Can you share samples of similar accounts you manage?", "s": 2269, "trick": "Give proof on a clear path", "url": "https://fathom.video/calls/288749754"}, {"a": "Luke said no, they do not own or hold anything hostage, though cold email uses several tools and sometimes they take over client accounts. His answer was long and went around the point.", "better": "Good question. You own your accounts, your domains and your data, and we never hold anything hostage. Some tools we run under our setup so it is fast, but if you ever leave we hand it all over. Does that cover what you were worried about?", "call": "Andrew Silagy", "good": false, "q": "Do you register the software on our behalf, or do you own everything?", "s": 720, "trick": "Short clear answer first", "url": "https://fathom.video/calls/341420869"}, {"a": "Brian apologized, said trust builds over time, and promised good results, regular updates and dedicated work.", "better": "That is not fun, and you are right to be careful. I will not ask you to trust me today. I would rather prove it, with weekly updates, no contract and full ownership of your accounts. What would help you feel safe starting?", "call": "Brian (mock call 1)", "good": false, "q": "I have been burned by agencies before. Why are you different?", "s": 1665, "trick": "Earn trust, do not ask for it", "url": "https://fathom.video/calls/267787294"}, {"a": "Luke said they have tons of reviews and video testimonials she can watch.", "better": "Yes, we have lots of video reviews from real clients, and I will send you the link today. If you like, I can also ask one or two fashion or ecommerce clients if they will chat with you. Would that help you feel sure?", "call": "Temisan", "good": false, "q": "Do you have testimonials?", "s": 1875, "trick": "Offer a real person to talk to", "url": "https://fathom.video/calls/229608484"}, {"a": "Luke said they are small enough not to pass work to juniors and that the team works together.", "better": "That is a real worry, and I am glad you said it. We are ten people in the US, and no one is a junior hidden behind me. You will meet the person on your account before you start. Would it help if we did that today?", "call": "Tony Small", "good": false, "q": "Is an agency not fully invested, and does my work get passed to a junior person?", "s": 292, "trick": "Name fear, offer to meet", "url": "https://fathom.video/calls/246099180"}, {"a": "Luke said they have hundreds of reviews and video reviews and have worked for Porsche, Whole Foods and Nescafe, and that they do not need to prove themselves.", "better": "Of course, you should check. I can send video reviews and put you in touch with a client who sells products like yours. We would love for you to feel sure. Which would help most?", "call": "Joyce", "good": false, "q": "Do you have successful clients we can use as a reference?", "s": 980, "trick": "Welcome the check", "url": "https://fathom.video/calls/470472685"}], "web": [{"a": "Luke said cold email could probably start right away, but the site is basic and does not look very professional, so at least a light refresh would help leads trust Doug.", "better": "Great question, and honestly you could start cold email first. Here is the catch. If we send you a 50K prospect and they land on a site that feels thin, they may bounce and never tell you. So I would do a light refresh at the same time, so both are ready together. Does that sound like a fair way to protect the leads we bring you?", "call": "Doug Fiore", "good": true, "q": "Does the website need to be reworked before we start cold email, or can we just do cold email first?", "s": 1103, "trick": "Honest answer plus a clear reason", "url": "https://fathom.video/calls/242167771"}, {"a": "Luke said that is the funnel, and they would make light changes like duplicating pages and removing clutter, or build new funnels if needed.", "better": "That worry is the right one, because ads only work if the page does its job. We send each type of search to a page that matches it, keep the page simple, and point people to book a call. If it needs more, we would build it, and I would tell you before we spend a dollar. Can I look at the page together with you?", "call": "Shabnam Akrami", "good": true, "q": "What if the ads bring people to my site and the content does not turn them into calls?", "s": 1524, "trick": "Name the fear, then fix it", "url": "https://fathom.video/calls/282988891"}, {"a": "Brian said small fixes like clickable phone numbers or moving text are done by the account manager, but bigger landing page work would be a separate charge.", "better": "Small fixes, like moving text up or making the call to action clearer, we do as part of your plan and you approve them first. A full rebuild would cost extra and I would tell you before any work. Your page is long, so I would start by moving the booking options higher. Want us to check that first?", "call": "Chris Bilyk", "good": true, "q": "If there are problems with the retreat landing page, who would fix them?", "s": 2673, "trick": "Say what is included and extra", "url": "https://fathom.video/calls/271182973"}, {"a": "Luke said they do branding and design everything from scratch, and showed a brand guideline example.", "better": "Yes, and from what you said, I think that is the right place to start. We build the brand first with mood boards and a guideline, then your emails and site follow it. Once the system is set, each email is just new text and a new link. Want me to show you how that looks for another family business?", "call": "Jade Pyne", "good": true, "q": "Is there a part of your company that can set up our brand first, and then we start email?", "s": 894, "trick": "Reframe to the real root problem", "url": "https://fathom.video/calls/242102912"}, {"a": "Luke said there is no cost difference between platforms, a base site starts at 4,500, but a light refresh on the current site would be about 3,000 and take around three weeks.", "better": "We can build on any platform, so there is no price difference. If Wix works for you today, keep it. A full new site starts at 4,500, but a light refresh of what you have is closer to 3,000 and takes about three weeks. That gets you ready for cold email without a big project. Does that feel right?", "call": "Doug Fiore", "good": true, "q": "Would moving my site from Wix to Squarespace cost more, and what would a light refresh cost?", "s": 3399, "trick": "Offer the smaller option first", "url": "https://fathom.video/calls/242167771"}, {"a": "Luke said Shopify is the best platform for sales, a bit more expensive than WooCommerce, they build in it all the time, and linking feeds and a blog is a piece of cake.", "better": "Yes, Shopify is what I would pick, because you want to sell print on demand items and it makes that smooth. It costs a bit more than cheaper options, but it saves headaches later. It can show your Instagram, YouTube and a blog on one home page. Want me to include a price for that in your plan?", "call": "Brett Hines", "good": true, "q": "Do you want a Shopify website, and can it link Instagram and YouTube?", "s": 3946, "trick": "Explain why, admit the cost", "url": "https://fathom.video/calls/293124897"}, {"a": "Brian said yes, they will pass on any website issues and suggestions because the ads send people to the site, and Luke added that they charge separately for Google Ads and SEO.", "better": "Yes, always. Your site is where the ad money turns into members, so if I see something that hurts it, I will tell you straight away and show you how to fix it. That is also how Chloe will learn along the way. Would you like me to take a quick look at your site before we start?", "call": "Chloe Puig", "good": true, "q": "Will you tell us if you see problems on our website that hurt the ads?", "s": 958, "trick": "Teach them as you go", "url": "https://fathom.video/calls/264491733"}, {"a": "Luke said it differs by client, they do not take the photos, but they turn her images and videos into ads with their in house designer.", "better": "You give us your photos and any video, and our designer turns them into ads. We do not shoot the photos, but we will tell you what shots would help. You said your clicks were high before, so we will build on what worked for you. What do you have ready for the new collection?", "call": "Temisan", "good": true, "q": "Where do the creatives come from, will they be made from what I give you?", "s": 1254, "trick": "Credit what already worked", "url": "https://fathom.video/calls/229608484"}, {"a": "Luke said the $2,400 is SEO, not the website design, that his sites start at $10,000, and he could do a very simple one page site for about $1,500 to $2,000 if the scope is clear.", "better": "Good catch, I should have been clearer. The $2,400 is SEO only. Our full websites start at $10,000, but for what you need, a simple one page site, I can do it for about $2,000 if we agree on the scope first. Would a simple page with your video and reviews be enough to start?", "call": "John Cho", "good": true, "q": "I thought the $2,400 was for the website. Is it?", "s": 2630, "trick": "Own the confusion, then simplify", "url": "https://fathom.video/calls/320715151"}, {"a": "Luke said for a high value 10k project, send people to the real website because it builds trust, and sometimes use a simplified copy of a page.", "better": "Great question. For a service that costs thousands, people want to trust you before they call, and your site does that well. I would send them to a focused page on your site, a copy with fewer distractions. We can test a landing page later if the data says so. Sound good?", "call": "Kyle", "good": true, "q": "Should I send ad traffic to my new website or to a separate landing page?", "s": 1620, "trick": "Explain with the buyer's view", "url": "https://fathom.video/calls/263406837"}, {"a": "Luke said any Google package includes small landing page fixes like nav bars and buttons, but full redesigns are a separate branding and web design service that he would quote.", "better": "Yes, in two ways. Small fixes, like a broken button or a bad layout on desktop, are part of your monthly work. A full redesign is a separate project and I would quote it clearly first. Since your desktop homepage is off, should we start with the quick fixes?", "call": "Rehan Amir", "good": true, "q": "Do you do site customization or landing pages, and which package covers that?", "s": 1698, "trick": "Tie the answer to their problem", "url": "https://fathom.video/calls/490898315"}, {"a": "Luke said no, it will help visually and a little for SEO, but a new site is not what will bring leads, so SEO work is needed.", "better": "I will not oversell you. A new site will look better and load faster, but a pretty site does not bring people in by itself. Traffic comes from SEO and ads. So the plan is a clean new site first, then keywords that bring in bookings. Does that make sense?", "call": "Colin Hornbaker", "good": true, "q": "Will switching my website off Wix actually help me get leads?", "s": 237, "trick": "Honest no, then a plan", "url": "https://fathom.video/calls/231727969"}, {"a": "Luke said small tweaks like adding a call to action, hyperlinks or a duplicated landing page are included on the larger plan, but a full redesign would be quoted separately.", "better": "Yes, small fixes are covered, like adding a call button, linking your phone and email, and building an ad landing page. A full redesign would be a separate quote and I would tell you before we start. Want me to make a short list of the quick fixes I see?", "call": "Garret Ashton", "good": true, "q": "Do you fix small website things like the call to action inside the package?", "s": 2354, "trick": "Draw a clear line on scope", "url": "https://fathom.video/calls/228223662"}, {"a": "Luke said they either advise what to change or do it themselves, and that where the ad lands is critical for advertising.", "better": "Yes, and it is a big deal, because ads only work if the page convinces people. I would look at your product pages and try ideas like a 20 minute free play before signup. We can tell you what to change or build it for you. Which would you prefer?", "call": "Lasse Jensen", "good": true, "q": "Can you advise on our landing and product pages so more people subscribe?", "s": 774, "trick": "Spot their idea and build on it", "url": "https://fathom.video/calls/240196889"}, {"a": "Luke said they have a lot of Shopify clients and some BigCommerce, with clients on almost every platform.", "better": "Yes, we work in BigCommerce and Shopify and most platforms, so your store is not a problem. What matters more is that your product feed in Merchant Center is clean, since you have many sizes and options. Would you like us to check that first?", "call": "Mark H", "good": true, "q": "Do you deal with any customers that have websites on BigCommerce?", "s": 1185, "trick": "Answer, then add a useful insight", "url": "https://fathom.video/calls/524683610"}, {"a": "Luke said they review the site for free and tell the client what to fix, and the client can fix it themselves, hire someone or get a quote from them, with simple page duplication for ads free.", "better": "We look at your site for free and give you an honest list. Small things like call buttons or a copied landing page, we do for no charge. A big redesign is a separate quote and your choice. Want us to review it before you decide anything?", "call": "Stephanie Webb", "good": true, "q": "Would you look at our website and tell us what to change, or do we pay you to change it?", "s": 2449, "trick": "Offer a free first look", "url": "https://fathom.video/calls/227326702"}, {"a": "Luke said it is nice and stylish, they can design it with an in house designer, build it pixel for pixel if he loves it, and redo it if he does not.", "better": "I like your ideas, they feel clean and match your drone work. We can build your concept exactly, or improve it with the design team. If you do not love it, we redo it until you do. Want to see the first draft before you decide on more?", "call": "Colin Hornbaker", "good": true, "q": "Do you like my website concepts, and would you design it?", "s": 467, "trick": "Praise, then lower the risk", "url": "https://fathom.video/calls/231727969"}, {"a": "Luke said yes, they have an in house design team and can build simple landing pages, though they would first see what campaigns are needed.", "better": "Yes, we can. Your site is lovely, so we may only need a simple page that makes it easy to say hello. We would check how your site does first and only build what helps. Does your site get many visitors that turn into inquiries now?", "call": "Leah Vogt", "good": true, "q": "Can you set up landing pages for the ads?", "s": 263, "trick": "Check what exists before selling more", "url": "https://fathom.video/calls/347069031"}, {"a": "Brian said they would be hands on with the survey, but the landing page would be a separate fee and they could guide his own developer.", "better": "Yes to both, with a clear split. We help shape the survey with you, and for landing pages we can build them for an added fee or guide your developer. Either way we make sure the pages match the ads. Which way would you like to go?", "call": "Carolina", "good": true, "q": "Will you help build the survey and the landing pages?", "s": 1666, "trick": "Offer two clear options", "url": "https://fathom.video/calls/274394195"}, {"a": "Luke said yes, they do landing pages and funnels if needed, but she should not overthink it; a simple ad, a good landing page and a call is enough.", "better": "Yes, we do, but you may not need a big one. You already close well on the phone, so we just need a simple page that gets people to call you. We keep it honest and not salesy. Want me to show you what I would change on your page?", "call": "Michelle Johns", "good": true, "q": "Do you build funnels?", "s": 298, "trick": "Keep it simple, match their style", "url": "https://fathom.video/calls/537594627"}, {"a": "Luke said it isn't essential for a high price product, but Shopify is definitely better, and offered a quote to migrate.", "better": "Not required, but I'd do it. Shopify gives you better tracking and better shopping ads, which matters when each sale is 3,000 dollars. Since you need to launch in 3 weeks, we can do it fast. Want me to price the move this week?", "call": "Dorian Fleuri", "good": true, "q": "Is it necessary to move my site from Wix to Shopify on your side?", "s": 1065, "trick": "Give an honest pick with a reason", "url": "https://fathom.video/calls/564365833"}, {"a": "Luke said pricing starts around $20,000, a small project like hers would be around $25,000 to $30,000, and they have two full time branders.", "better": "Branding starts near $20,000, and for you I would expect $25,000 to $30,000. I would not rush it, since your ads can start first. Your team could also build it and we guide them on what converts. Which way fits your plan?", "call": "Ivona", "good": true, "q": "What does the whole branding and website package cost?", "s": 988, "trick": "Give options, not pressure", "url": "https://fathom.video/calls/481051622"}, {"a": "Megan said a consultation with Luke is about $1,000, and that they would need website access anyway to set up tracking.", "better": "Good thinking. When we set up your ads, we look at your website anyway, so we will tell you what to fix. If you want a deep review, Luke's consultation is $1,000. Want to send me the link so I take a quick look first?", "call": "Kristina Shumi", "good": true, "q": "Can your team review my website, and would that be the $1,000 consultation?", "s": 1541, "trick": "Free look before the paid one", "url": "https://fathom.video/calls/284134646"}, {"a": "Luke said no, the website can be a funnel, and they can send traffic to the site or to a funnel page. He said keep it simple and do whatever works.", "better": "No need to rebuild anything first. Your current site can work, and we will test it. If we see people drop off, we will tell you exactly what to change, or we can fix it for you. Start simple.", "call": "Mcbride", "good": true, "q": "Do I need different funnel pages before we start Meta ads?", "s": 1219, "trick": "Remove the fear of extra work", "url": "https://fathom.video/calls/241078094"}, {"a": "Luke said that works if he has a designer, because design matters more than code, and Luke can send a video of what to change or quote the design.", "better": "Yes, that can work well, and it saves you money. The key is a good designer, not just a coder. I can record a short video showing what to change and why. Want me to do that?", "call": "Amy N Neighbors", "good": true, "q": "Can my brother, who builds websites, do the website changes you suggest?", "s": 2529, "trick": "Support their own plan", "url": "https://fathom.video/calls/485151651"}, {"a": "Luke said yes or he could put Greg in touch with someone, adding that it might be a little more expensive depending on budget.", "better": "Yes, we can do a redesign, and your site is a good example of why: too much text hides the one thing you want people to do. I would cut it down to one clear message and one button. I would want to see your budget first so I can be straight about whether we fit. Can I send you a short list of what I would change?", "call": "Greg Laskody", "good": false, "q": "If I decide to finish HOT, could you help me with the web redesign?", "s": 2910, "trick": "Show one quick insight to earn trust", "url": "https://fathom.video/calls/804786478"}, {"a": "Luke gave a long talk saying branding matters as much as ads and that he would not market the current website, because it explains nothing.", "better": "I like the idea, and honestly the ads are the easy part. We can find buyers. The bigger risk is that your site doesn't explain the value in five seconds, so I would fix that first. Then we start small on Meta and see what sticks. Can I look at your screenshots next week and tell you exactly what I'd change?", "call": "Pete Patrino", "good": false, "q": "Can you give us your high level reaction on how this might go?", "s": 969, "trick": "One clear insight, then next step", "url": "https://fathom.video/calls/849585251"}, {"a": "Luke said yes, they design and build websites.", "better": "Yes, we design and build sites, and we build them to turn visitors into leads. A small site that links to your auction page is possible, but our builds start at $10,000, so I want to be upfront. What would you want the site to do first?", "call": "Yesset Karayev", "good": false, "q": "Do you specialize in creating websites?", "s": 1507, "trick": "Say price early", "url": "https://fathom.video/calls/455546501"}, {"a": "Luke said they can give a quote and website pricing is custom depending on what is wanted.", "better": "Websites are priced on their own, because every site is different. Since you do not need one right now, we can leave it for later and focus on ads and email first. When you are ready, I will give you a quote. Is that okay for now?", "call": "Joseph Gissy", "good": false, "q": "Is website design included in anything, or is that separate?", "s": 2400, "trick": "Park it, keep focus on the goal", "url": "https://fathom.video/calls/230308235"}, {"a": "Luke said they can, but it is not in the price, and gave about $500 per landing page, sometimes duplicating a page for free.", "better": "Yes we can. A landing page is about $500 each, separate from ad management. Often we start by testing your own page for free and only build a new one if the data says it helps. Would you like us to test first?", "call": "Tony Small", "good": false, "q": "Could you also build a landing page, and how much would that be?", "s": 1098, "trick": "Offer the cheaper test first", "url": "https://fathom.video/calls/246099180"}, {"a": "Luke said they mostly end at communication but can build landing pages, and the answer wandered into how cold email works.", "better": "We can do either. Most clients use their own booking page, and if you want a fresh landing page we can build one. Which would you rather do, use your current page or have us improve it?", "call": "Gio", "good": false, "q": "Would you also build the landing page and booking, or do you just hand over the replies?", "s": 870, "trick": "Offer two clear options", "url": "https://fathom.video/calls/267686901"}]}}$json$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();

insert into growth_settings (key, value) values ('qa_extra', $json${"asked": 588, "calls": 108, "tricks": [{"b": "Cesar, Sam and Mathieu all moved when the discount came with a reason (small budget) and a deadline (today). It worked every time it was tied to a yes.", "t": "Drop the price with a reason and a deadline"}, {"b": "The 10 day exit calmed Michael, Mike and Marius. Say it early, in one sentence.", "t": "Say the exit before they ask"}, {"b": "Saying no to cold email, CRM and one off audits built trust. People believe the yes more after a clean no.", "t": "Be honest about what you cannot do"}, {"b": "12 people, about 50 clients, Matthew in New York, Mango Vans, Konzu. Specific beats vague.", "t": "Use real numbers and real names"}, {"b": "Telling Michelle about a 90% Google and 75 to 80% Meta success rate made the claim believable.", "t": "Admit the failure rate"}, {"b": "With Amy, saying stop the bleeding now, even if it meant not hiring you first, showed you were on her side.", "t": "Tell them to stop the bleeding"}, {"b": "No guarantee, but daily work and honesty. You keep clients only by making them money.", "t": "Turn guarantees into a promise you can keep"}, {"b": "Payment link, 15 minute form, call with Matthew. Number the steps.", "t": "Make the next step small"}, {"b": "Passing a question to Matthew shows a real team. Do it on purpose, not only when you do not know.", "t": "Bring in the team"}, {"b": "Then work backwards to budget. It makes your number feel logical instead of random.", "t": "Ask what a customer is worth"}], "weak": [{"fix": "Pick one clear rule: $1,500 up to $15,000, about 10% above, and say it the same way every time.", "q": "Fee structure above $15,000 ad spend", "why": "Quoted a spend based fee and changed the numbers mid call (Mark H)."}, {"fix": "Settle one list. The Pricing tab shows Meta $2,000, SEO $2,500 and vault $3,000.", "q": "Meta, SEO and vault prices", "why": "Meta was quoted at $1,800 and $2,000, SEO at $2,400 and $2,500, the vault at $2,500, $2,800 and $3,000."}, {"fix": "Say that cost per click rises with demand, and Matthew builds that into the plan.", "q": "Seasonality and cost per click", "why": "Did not know and passed to Matthew (Darren Lebel)."}, {"fix": "Use one line: no guarantees, daily work, and we only keep clients that make money.", "q": "Guaranteed return or break even", "why": "Hedged without a clear line (Dorian Fleuri, Sam Daoud)."}, {"fix": "Know it cold: about four years as ReachGiant, 45 to 50 clients.", "q": "How long have you been in business", "why": "Sounded unsure on the number of years (Matt Holdridge)."}, {"fix": "Say it is outside what you do and point to a CRM specialist.", "q": "Regulations on follow up and automation", "why": "General answer that skipped the actual question (Cesar Diaz)."}]}$json$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();
